window.NI_DATA = {"version":1,"updated":"2026-10-16","topics":[{"id":"programming","title":"Tư duy lập trình","group":"01 · Nền tảng","description":"Hiểu dữ liệu, luồng thực thi và cách chương trình sử dụng bộ nhớ.","sources":[{"title":"MDN JavaScript Guide","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide"}],"imageRefs":["C02"],"prerequisites":[],"notes":[{"id":"values","title":"Giá trị, biến và kiểu dữ liệu","body":["Biến là tên dùng để truy cập một giá trị; mô hình lưu trữ cụ thể phụ thuộc ngôn ngữ. Kiểu dữ liệu quyết định các phép toán hợp lệ. Static typing kiểm tra nhiều lỗi trước khi chạy; dynamic typing kiểm tra kiểu khi thực thi. Cả hai vẫn cần kiểm tra dữ liệu từ bên ngoài."],"example":"const count = 3;\nconst user = { name: \"An\" };\nconst alias = user;\nalias.name = \"Bình\"; // user.name cũng đổi","pitfall":"const ngăn gán lại binding; không tự làm object bất biến.","exercise":"Thử sao chép object có object con bằng spread rồi sửa object con."},{"id":"memory","title":"Stack, heap và truyền đối số","body":["Call stack lưu các frame của lời gọi hàm; heap thường chứa dữ liệu có vòng đời linh hoạt. Đây là mô hình khái niệm: compiler/runtime có thể tối ưu cách lưu thực tế. Đừng suy ra mọi primitive luôn trên stack hay mọi object luôn trên heap.","Java và JavaScript truyền đối số theo giá trị. Khi giá trị là tham chiếu tới object, hàm có thể sửa object chung nhưng gán lại tham số không đổi binding của bên gọi."],"example":"function change(x) { x.name = \"B\"; x = { name: \"C\" }; }\nconst a = { name: \"A\" }; change(a); // a.name === \"B\"","pitfall":"Garbage collector thu hồi dữ liệu không còn truy cập được, không bảo đảm thu hồi ngay.","exercise":"Giải thích vì sao listener còn giữ object lớn có thể gây memory leak.","diagram":{"type":"flow","title":"Hai binding cùng trỏ một object","nodes":["Biến a","Tham chiếu","Object {name: B}","Biến x cũng giữ tham chiếu"],"caption":"Gán lại x thay tham chiếu của x; sửa thuộc tính tác động object chung."}},{"id":"functions","title":"Hàm, scope và xử lý lỗi","body":["Một hàm nên có đầu vào, đầu ra và tác dụng phụ rõ ràng. Scope quyết định nơi truy cập được tên; closure giữ khả năng truy cập môi trường lexical. Exception chuyển điều khiển tới nơi xử lý lỗi phù hợp.","Phân biệt lỗi dự kiến như dữ liệu sai với lỗi lập trình. Kiểm tra đầu vào tại ranh giới, giữ nguyên nguyên nhân lỗi khi chuyển tầng và dùng finally để dọn tài nguyên khi ngôn ngữ hỗ trợ."],"example":"function counter() {\n  let n = 0;\n  return () => ++n;\n}\nconst next = counter(); // mỗi counter có môi trường riêng","pitfall":"Bắt mọi lỗi rồi trả null có thể che giấu lỗi và làm nơi gọi hiểu nhầm.","exercise":"Viết hàm parse giá tiền: xác định cách xử lý chuỗi rỗng, số âm, NaN và đơn vị tiền."},{"id":"complexity","title":"Đánh giá giải pháp bằng thời gian và bộ nhớ","body":["Big-O mô tả cận tăng trưởng khi kích thước đầu vào tăng, không phải số mili giây chính xác. Cần ghi rõ kích thước n, trường hợp đang xét và bộ nhớ phụ. Hai vòng lặp nối tiếp thường là O(n); hai vòng lặp lồng nhau duyệt toàn bộ thường là O(n²)."],"example":"// O(n) thời gian, O(n) bộ nhớ phụ\nconst seen = new Set();\nfor (const x of values) {\n  if (seen.has(x)) return true;\n  seen.add(x);\n}","pitfall":"Hash lookup thường O(1) trung bình; không phải bảo đảm O(1) trong mọi implementation.","exercise":"So sánh tìm phần tử trùng bằng hai vòng lặp, sort và Set."}],"questions":[{"id":"typing","question":"Static typing có loại bỏ lỗi runtime không?","answer":"Không. Nó phát hiện một nhóm lỗi trước khi chạy; lỗi I/O, dữ liệu sai và logic vẫn tồn tại.","explanation":"Dữ liệu JSON từ API cần được xác thực lúc chạy ngay cả khi code dùng TypeScript.","followUp":"Bạn kiểm tra response từ API ở đâu?","note":"values","level":"Cơ bản"},{"id":"mutable","question":"Mutable và immutable khác nhau thế nào?","answer":"Mutable cho phép đổi trạng thái của giá trị; immutable yêu cầu tạo giá trị mới khi thay đổi.","explanation":"Bất biến giúp theo dõi thay đổi và chia sẻ dữ liệu, nhưng sao chép có chi phí cần cân nhắc.","followUp":"Object.freeze có làm bất biến toàn bộ object con không?","note":"values","level":"Cơ bản"},{"id":"pass","question":"JavaScript truyền object theo tham chiếu đúng không?","answer":"Chính xác hơn: truyền theo giá trị, trong đó giá trị truyền có thể là tham chiếu tới object.","explanation":"Sửa object qua tham số thấy được ở bên gọi; gán object mới cho tham số thì không đổi binding bên gọi.","followUp":"Cho một đoạn code chứng minh hai hành vi này.","note":"memory","level":"Cơ bản"},{"id":"gc","question":"Có GC thì còn memory leak không?","answer":"Có, khi chương trình giữ tham chiếu tới dữ liệu không còn cần thiết.","explanation":"Ví dụ cache không giới hạn, listener không gỡ hoặc timer giữ closure lớn. GC không biết mục đích nghiệp vụ.","followUp":"Bạn kiểm tra heap tăng liên tục bằng cách nào?","note":"memory","level":"Cơ bản"},{"id":"closure","question":"Closure là gì và dùng khi nào?","answer":"Là hàm cùng khả năng truy cập môi trường lexical nơi nó được tạo.","explanation":"Có thể tạo factory, giữ trạng thái riêng hoặc callback; cũng cần chú ý dữ liệu bị giữ lâu.","followUp":"Hai counter tạo từ cùng factory có dùng chung n không?","note":"functions","level":"Cơ bản"},{"id":"error","question":"Khi nào trả lỗi và khi nào throw?","answer":"Tùy hợp đồng API: kết quả lỗi rõ ràng phù hợp lỗi dự kiến; exception phù hợp cơ chế truyền lỗi của hệ thống.","explanation":"Quan trọng là nhất quán, không nuốt lỗi và không biến lỗi hệ thống thành thành công.","followUp":"Bạn phân biệt validation error và lỗi mất kết nối DB thế nào?","note":"functions","level":"Vận dụng"},{"id":"recursion","question":"Đệ quy cần điều kiện gì?","answer":"Có trường hợp dừng và mỗi bước phải tiến gần hơn tới trường hợp dừng.","explanation":"Cần xét độ sâu stack; dữ liệu sâu có thể cần stack tường minh hoặc vòng lặp.","followUp":"Fibonacci đệ quy thuần vì sao chậm?","note":"complexity","level":"Cơ bản"},{"id":"big-o","question":"Hai thuật toán O(n) có nhanh bằng nhau không?","answer":"Không. Big-O bỏ qua nhiều hằng số và chi phí thực tế.","explanation":"Cache locality, cấp phát, I/O và kích thước dữ liệu ảnh hưởng thời gian chạy. Đo trên workload đại diện.","followUp":"Khi nào thuật toán O(n log n) vẫn nhanh hơn trên input nhỏ?","note":"complexity","level":"Cơ bản"},{"id":"copy","question":"Shallow copy và deep copy khác nhau thế nào?","answer":"Shallow copy sao chép tầng ngoài; các object lồng nhau vẫn có thể được chia sẻ.","explanation":"Deep copy cần xử lý chu kỳ và kiểu đặc biệt. JSON stringify/parse không bảo toàn mọi kiểu dữ liệu.","followUp":"Date, undefined và vòng tham chiếu gây vấn đề gì?","note":"memory","level":"Cơ bản"},{"id":"pure","question":"Hàm thuần giúp kiểm thử thế nào?","answer":"Cùng đầu vào cho cùng đầu ra và không có tác dụng phụ quan sát được.","explanation":"Tách tính toán khỏi database, clock và network giúp test đơn giản, ổn định hơn.","followUp":"Bạn truyền thời gian hiện tại vào hàm tính hạn dùng thế nào?","note":"functions","level":"Cơ bản"}],"order":1},{"id":"oop","title":"OOP & thiết kế code","group":"01 · Nền tảng","description":"Từ object đến interface, SOLID và các pattern có lý do sử dụng.","sources":[{"title":"Refactoring Guru — Design Patterns","url":"https://refactoring.guru/design-patterns"},{"title":"Java classes","url":"https://dev.java/learn/classes-objects/"}],"imageRefs":["C03","A05"],"prerequisites":["programming"],"notes":[{"id":"pillars","title":"Bốn ý tưởng OOP và giới hạn của kế thừa","body":["Đóng gói bảo vệ bất biến của object qua API; trừu tượng tập trung vào hợp đồng cần dùng; kế thừa biểu diễn quan hệ thay thế hợp lệ; đa hình cho phép gọi cùng hợp đồng với implementation khác nhau.","Quan hệ “is-a” chưa đủ: subtype phải giữ kỳ vọng hành vi của nơi gọi. Composition ghép các năng lực thông qua object cộng tác, thường linh hoạt hơn cây kế thừa sâu."],"example":"interface Sender { send(message: string): Promise\u003cvoid> }\nclass Notification {\n  constructor(private sender: Sender) {}\n  deliver(text: string) { return this.sender.send(text); }\n}","pitfall":"Không tạo lớp chỉ để làm code có vẻ hướng đối tượng.","exercise":"Thiết kế gửi thông báo qua email và SMS mà không sửa logic tạo nội dung."},{"id":"contracts","title":"Interface, abstract class và dependency injection","body":["Interface mô tả hợp đồng; abstract class có thể chia sẻ trạng thái và implementation theo khả năng ngôn ngữ. Dependency injection đưa dependency từ ngoài vào thay vì tự khởi tạo sâu trong logic.","Một service phụ thuộc PaymentGateway sẽ dễ test bằng fake hơn service tự new SDK ngân hàng. DI không bắt buộc dùng framework; constructor injection đã là DI."],"example":"class Checkout {\n  constructor(private gateway: PaymentGateway) {}\n  pay(order: Order) { return this.gateway.charge(order.total); }\n}","pitfall":"Interface quá lớn buộc client phụ thuộc chức năng không dùng.","exercise":"Tách interface read-only khỏi interface quản trị có quyền ghi."},{"id":"solid","title":"SOLID như câu hỏi thiết kế","body":["SRP: một nhóm lý do thay đổi gắn kết. OCP: mở rộng tại điểm biến thiên. LSP: subtype giữ hợp đồng. ISP: interface theo nhu cầu client. DIP: policy cấp cao phụ thuộc abstraction phù hợp.","Áp dụng theo chi phí thay đổi thực tế. Tách mọi hàm thành interface và factory có thể làm hệ thống khó đọc hơn. Kiểm tra xem thiết kế giúp thêm yêu cầu hoặc test dễ hơn ở điểm nào."],"example":"// Strategy: thay thuật toán tính phí\nconst shippingFee = strategies[order.shippingMethod](order);","pitfall":"SOLID không phải tiêu chí đếm số class hay số file.","exercise":"Thêm phương thức giao hàng mới và chỉ ra những file phải thay đổi."},{"id":"patterns","title":"Pattern giải quyết vấn đề cụ thể","body":["Strategy thay thuật toán; Adapter đổi hợp đồng; Factory tách việc tạo object; Observer thông báo thay đổi; Decorator thêm hành vi; Repository gom truy cập dữ liệu. Pattern giúp gọi tên thiết kế, không thay thế phân tích yêu cầu.","Singleton có thể làm dependency ẩn và trạng thái test rò rỉ. Repository không nhất thiết phải che hết tính năng truy vấn của database bằng một interface CRUD chung."],"example":"// Adapter giữ service khỏi phụ thuộc response riêng của nhà cung cấp\nreturn { trackingId: vendorResult.shipment_code };","pitfall":"Đừng mặc định mọi pattern đều phải có ở một ứng dụng nhỏ.","exercise":"Chọn Strategy hoặc if đơn giản cho ba loại giảm giá; giải thích trade-off.","diagram":{"type":"flow","title":"Đảo chiều phụ thuộc","nodes":["Checkout policy","PaymentGateway interface","Adapter ngân hàng","API bên ngoài"],"caption":"Logic thanh toán phụ thuộc hợp đồng; adapter chịu trách nhiệm tích hợp nhà cung cấp."}}],"questions":[{"id":"class","question":"Class và object khác nhau thế nào?","answer":"Class mô tả cấu trúc/hành vi; object là một instance có trạng thái cụ thể.","explanation":"Trong ngôn ngữ prototype như JavaScript, class là một cú pháp trên cơ chế prototype chứ không giống hoàn toàn Java.","followUp":"Hai instance có chia sẻ thuộc tính instance không?","note":"pillars","level":"Cơ bản"},{"id":"encapsulation","question":"Đóng gói có phải chỉ là private field?","answer":"Không. Mục tiêu là giữ các bất biến bằng một API kiểm soát thay đổi.","explanation":"Tài khoản không nên cho sửa balance tùy ý; deposit/withdraw kiểm tra điều kiện nghiệp vụ.","followUp":"Bạn bảo vệ số dư không âm ở tầng nào nữa?","note":"pillars","level":"Cơ bản"},{"id":"composition","question":"Khi nào chọn composition thay kế thừa?","answer":"Khi cần ghép hoặc thay hành vi độc lập và không có quan hệ thay thế bền vững.","explanation":"Ví dụ dịch vụ dùng Sender được inject dễ thay hơn kế thừa EmailService để tạo SmsService.","followUp":"Composition có tạo nhiều object hơn không và có đáng không?","note":"pillars","level":"Cơ bản"},{"id":"overload","question":"Overloading khác overriding ra sao?","answer":"Overloading có cùng tên với chữ ký khác; overriding thay implementation kế thừa theo quy tắc ngôn ngữ.","explanation":"JavaScript không có method overload theo chữ ký runtime như Java.","followUp":"Dispatch của overriding được quyết định khi nào?","note":"pillars","level":"Cơ bản"},{"id":"interface","question":"Interface khác abstract class thế nào?","answer":"Interface tập trung hợp đồng; abstract class có thể cung cấp code và trạng thái chung.","explanation":"Khả năng cụ thể phụ thuộc ngôn ngữ; tránh học bảng so sánh áp dụng chung cho tất cả.","followUp":"Khi cần nhiều implementation độc lập bạn chọn gì?","note":"contracts","level":"Cơ bản"},{"id":"di","question":"Dependency injection có cần container không?","answer":"Không. Truyền dependency qua constructor hoặc tham số đã là DI.","explanation":"Container chỉ tự động quản lý việc nối và vòng đời dependency.","followUp":"DI hỗ trợ thay clock và database trong test thế nào?","note":"contracts","level":"Cơ bản"},{"id":"lsp","question":"Một ví dụ vi phạm LSP là gì?","answer":"Subtype yêu cầu điều kiện đầu vào chặt hơn hoặc không giữ hậu điều kiện mà client dựa vào.","explanation":"Ví dụ implementation read-only của một interface hứa hỗ trợ write nhưng luôn throw khi write.","followUp":"Bạn sửa hợp đồng thay vì thêm kiểm tra subtype thế nào?","note":"solid","level":"Cơ bản"},{"id":"strategy","question":"Strategy khác một if/else thế nào?","answer":"Strategy đưa các thuật toán cùng hợp đồng thành phần có thể thay thế.","explanation":"if/else vẫn phù hợp khi số nhánh ít, ổn định; abstraction có chi phí.","followUp":"Dấu hiệu nào cho thấy nên tách Strategy?","note":"patterns","level":"Cơ bản"},{"id":"singleton","question":"Singleton có nhược điểm gì?","answer":"Dependency và trạng thái toàn cục khó kiểm soát, khó cô lập test.","explanation":"Một instance trong một process không đồng nghĩa một instance toàn hệ phân tán.","followUp":"Nhiều replica ứng dụng có bao nhiêu singleton?","note":"patterns","level":"Cơ bản"},{"id":"repository","question":"Repository có tác dụng gì?","answer":"Tạo ranh giới truy cập và lưu trữ dữ liệu cho logic nghiệp vụ.","explanation":"Cần giữ khả năng truy vấn hiệu quả; abstraction không nên gây N+1 hoặc che mất transaction.","followUp":"Transaction đi qua nhiều repository được quản lý ở đâu?","note":"patterns","level":"Cơ bản"}],"order":2},{"id":"dsa","title":"DSA & mẫu giải bài toán","group":"01 · Nền tảng","description":"Chọn cấu trúc dữ liệu và nhận diện kỹ thuật giải trước khi viết code.","sources":[{"title":"MIT 6.006","url":"https://ocw.mit.edu/courses/6-006-introduction-to-algorithms-spring-2020/"}],"imageRefs":["C04–C09"],"prerequisites":["programming"],"notes":[{"id":"structures","title":"Chọn cấu trúc theo thao tác","body":["Array truy cập theo chỉ số nhanh, nhưng chèn giữa thường phải dịch phần tử. Linked list nối node linh hoạt nhưng tìm node vẫn O(n). Stack dùng LIFO; queue dùng FIFO; heap lấy phần tử ưu tiên; hash map tra theo khóa.","Cần xét implementation: queue bằng array.shift trong JavaScript có thể phải dịch phần tử. Dùng chỉ số head hoặc deque khi cần dequeue hiệu quả."],"example":"","pitfall":"BST không cân bằng có thể suy biến thành danh sách và tìm kiếm O(n).","exercise":"Thiết kế LRU cache: vì sao kết hợp hash map và doubly linked list?","table":{"headers":["Cấu trúc","Mạnh ở","Điểm cần nhớ"],"rows":[["Array","Index O(1)","Chèn giữa O(n)"],["Hash map","Lookup trung bình O(1)","Hash collision, bộ nhớ"],["Heap","Min/max O(1), insert O(log n)","Không hỗ trợ tìm tùy ý nhanh"],["BST cân bằng","Search/insert O(log n)","Cần duy trì cân bằng"]]}},{"id":"patterns","title":"Two pointers, sliding window và binary search","body":["Two pointers tận dụng thứ tự hoặc hai vị trí tiến dần để tránh xét mọi cặp. Sliding window duy trì thông tin của đoạn liên tiếp; không phải điều kiện nào cũng cho phép bỏ trái/phải một cách đơn điệu. Binary search tìm trên miền có thứ tự hoặc một predicate đơn điệu."],"example":"// lower_bound: vị trí đầu tiên a[i] >= target\nlet lo = 0, hi = a.length;\nwhile (lo \u003c hi) {\n  const mid = lo + Math.floor((hi - lo) / 2);\n  if (a[mid] \u003c target) lo = mid + 1; else hi = mid;\n}","pitfall":"Sliding window cho tổng với số âm thường cần kỹ thuật khác; đừng áp công thức của số dương.","exercise":"Viết invariant cho binary search và test array rỗng, một phần tử, toàn phần tử trùng."},{"id":"graphs","title":"Cây, đồ thị, BFS và DFS","body":["BFS khám phá theo lớp, cho đường đi ít cạnh nhất trong graph không trọng số. DFS đi sâu, phù hợp duyệt thành phần, phát hiện chu kỳ và topological sort theo điều kiện. Graph có hướng và vô hướng cần xử lý cạnh cha khác nhau khi tìm cycle.","Dijkstra yêu cầu trọng số không âm; Bellman–Ford xử lý cạnh âm và phát hiện chu kỳ âm có thể tới được. Union-Find hỗ trợ truy vấn kết nối động và Kruskal."],"example":"","pitfall":"Đánh dấu visited đúng thời điểm để tránh thêm node nhiều lần. Độ phức tạp adjacency list thường O(V + E) cho BFS/DFS.","exercise":"Tìm đường đi trên lưới và phục hồi đường bằng mảng parent.","diagram":{"type":"flow","title":"BFS theo từng lớp","nodes":["Bắt đầu A","Lớp 1: B, C","Lớp 2: D, E","Dùng queue + visited"],"caption":"Mỗi cạnh có cùng trọng số thì số lớp cho khoảng cách ngắn nhất tính theo cạnh."}},{"id":"dp","title":"Đệ quy, backtracking và quy hoạch động","body":["Backtracking thử lựa chọn, đi tiếp rồi hoàn tác trạng thái. DP dùng trạng thái và chuyển trạng thái để tái sử dụng kết quả bài toán con. Memoization tính khi cần theo top-down; tabulation tính theo thứ tự phụ thuộc bottom-up.","Bắt đầu bằng định nghĩa dp[i] đại diện điều gì, base case, công thức chuyển và thứ tự tính. Tối ưu bộ nhớ sau khi đã chứng minh đúng. Greedy chỉ đúng khi có lập luận về lựa chọn cục bộ."],"example":"// Số cách leo n bậc, mỗi bước 1 hoặc 2 bậc\nlet prev = 1, curr = 1;\nfor (let i = 2; i \u003c= n; i++) [prev, curr] = [curr, prev + curr];","pitfall":"Không dùng DP chỉ vì bài có đệ quy; cần bài toán con trùng và cấu trúc tối ưu phù hợp.","exercise":"Giải Coin Change với mệnh giá 1, 3, 4 và tổng 6; chứng minh greedy chọn 4 rồi 1 rồi 1 không tối ưu."},{"id":"sorting","title":"Sorting và độ ổn định","body":["Merge sort có O(n log n) theo mô hình thông dụng và thường cần bộ nhớ phụ; quicksort trung bình O(n log n) nhưng có worst case O(n²) nếu không có biện pháp bảo vệ; heap sort có worst case O(n log n) và không ổn định theo implementation chuẩn. Stable sort giữ thứ tự tương đối của item có khóa bằng nhau.","Sorting cần comparator nhất quán. JavaScript Array.sort mặc định so theo chuỗi; sort((a,b)=>a-b) phù hợp số hữu hạn thông thường. Đừng trộn mutate input với kỳ vọng hàm thuần."],"example":"const sorted = [...values].sort((a, b) => a - b);\n// Giữ array gốc; comparator cho số cần policy riêng nếu có NaN.","pitfall":"","exercise":"Sắp nhân viên theo phòng rồi lương: tie-breaker và stable sort khác nhau thế nào?"},{"id":"trees","title":"BST, traversal và heap qua hình","body":["BST giữ invariant thứ tự cho toàn subtree, không chỉ child trực tiếp. Inorder trên BST đúng cho thứ tự tăng theo quy ước duplicate. Preorder thăm node trước child; postorder thăm sau child; level-order dùng BFS.","Height/depth cần nêu quy ước đếm cạnh hay node. Để validate BST, truyền khoảng hợp lệ hoặc theo dõi inorder; chỉ so node với hai child là chưa đủ. Heap không có invariant trái nhỏ phải lớn như BST."],"example":"","pitfall":"","exercise":"Thêm node 9 làm con phải của 6: so cha-con có vẻ đúng nhưng BST toàn cây còn đúng không?","diagram":{"type":"graph","title":"BST: inorder cho 2, 4, 6, 8, 10, 12","nodes":[[320,50,"8"],[170,150,"4"],[470,150,"12"],[80,250,"2"],[245,250,"6"],[420,250,"10"]],"edges":[[0,1],[0,2],[1,3],[1,4],[2,5]],"caption":"Mọi node trong subtree trái của 8 nhỏ hơn 8; invariant áp dụng xuống toàn subtree."}},{"id":"hash-linked","title":"Hash map, linked list và LRU","body":["LRU giữ item dùng gần nhất. Hash map ánh xạ key→node để tìm nhanh; doubly linked list hỗ trợ bỏ/thêm node ở đầu/cuối khi đã có node. GET hit đưa node lên đầu; PUT cập nhật/đưa lên đầu; quá capacity loại node cuối.","Giữ invariant map và list cùng chứa các key tương ứng, xử lý capacity 0, update key cũ và singleton list. O(1) kỳ vọng phụ thuộc hash map; thread safety/distributed cache là bài toán bổ sung."],"example":"","pitfall":"","exercise":"Viết test GET key không có, update key cũ, eviction đúng và capacity 1."},{"id":"dp-example","title":"Một bài DP hoàn chỉnh: số đồng xu ít nhất","body":["Định nghĩa dp[x] là số đồng ít nhất để tạo tổng x, hoặc vô cực nếu chưa tạo được. Base dp[0]=0. Với mỗi tổng x, thử đồng c\u003c=x: dp[x]=min(dp[x],dp[x-c]+1). Thứ tự tăng của x cho phép dùng lại đồng nhiều lần.","Thời gian O(amount × số mệnh giá), bộ nhớ O(amount). Nếu mỗi đồng chỉ được dùng một lần thì thứ tự/định nghĩa phải thay; không dùng nguyên công thức thiếu phân tích."],"example":"function minCoins(coins, amount) {\n  const dp = Array(amount + 1).fill(Infinity);\n  dp[0] = 0;\n  for (let x = 1; x \u003c= amount; x++) {\n    for (const c of coins) if (c > 0 && c \u003c= x)\n      dp[x] = Math.min(dp[x], dp[x - c] + 1);\n  }\n  return Number.isFinite(dp[amount]) ? dp[amount] : -1;\n}\n// coins phải là số nguyên dương; amount là số nguyên không âm.\nminCoins([1, 3, 4], 6); // 2: 3 + 3","pitfall":"","exercise":"Đổi bài thành đếm số cách: giải thích vì sao thứ tự vòng lặp có thể đổi cách đếm."}],"questions":[{"id":"hash","question":"Hash collision xử lý như thế nào?","answer":"Chaining hoặc open addressing là hai họ kỹ thuật phổ biến.","explanation":"Hiệu năng phụ thuộc hàm hash, load factor và resize; cần phân biệt expected với worst case.","followUp":"Khi nào hash map mất lợi thế so với cây cân bằng?","note":"structures","level":"Cơ bản"},{"id":"list","question":"Xóa node linked list có luôn O(1) không?","answer":"Không. Chỉ sửa liên kết có thể O(1) nếu đã có thông tin cần thiết; tìm node/previous có thể O(n).","explanation":"Doubly linked list cho phép cập nhật hai phía khi có node, nhưng tốn thêm bộ nhớ.","followUp":"Xóa node cuối singly linked list cần gì?","note":"structures","level":"Cơ bản"},{"id":"heap","question":"Heap khác BST ra sao?","answer":"Heap giữ quan hệ ưu tiên cha-con; BST giữ thứ tự trái–node–phải.","explanation":"Heap phù hợp top K và priority queue; không bảo đảm tìm giá trị bất kỳ O(log n).","followUp":"Top K streaming cần min heap hay max heap?","note":"structures","level":"Cơ bản"},{"id":"binary","question":"Binary search cần điều kiện gì?","answer":"Miền tìm kiếm có thứ tự hoặc predicate đơn điệu để loại được một nửa mỗi bước.","explanation":"Cần invariant rõ và bảo đảm khoảng thu hẹp; đây là nguồn lỗi off-by-one phổ biến.","followUp":"Tìm vị trí đầu tiên của phần tử trùng thế nào?","note":"patterns","level":"Cơ bản"},{"id":"window","question":"Khi nào dùng sliding window?","answer":"Khi xét đoạn liên tiếp và có thể cập nhật điều kiện khi dịch biên hiệu quả.","explanation":"Ví dụ longest substring không lặp dùng map vị trí; bài tổng có số âm không tự có tính đơn điệu.","followUp":"Khác gì với prefix sum?","note":"patterns","level":"Vận dụng"},{"id":"bfs","question":"BFS có tìm đường ngắn nhất cho mọi graph không?","answer":"Không. BFS chuẩn phù hợp cạnh cùng trọng số, đặc biệt graph không trọng số.","explanation":"Với trọng số 0/1 có 0–1 BFS; tổng quát cạnh không âm có Dijkstra.","followUp":"Khi có cạnh âm bạn cân nhắc thuật toán nào?","note":"graphs","level":"Cơ bản"},{"id":"cycle","question":"Tìm cycle trong linked list mà không dùng Set thế nào?","answer":"Dùng Floyd với hai con trỏ đi tốc độ khác nhau.","explanation":"Nếu có chu kỳ, chúng sẽ gặp; sau đó có thể tìm đầu chu kỳ bằng bước di chuyển thích hợp.","followUp":"Độ phức tạp thời gian và bộ nhớ là gì?","note":"structures","level":"Cơ bản"},{"id":"dp","question":"Memoization khác tabulation thế nào?","answer":"Memoization tính đệ quy khi cần; tabulation điền bảng theo thứ tự phụ thuộc.","explanation":"Top-down dễ chuyển từ recurrence; bottom-up tránh call stack và thường dễ tối ưu bộ nhớ.","followUp":"Trạng thái nào không cần tính nếu dùng memoization?","note":"dp","level":"Vận dụng"},{"id":"greedy","question":"Làm sao biết greedy đúng?","answer":"Cần chứng minh lựa chọn cục bộ không loại lời giải tối ưu, thường qua exchange argument.","explanation":"Một vài ví dụ chạy đúng không đủ; Coin Change với bộ tiền bất kỳ là phản ví dụ quen thuộc.","followUp":"Hãy tìm phản ví dụ cho một greedy bạn đang đề xuất.","note":"dp","level":"Vận dụng"},{"id":"approach","question":"Nên trình bày bài coding interview thế nào?","answer":"Làm rõ input, ví dụ và edge case; nêu baseline, cải thiện, chứng minh rồi viết và kiểm tra code.","explanation":"Nói rõ time/space complexity và những giả định như thứ tự, mutation, Unicode hoặc số lớn.","followUp":"Bạn test gì trước khi kết luận đúng?","note":"patterns","level":"Vận dụng"},{"id":"stable","question":"Stable sort nghĩa là gì?","answer":"Các phần tử bằng khóa giữ thứ tự tương đối ban đầu.","explanation":"Hữu ích khi sort nhiều tiêu chí hoặc dữ liệu cần thứ tự tie ổn định; vẫn cần biết semantics implementation.","followUp":"Stable có đồng nghĩa in-place không?","note":"sorting","level":"Vận dụng"},{"id":"quicksort","question":"Quicksort có luôn O(n log n) không?","answer":"Không. Phân hoạch lệch có thể cho O(n²) trong implementation không bảo vệ.","explanation":"Pivot strategy và introsort là cách thực tế giảm rủi ro; phân biệt expected và worst case.","followUp":"Input đã sorted tác động implementation chọn pivot đầu thế nào?","note":"sorting","level":"Vận dụng"},{"id":"validatebst","question":"Validate BST bằng so từng node với hai child đã đủ chưa?","answer":"Chưa. Invariant phải đúng với toàn subtree.","explanation":"Dùng khoảng min/max theo đường đi hoặc inorder với quy tắc duplicate rõ.","followUp":"Một node 9 nằm trong subtree trái của root 8 thì sao?","note":"trees","level":"Vận dụng"},{"id":"lca","question":"Tìm LCA trong BST có thể tận dụng gì?","answer":"So hai giá trị với node để đi trái/phải tới điểm phân nhánh, theo giả định node tồn tại và key phù hợp.","explanation":"Với binary tree thường cần thuật toán khác; duplicate và identity phải rõ.","followUp":"Nếu một node không tồn tại thì hợp đồng trả gì?","note":"trees","level":"Vận dụng"},{"id":"balance","question":"Kiểm tra cây cân bằng tối ưu thế nào?","answer":"Tính height bottom-up một lần và trả tín hiệu mất cân bằng khi chênh lệch vượt ngưỡng.","explanation":"Tính height lại ở mỗi node có thể O(n²); postorder có thể O(n).","followUp":"Độ sâu cây có gây stack overflow không?","note":"trees","level":"Vận dụng"},{"id":"topk","question":"Tìm K phần tử lớn nhất trong stream bằng gì?","answer":"Giữ min heap kích thước K, loại phần tử nhỏ nhất khi vượt K.","explanation":"Thời gian O(n log K), bộ nhớ O(K) theo heap chuẩn; output có cần sort thêm tùy hợp đồng.","followUp":"Nếu K=0 hoặc lớn hơn n thì sao?","note":"structures","level":"Vận dụng"},{"id":"twosum","question":"Two Sum dùng hash map như thế nào?","answer":"Duyệt mỗi x, tìm target-x trong map đã thấy, rồi lưu x nếu chưa có cặp.","explanation":"Tra trước khi lưu giúp không dùng cùng index hai lần; xử lý duplicate theo yêu cầu.","followUp":"Nếu cần mọi cặp thay một cặp thì thay đổi gì?","note":"patterns","level":"Vận dụng"},{"id":"prefix","question":"Prefix sum hữu ích khi nào?","answer":"Khi cần tính tổng đoạn nhanh sau tiền xử lý hoặc đếm đoạn theo tổng với map.","explanation":"Sum[l..r] suy từ hiệu prefix; overflow và số âm cần xét.","followUp":"Tổng đoạn bằng K với số âm dùng map ra sao?","note":"patterns","level":"Vận dụng"},{"id":"parentheses","question":"Valid parentheses thường dùng cấu trúc gì?","answer":"Stack lưu dấu mở; mỗi dấu đóng phải khớp đỉnh stack.","explanation":"Kết thúc stack rỗng và không có mismatch; không chỉ đếm số lượng dấu.","followUp":"Chuỗi ([)] vì sao đếm đúng mà vẫn sai?","note":"structures","level":"Vận dụng"},{"id":"reverse","question":"Đảo singly linked list lặp cần giữ những gì?","answer":"prev, current và next trước khi đổi current.next.","explanation":"Đổi link rồi quên lưu next làm mất phần còn lại; chạy O(n) thời gian và O(1) bộ nhớ phụ.","followUp":"List rỗng và một node xử lý thế nào?","note":"hash-linked","level":"Vận dụng"},{"id":"topological","question":"Topological sort áp dụng cho graph nào?","answer":"Directed acyclic graph, để mọi cạnh u→v có u trước v.","explanation":"Có thể dùng indegree/Kahn hoặc DFS với cycle detection; graph có cycle không có thứ tự hợp lệ.","followUp":"Ứng dụng vào dependency build thế nào?","note":"graphs","level":"Vận dụng"},{"id":"unionfind","question":"Union-Find dùng để làm gì?","answer":"Quản lý các tập rời nhau và truy vấn hai phần tử có cùng tập không.","explanation":"Path compression và union by rank/size cải thiện amortized cost; không trả đường đi graph trực tiếp.","followUp":"Kruskal dùng nó phát hiện điều gì?","note":"graphs","level":"Vận dụng"},{"id":"backtrack","question":"Backtracking cần hoàn tác gì?","answer":"Mọi trạng thái dùng chung đã thay đổi cho lựa chọn hiện tại trước khi thử nhánh khác.","explanation":"Có thể copy state thay undo nhưng có chi phí; pruning phải giữ tính đúng.","followUp":"N-Queens dùng tập cột và đường chéo như thế nào?","note":"dp","level":"Vận dụng"},{"id":"lcs","question":"LCS khác longest common substring thế nào?","answer":"Subsequence không cần liên tiếp; substring phải liên tiếp.","explanation":"Hai bài có state/transition khác; không dùng chung kết quả chỉ vì cùng chữ longest common.","followUp":"Khi ký tự cuối không khớp, LCS xét nhánh nào?","note":"dp","level":"Vận dụng"},{"id":"coin","question":"Vì sao greedy sai với coins 1,3,4 và tổng 6?","answer":"Greedy chọn 4+1+1 ba đồng, nhưng 3+3 chỉ hai đồng.","explanation":"DP xét đầy đủ subproblem theo recurrence; cần chứng minh thay vì suy từ bộ tiền quen thuộc.","followUp":"Nếu chỉ có một đồng mỗi loại thì recurrence đổi thế nào?","note":"dp-example","level":"Vận dụng"}],"order":3},{"id":"os","title":"OS, bộ nhớ & đồng thời","group":"01 · Nền tảng","description":"Từ syscall, tiến trình đến scheduling, đồng bộ và deadlock.","sources":[{"title":"OSTEP","url":"https://pages.cs.wisc.edu/~remzi/OSTEP/"}],"imageRefs":["B01–B20","A16","D16"],"prerequisites":["programming"],"notes":[{"id":"process","title":"Kernel, process và thread","body":["Kernel quản lý tài nguyên và quyền truy cập. Syscall là một giao diện để chương trình yêu cầu dịch vụ kernel; thư viện có thể bao syscall hoặc xử lý hoàn toàn ở user space. Process có không gian địa chỉ; các thread trong process chia sẻ nhiều tài nguyên nhưng có stack và trạng thái thực thi riêng.","Context switch lưu/khôi phục trạng thái và có chi phí gián tiếp lên cache. Đồng thời là nhiều tác vụ cùng tiến triển; song song là thực thi cùng lúc trên nhiều đơn vị xử lý."],"example":"","pitfall":"Một CPU core không đồng nghĩa máy chỉ có một process. Nhiều thread không bảo đảm chương trình nhanh hơn.","exercise":"So sánh CPU-bound với I/O-bound trước khi chọn process, thread hoặc async.","diagram":{"type":"flow","title":"Vòng đời process","nodes":["Ready · chờ CPU","Running · đang chạy","Waiting · chờ I/O","Ready · được đánh thức"],"caption":"Preemption đưa Running về Ready; kết thúc chuyển sang Terminated. Đây là sơ đồ vòng lặp giản lược."}},{"id":"scheduling","title":"Scheduling và tạo process","body":["FCFS đơn giản nhưng có convoy effect. SJF tối ưu một số chỉ số khi biết burst time; thực tế phải ước lượng. Round Robin chia time quantum: quá nhỏ tăng overhead, quá lớn gần FCFS. Priority scheduling cần cơ chế như aging để giảm starvation.","Trên Unix, fork tạo child với không gian địa chỉ logic riêng, thường dùng copy-on-write; exec thay chương trình trong process. wait thu trạng thái child đã kết thúc. Zombie khác process còn đang chạy."],"example":"","pitfall":"Orphan không đồng nghĩa zombie. Ready khác Waiting: Ready có thể chạy khi được cấp CPU.","exercise":"Tính waiting time và turnaround cho ba process bằng FCFS và Round Robin."},{"id":"memory","title":"Bộ nhớ ảo, paging và file system","body":["Virtual memory cung cấp không gian địa chỉ cho process; page table ánh xạ trang ảo sang frame vật lý, TLB cache bản dịch. Page fault có thể do trang chưa resident, cấp phát theo nhu cầu hoặc truy cập không hợp lệ, không luôn là lỗi chương trình.","File descriptor là handle tài nguyên mở trong process; inode lưu metadata trong nhiều file system Unix. Page cache giúp giảm I/O. Buffer ghi và journaling cần được hiểu cùng yêu cầu durability, không mặc định write trả về là dữ liệu đã bền trên thiết bị."],"example":"","pitfall":"RSS tăng có thể do cache, allocation hoặc leak; cần đo và phân biệt.","exercise":"Giải thích vì sao đọc cùng file lần hai thường nhanh hơn lần đầu."},{"id":"sync","title":"Đồng bộ, deadlock và bài toán kinh điển","body":["Race condition xảy ra khi kết quả phụ thuộc interleaving không kiểm soát. Mutex bảo vệ critical section; semaphore đếm quyền truy cập; condition variable hỗ trợ đợi một predicate, thường kiểm tra trong vòng while dưới lock. Monitor đóng gói trạng thái và đồng bộ.","Deadlock có bốn điều kiện Coffman: mutual exclusion, hold-and-wait, no preemption, circular wait. Thứ tự lấy lock thống nhất có thể phá circular wait. Banker kiểm tra trạng thái an toàn dưới giả định biết nhu cầu tối đa; unsafe không tự động có nghĩa đang deadlock."],"example":"// Pseudocode producer-consumer có bounded buffer\nproducer: wait(empty); lock(m); put(item); unlock(m); signal(full);\nconsumer: wait(full); lock(m); get(item); unlock(m); signal(empty);","pitfall":"Không chờ empty/full khi đang giữ mutex của buffer; có thể chặn bên cần tạo tiến triển. Mutex thực tế không phải luôn busy-wait.","exercise":"Mô phỏng hai thread lấy lock A/B theo thứ tự ngược nhau; sửa bằng thứ tự thống nhất."},{"id":"architectures","title":"Các loại OS, kernel và system call","body":["Batch, time-sharing, real-time và embedded mô tả các mục tiêu/kiểu phục vụ có thể chồng lấn. Hard real-time cần đáp ứng deadline theo guarantee thiết kế; soft real-time chấp nhận một mức trễ. Không phải mọi hệ nhanh đều real-time.","Monolithic kernel đặt nhiều dịch vụ trong kernel; microkernel giữ core nhỏ hơn và nhiều dịch vụ ngoài kernel, đổi chi phí IPC và isolation. Modular và hybrid là các cách tổ chức thực tế, không một trục xếp loại tuyệt đối. Syscall có overhead, kiểm tra tham số và privilege transition; library function có thể không vào kernel."],"example":"","pitfall":"","exercise":"So sánh crash driver ở các mô hình kernel mà không khẳng định một mô hình luôn nhanh hơn."},{"id":"memory-map","title":"Một ánh xạ bộ nhớ giản lược","body":["Một process có code/data, heap và các stack theo mô hình phổ biến; address space là virtual và không bảo đảm toàn bộ resident trong RAM. Page table nối virtual page với physical frame theo permission. TLB cache bản dịch; miss TLB khác page fault.","Swap, demand paging và copy-on-write là các cơ chế khác nhau. Page replacement như FIFO/LRU/Clock là mô hình cần phân biệt với policy thực tế của OS. Working set quá lớn so với RAM có thể gây thrashing, khi nhiều thời gian dùng cho chuyển trang."],"example":"","pitfall":"","exercise":"Phân biệt TLB miss, minor/major page fault theo ngữ cảnh OS và invalid memory access.","diagram":{"type":"graph","title":"Dịch địa chỉ ảo qua page table","nodes":[[110,65,"Virtual page"],[330,65,"Page table"],[530,65,"RAM frame"],[330,180,"TLB cache"]],"edges":[[0,1],[1,2],[0,3],[3,2]],"caption":"Đây là các đường khái niệm tra cứu, không phải mọi request đi qua bốn bước nối tiếp. TLB hit có thể bỏ qua page-table walk."}},{"id":"classical","title":"Producer–consumer, readers–writers và dining philosophers","body":["Bounded buffer dùng empty/full để đếm slot và mutex bảo vệ cấu trúc. Với readers–writers, reader preference có thể làm writer starvation; fairness không tự có chỉ vì dùng semaphore. Dining philosophers minh họa circular wait: lấy dụng cụ theo thứ tự toàn cục hoặc coordinator là các hướng giải.","Peterson là thuật toán kinh điển cho hai bên dưới giả định memory model phù hợp. Code đọc/ghi biến thông thường trên compiler/CPU hiện đại không tự giữ giả định của proof; cần atomic/memory ordering thích hợp. Spinlock phù hợp critical section ngắn trong một số bối cảnh, không thay mutex ngủ cho mọi tình huống."],"example":"","pitfall":"","exercise":"Tìm chỗ cần while quanh condition wait và chứng minh không có lost wakeup theo monitor semantics.","diagram":{"type":"graph","title":"Bounded buffer: dữ liệu và quyền truy cập","nodes":[[110,120,"Producer"],[320,120,"Buffer N slots"],[535,120,"Consumer"],[320,250,"Mutex + counts"]],"edges":[[0,1],[1,2],[3,1]],"caption":"empty/full đếm slot/item; mutex bảo vệ cấu trúc buffer. Không chờ semaphore tài nguyên trong lúc giữ mutex làm bên kia không thể tạo tiến triển."}}],"questions":[{"id":"thread","question":"Process và thread khác nhau thế nào?","answer":"Process cung cấp ranh giới tài nguyên/địa chỉ; thread là luồng thực thi trong process.","explanation":"Thread chia sẻ dữ liệu nên giao tiếp rẻ hơn nhưng dễ race; process tách biệt hơn nhưng IPC có chi phí.","followUp":"Một thread crash có thể ảnh hưởng cả process không?","note":"process","level":"Cơ bản"},{"id":"syscall","question":"System call khác function call thông thường thế nào?","answer":"Syscall yêu cầu dịch vụ kernel và có chuyển chế độ theo cơ chế hệ thống.","explanation":"Một function thư viện có thể gọi syscall, gọi nhiều syscall hoặc không gọi syscall nào.","followUp":"printf có luôn gọi write ngay không?","note":"process","level":"Cơ bản"},{"id":"concurrency","question":"Concurrency khác parallelism thế nào?","answer":"Concurrency là cùng tiến triển; parallelism là thực thi đồng thời theo thời gian thực.","explanation":"Một event loop có concurrency I/O dù JavaScript callback chạy từng cái trên một thread.","followUp":"CPU-bound được lợi từ async đơn thuần không?","note":"process","level":"Cơ bản"},{"id":"rr","question":"Time quantum quá nhỏ có vấn đề gì?","answer":"Tăng context-switch overhead và giảm thời gian làm việc hữu ích.","explanation":"Quantum lớn giảm overhead nhưng có thể tăng thời gian chờ phản hồi của task khác.","followUp":"Chỉ số response time khác turnaround ra sao?","note":"scheduling","level":"Cơ bản"},{"id":"zombie","question":"Zombie process là gì?","answer":"Child đã kết thúc nhưng parent chưa thu exit status.","explanation":"Nó giữ một số metadata trong process table, không tiếp tục dùng CPU để chạy chương trình đã kết thúc.","followUp":"wait hoặc waitpid giải quyết thế nào?","note":"scheduling","level":"Cơ bản"},{"id":"fault","question":"Page fault có luôn là segmentation fault không?","answer":"Không. Nhiều page fault được kernel xử lý hợp lệ bằng cấp trang hoặc nạp dữ liệu.","explanation":"Segmentation fault thường liên quan truy cập bộ nhớ không được phép; đây không phải mọi trường hợp fault.","followUp":"Copy-on-write liên quan page fault thế nào?","note":"memory","level":"Cơ bản"},{"id":"mutex","question":"Mutex khác semaphore thế nào?","answer":"Mutex thường có ownership và bảo vệ truy cập độc quyền; semaphore quản lý số lượng permit.","explanation":"Binary semaphore và mutex có thể khác quy tắc release, priority inheritance và ý nghĩa sử dụng.","followUp":"Giới hạn 10 kết nối đồng thời nên dùng gì?","note":"sync","level":"Cơ bản"},{"id":"deadlock","question":"Deadlock và starvation khác nhau thế nào?","answer":"Deadlock là vòng chờ không tiến triển; starvation là một tác vụ liên tục không được phục vụ.","explanation":"Hệ thống có thể vẫn tiến triển trong lúc một task starvation; fairness cần phân tích riêng.","followUp":"Livelock khác cả hai thế nào?","note":"sync","level":"Cơ bản"},{"id":"condition","question":"Vì sao condition variable thường dùng while?","answer":"Vì khi được đánh thức, predicate có thể chưa đúng hoặc đã bị thread khác thay đổi.","explanation":"Spurious wakeup và việc tranh lại mutex khiến if đơn lẻ không đủ trong mô hình thông dụng.","followUp":"signal có chuyển lock ngay cho waiter không?","note":"sync","level":"Cơ bản"},{"id":"banker","question":"Unsafe state có nghĩa đang deadlock không?","answer":"Không. Nó nghĩa không tìm được bảo đảm hoàn tất an toàn dưới mô hình nhu cầu đã khai báo.","explanation":"Deadlock avoidance khác detection; điều kiện và dữ liệu đầu vào phải được nói rõ.","followUp":"Thứ tự lấy lock giúp tránh loại điều kiện nào?","note":"sync","level":"Cơ bản"},{"id":"rtos","question":"Real-time OS có nghĩa luôn chạy nhanh nhất không?","answer":"Không. Trọng tâm là đáp ứng timing/deadline theo guarantee, không chỉ throughput cao.","explanation":"Hard và soft real-time có yêu cầu khác nhau; worst-case latency quan trọng.","followUp":"Một task nhanh trung bình nhưng trễ deadline hiếm có đáp ứng không?","note":"architectures","level":"Đào sâu"},{"id":"kernel","question":"Microkernel khác monolithic kernel thế nào?","answer":"Khác nơi đặt dịch vụ và ranh giới kernel/user, kèm trade-off IPC, isolation và độ phức tạp.","explanation":"Hệ thực tế có mô hình lai/modular; tránh kết luận từ tên gọi đơn lẻ.","followUp":"Driver lỗi ảnh hưởng phạm vi nào?","note":"architectures","level":"Đào sâu"},{"id":"tlb","question":"TLB miss khác page fault thế nào?","answer":"TLB miss là thiếu cache bản dịch; page fault liên quan điều kiện ánh xạ/permission/residency cần xử lý.","explanation":"Một TLB miss có thể được page-table walk giải quyết mà không nạp trang từ disk.","followUp":"Vì sao context switch có chi phí cache?","note":"memory-map","level":"Đào sâu"},{"id":"thrashing","question":"Thrashing là gì?","answer":"Hệ mất nhiều công việc vào chuyển trang do working set vượt khả năng RAM trong điều kiện đó.","explanation":"Cần giảm áp lực/working set hoặc tăng tài nguyên, không chỉ thêm thread.","followUp":"Page fault rate và disk activity gợi ý gì?","note":"memory-map","level":"Đào sâu"},{"id":"rw","question":"Readers-preference có ngăn writer starvation không?","answer":"Không nói chung. Reader mới liên tục có thể giữ writer chờ.","explanation":"Cần policy fairness hoặc writer priority với trade-off riêng.","followUp":"Reader-writer lock có luôn nhanh hơn mutex không?","note":"classical","level":"Đào sâu"},{"id":"peterson","question":"Peterson có thể chép nguyên bằng biến thường trên mọi CPU không?","answer":"Không. Proof dựa trên giả định visibility/ordering cần được bảo đảm.","explanation":"Compiler/CPU và memory model hiện đại có thể đổi quan sát; dùng primitive đúng.","followUp":"Atomicity khác memory ordering thế nào?","note":"classical","level":"Đào sâu"},{"id":"spin","question":"Khi nào spinlock có thể không phù hợp?","answer":"Khi chờ lâu hoặc holder không thể chạy ngay, spinning tiêu tốn CPU.","explanation":"Sleeping lock và scheduler trade-off theo bối cảnh; user-space/kernels khác nhau.","followUp":"Critical section ngắn có đủ để quyết định không?","note":"sync","level":"Đào sâu"},{"id":"philosophers","question":"Tránh deadlock dining philosophers bằng cách nào?","answer":"Áp thứ tự lấy tài nguyên hoặc phối hợp giới hạn người cùng thử theo thuật toán đúng.","explanation":"Còn cần phân tích starvation/fairness, không chỉ hết circular wait.","followUp":"Tại sao mọi người lấy dụng cụ trái trước có thể kẹt?","note":"classical","level":"Đào sâu"}],"order":4},{"id":"git","title":"Git & GitHub","group":"01 · Nền tảng","description":"Hiểu lịch sử commit để cộng tác và khôi phục thay đổi có chủ đích.","sources":[{"title":"Pro Git","url":"https://git-scm.com/book/en/v2"},{"title":"gitignore","url":"https://git-scm.com/docs/gitignore"}],"imageRefs":["E01–E15"],"prerequisites":["programming"],"notes":[{"id":"areas","title":"Working tree, index, commit và remote","body":["Working tree là file đang làm việc; index là snapshot dự kiến cho commit tiếp theo; commit là snapshot có metadata và liên kết parent. Branch là tên trỏ tới commit, không phải bản sao riêng toàn bộ thư mục. HEAD thường trỏ tới branch hiện tại.","Git là hệ thống version control; GitHub cung cấp hosting, PR và các chức năng cộng tác. Các thao tác commit, diff và branch cục bộ không cần mạng."],"example":"git status\ngit diff          # working tree so với index\ngit diff --cached # index so với HEAD\ngit add app.js\ngit commit -m \"Validate checkout input\"","pitfall":"git add . có thể stage thay đổi ngoài ý định; xem diff trước commit.","exercise":"Stage một phần thay đổi bằng git add -p.","diagram":{"type":"flow","title":"Từ chỉnh sửa đến chia sẻ","nodes":["Working tree","git add → Index","git commit → Local history","git push → Remote"],"caption":"fetch cập nhật remote-tracking refs; không tự trộn thay đổi vào working tree."}},{"id":"history","title":"Merge, rebase và giải quyết conflict","body":["Merge kết hợp các dòng lịch sử, có thể fast-forward hoặc tạo merge commit. Rebase phát lại commit trên base mới và tạo commit có định danh mới. Rebase hữu ích để chỉnh lịch sử riêng; lịch sử đã chia sẻ cần phối hợp trước khi viết lại.","Conflict là phần Git không tự hợp nhất được. Đọc cả hai thay đổi và mục đích nghiệp vụ, sửa code, chạy kiểm tra rồi tiếp tục thao tác. Không chỉ xóa marker mà bỏ qua logic."],"example":"git fetch origin\ngit rebase origin/main\n# sửa conflict, kiểm tra\ngit add app.js\ngit rebase --continue\n# hoặc git rebase --abort","pitfall":"Rebase không làm lịch sử không có xung đột; nó thay cách trình bày và giải quyết lịch sử.","exercise":"Vẽ commit DAG trước/sau merge và rebase của cùng hai nhánh."},{"id":"undo","title":"Restore, reset, revert và reflog","body":["restore thường khôi phục file hoặc index; reset có thể di chuyển ref và cập nhật index/working tree tùy mode; revert tạo commit đảo thay đổi. Revert phù hợp hoàn tác đã chia sẻ mà giữ lịch sử. Reflog ghi các lần di chuyển ref cục bộ và hỗ trợ tìm lại commit trong thời gian còn được giữ."],"example":"git restore --staged app.js # bỏ stage, giữ nội dung working tree\ngit revert \u003ccommit>        # tạo commit đảo\ngit reflog                 # tìm vị trí HEAD trước đó","pitfall":"reset --hard có thể loại thay đổi chưa commit. Reflog không phải backup và không bảo đảm phục hồi mọi file chưa từng được lưu vào Git.","exercise":"Chọn cách xử lý cho: staged nhầm, commit local sai, commit đã push sai."},{"id":"workflow","title":"Workflow, tag, stash và ignore","body":["Feature branch + PR giúp review thay đổi tập trung. Trunk-based dùng nhánh ngắn và tích hợp thường xuyên; Git Flow phù hợp một số quy trình release nhưng có thêm chi phí nhánh. Tag đánh dấu commit; annotated tag có metadata. Stash cất thay đổi tạm, không nên thay commit lâu dài.",".gitignore ngăn Git chú ý file chưa tracked phù hợp pattern; nó không tự untrack file đã commit và không xóa secret khỏi lịch sử. Secret đã lộ cần được thu hồi/đổi, không chỉ thêm ignore."],"example":"git stash push -u -m \"WIP form\"\ngit stash list\ngit tag -a v1.0.0 -m \"First release\"\n# Ignore ảnh nguồn tại root:\n/FDown.vn_instagram_*/","pitfall":"git pull phụ thuộc cấu hình merge/rebase; đừng hiểu nó luôn là một hành vi cố định.","exercise":"Thiết kế PR nhỏ cho thay đổi schema và ứng dụng cần tương thích nhiều phiên bản."},{"id":"dag","title":"Commit DAG và lịch sử nhánh","body":["Commit chứa parent; merge commit có nhiều parent. Log là đồ thị, không phải chỉ một đường thẳng. Tag/branch là ref tới commit; commit không “thuộc độc quyền” một branch. Cherry-pick phát lại thay đổi của commit vào dòng hiện tại và thường tạo commit mới.","Rebase/cherry-pick có thể gặp conflict do ngữ cảnh. Squash gom thay đổi để lịch sử review gọn hơn nhưng làm mất ranh giới commit gốc trên nhánh đích. Chọn theo mục tiêu history/debug, không chỉ giao diện đẹp."],"example":"","pitfall":"","exercise":"Đếm parent của M; giải thích vì sao revert merge cần chọn mainline.","diagram":{"type":"graph","title":"Hai nhánh cùng phát triển rồi merge","nodes":[[85,160,"A"],[240,160,"B"],[400,160,"C"],[240,55,"F1"],[400,55,"F2"],[555,160,"M"]],"edges":[[0,1],[1,2],[0,3],[3,4],[2,5],[4,5]],"caption":"M là merge commit có hai parent C/F2. Mũi tên ở đây biểu diễn hướng phát triển thời gian, ngược chiều liên kết parent trong object commit."}},{"id":"debug-history","title":"Bisect, blame và review lịch sử","body":["git bisect tìm commit gây regression bằng phép chia đôi với tiêu chí good/bad. Test dùng cho bisect cần tái hiện đủ ổn định và có thể bỏ qua commit không kiểm tra được. Blame cho biết nguồn dòng theo lịch sử, không xác định ai phải chịu lỗi.","PR tốt có mục đích, thay đổi quan sát được và kiểm chứng. Commit nhỏ, có ý nghĩa giúp review, revert và bisect; không sửa format toàn repo cùng lúc với logic nếu không cần."],"example":"git bisect start\ngit bisect bad\ngit bisect good \u003cknown-good-commit>\n# Kiểm tra rồi đánh dấu good/bad; kết thúc:\ngit bisect reset","pitfall":"","exercise":"Thiết kế test phát hiện regression mà không phụ thuộc API ngoài bất ổn."}],"questions":[{"id":"fetch","question":"git fetch khác git pull thế nào?","answer":"fetch lấy object và cập nhật remote-tracking refs; pull thực hiện fetch rồi tích hợp theo tùy chọn/cấu hình.","explanation":"Tích hợp có thể merge hoặc rebase; working tree cần được xử lý phù hợp trước đó.","followUp":"Khi muốn xem thay đổi remote trước khi tích hợp bạn làm gì?","note":"areas","level":"Cơ bản"},{"id":"branch","question":"Branch trong Git là gì?","answer":"Một ref có thể di chuyển trỏ tới commit.","explanation":"Tạo branch rẻ vì không sao chép toàn bộ file; working tree được cập nhật khi switch.","followUp":"Detached HEAD nghĩa là gì?","note":"areas","level":"Cơ bản"},{"id":"merge","question":"Merge và rebase khác nhau thế nào?","answer":"Merge giữ quan hệ lịch sử; rebase viết lại commit trên base mới.","explanation":"Hash thay vì parent thay đổi; chọn theo chính sách repo và trạng thái chia sẻ.","followUp":"Vì sao tránh rebase nhánh nhiều người đang dựa vào?","note":"history","level":"Cơ bản"},{"id":"conflict","question":"Xử lý conflict có những bước nào?","answer":"Hiểu ý định hai phía, sửa nội dung, stage, kiểm tra rồi tiếp tục merge/rebase.","explanation":"Marker biến mất chưa chứng minh code hợp lệ; cần kiểm tra cả API, kiểu dữ liệu và test.","followUp":"Bạn hủy merge/rebase đang dở thế nào?","note":"history","level":"Vận dụng"},{"id":"revert","question":"Commit đã push gây lỗi thì nên làm gì?","answer":"Thường tạo revert commit và đi qua quy trình review/deploy phù hợp.","explanation":"Giữ lịch sử chung; với merge commit cần hiểu mainline trước khi revert.","followUp":"Revert rồi muốn đưa lại tính năng cần chú ý gì?","note":"undo","level":"Cơ bản"},{"id":"reset","question":"reset --soft, --mixed, --hard khác nhau thế nào?","answer":"Soft di chuyển HEAD; mixed còn reset index; hard còn cập nhật working tree.","explanation":"Các mode có tác động khác nhau tới thay đổi chưa commit; cần đọc status/diff trước khi dùng.","followUp":"Bạn muốn gộp commit mà giữ thay đổi thì chọn gì?","note":"undo","level":"Cơ bản"},{"id":"reflog","question":"Lỡ xóa branch có khôi phục được không?","answer":"Có thể, nếu commit vẫn tìm được qua reflog hoặc ref khác và chưa bị thu dọn.","explanation":"Tìm commit rồi tạo branch trỏ tới nó; không coi đây là bảo đảm cho mọi dữ liệu.","followUp":"Khác nhau giữa log và reflog là gì?","note":"undo","level":"Đào sâu"},{"id":"ignore","question":"Thêm .env vào gitignore có gỡ file đã commit không?","answer":"Không. Ignore chủ yếu tác động file chưa tracked.","explanation":"Cần xử lý tracking riêng; nếu có secret đã lộ phải đổi secret, vì lịch sử vẫn có thể chứa nó.","followUp":"Tại sao xóa file ở commit mới vẫn chưa đủ?","note":"workflow","level":"Cơ bản"},{"id":"stash","question":"Stash có mặc định chứa untracked files không?","answer":"Không; thường cần -u để gồm untracked và -a để gồm cả ignored theo lệnh.","explanation":"Stash là lưu tạm cục bộ; kiểm tra nội dung trước pop và xử lý conflict nếu có.","followUp":"apply khác pop ở điểm nào?","note":"workflow","level":"Cơ bản"},{"id":"force","question":"force-with-lease an toàn tuyệt đối không?","answer":"Không. Nó kiểm tra ref remote theo kỳ vọng trước khi cập nhật, nhưng vẫn là viết lại lịch sử.","explanation":"Cần phối hợp và hiểu ref mong đợi; background fetch có thể ảnh hưởng cách suy ra kỳ vọng mặc định.","followUp":"Vì sao nhánh protected thường cấm force push?","note":"history","level":"Đào sâu"},{"id":"cherry","question":"Cherry-pick khác merge thế nào?","answer":"Cherry-pick phát lại thay đổi của commit cụ thể; merge kết hợp lịch sử và quan hệ parent.","explanation":"Cherry-pick có thể tạo patch tương tự với hash khác; cần tránh nhân thay đổi ngoài ý định.","followUp":"Khi backport hotfix bạn dùng gì?","note":"dag","level":"Vận dụng"},{"id":"bisect","question":"git bisect giúp gì?","answer":"Tìm commit đầu tiên gây lỗi bằng chia đôi khoảng good/bad.","explanation":"Cần tiêu chí kiểm tra ổn định; có thể automate bằng script phù hợp.","followUp":"Commit không build được trong khoảng xử lý sao?","note":"debug-history","level":"Vận dụng"},{"id":"squash","question":"Squash merge có đánh đổi gì?","answer":"Lịch sử nhánh đích gọn nhưng mất các ranh giới commit chi tiết ở đó.","explanation":"Chọn theo convention, khả năng revert và cách review.","followUp":"Một PR chứa hai tính năng độc lập squash có khó revert không?","note":"dag","level":"Vận dụng"},{"id":"detached","question":"Detached HEAD có làm mất commit ngay không?","answer":"Không. HEAD trỏ trực tiếp commit; commit mới cần ref phù hợp để giữ/tìm thuận tiện.","explanation":"Có thể tạo branch từ trạng thái đó; GC/reflog có lifecycle.","followUp":"Trước switch đi bạn giữ công việc thế nào?","note":"areas","level":"Vận dụng"},{"id":"tag","question":"Annotated tag khác lightweight tag thế nào?","answer":"Annotated tag có object/metadata riêng; lightweight thường là ref đơn giản.","explanation":"Release policy có thể yêu cầu chữ ký/metadata; tag không tự deploy.","followUp":"Tag có phải branch tự di chuyển khi commit không?","note":"workflow","level":"Vận dụng"},{"id":"stashconflict","question":"Stash pop gặp conflict thì sao?","answer":"Giải quyết như thay đổi cục bộ có conflict và kiểm tra stash còn tồn tại theo kết quả thao tác.","explanation":"Không chạy pop lặp mù quáng; inspect diff và bảo toàn bản gốc cần thiết.","followUp":"apply cho phép giữ stash để thử lại thế nào?","note":"workflow","level":"Vận dụng"}],"order":5},{"id":"linux","title":"Linux, CLI & chẩn đoán","group":"01 · Nền tảng","description":"Quan sát process, file, network và tài nguyên trước khi sửa hệ thống.","sources":[{"title":"GNU Bash manual","url":"https://www.gnu.org/software/bash/manual/bash.html"},{"title":"Linux man-pages","url":"https://www.kernel.org/doc/man-pages/"}],"imageRefs":[],"prerequisites":["os","git"],"notes":[{"id":"shell","title":"Shell, stream và pipeline","body":["Shell diễn giải lệnh và tổ hợp tiến trình. stdin/stdout/stderr là các stream riêng; pipe nối stdout lệnh trước với stdin lệnh sau. Quote tham số để giữ khoảng trắng và tránh glob/expansion ngoài ý định. Exit code 0 thường báo thành công; quy ước từng lệnh có thể khác."],"example":"rg \"ERROR\" app.log | head -n 20\ncommand >output.txt 2>errors.txt\n# 2>&1 ghép stderr vào stdout tại thời điểm redirect","pitfall":"Pipeline có thể che exit code của lệnh trước; trong Bash, cân nhắc set -o pipefail khi cần.","exercise":"Giải thích khác nhau giữa >, >>, 2> và 2>&1."},{"id":"files","title":"File, quyền và cấu hình","body":["Quyền rwx áp dụng cho owner/group/others; x trên directory là quyền đi qua. File ownership, umask và ACL ảnh hưởng quyền thực tế. Symlink trỏ theo đường dẫn; hard link liên kết tới cùng inode trong các giới hạn file system.","Tách cấu hình khỏi code, kiểm tra quyền file secret và tránh in secret vào log. Biến môi trường được truyền tới process con; không tự thay đổi process cha."],"example":"ls -lah\nstat app.log\nchmod 640 config.env\n# Đọc cấu trúc thay vì sửa quyền toàn bộ bằng 777","pitfall":"chmod 777 không phải cách sửa mặc định cho mọi lỗi permission.","exercise":"Giải thích vì sao đọc file được nhưng không xóa được trong một directory."},{"id":"process-tools","title":"Quan sát process và tài nguyên","body":["Bắt đầu từ triệu chứng: chậm, lỗi, hết bộ nhớ hay không kết nối được. Dùng ps/top để xem process; free/vmstat/iostat hoặc công cụ hệ tương ứng để phân tích memory/I/O. CPU cao khác load average cao; load có thể tăng khi tác vụ chờ I/O.","SIGTERM cho ứng dụng cơ hội đóng có trật tự; SIGKILL không thể bị bắt để cleanup. Kiểm tra process có shutdown handler, deadline và cách xử lý request đang chạy."],"example":"ps aux\n# Linux:\nss -lntp\ndf -h\ndu -sh ./logs\n# Lệnh và tùy chọn có thể khác trên macOS","pitfall":"Không xóa log đang mở mà mặc định dung lượng sẽ được trả ngay; process còn giữ descriptor có thể giữ dữ liệu.","exercise":"Lập trình tự điều tra disk full: block, inode, file đang mở đã bị xóa."},{"id":"network-tools","title":"Điều tra lỗi kết nối theo tầng","body":["Tách lỗi phân giải DNS, route/TCP, TLS và HTTP/application. curl có thể hiển thị status/headers/timing; dig kiểm tra DNS; ss/lsof xem socket/listener theo hệ điều hành. Một port mở chỉ chứng minh một phần kết nối, chưa chứng minh nghiệp vụ hoạt động."],"example":"curl -I https://example.com\ncurl -sS -o /dev/null -w \"%{http_code} %{time_total}\\n\" https://example.com\ndig example.com","pitfall":"HTTP 200 không tự có nghĩa response đúng; cần xét body, freshness và trạng thái nghiệp vụ.","exercise":"Một API chạy được trên máy server nhưng không từ container: liệt kê giả thuyết và phép kiểm tra."}],"questions":[{"id":"pipe","question":"Pipe chuyển những dữ liệu nào mặc định?","answer":"stdout của tiến trình bên trái thành stdin của bên phải.","explanation":"stderr không tự đi qua pipe trừ khi redirect phù hợp.","followUp":"Khi grep trả 1 có nhất thiết là lỗi hệ thống không?","note":"shell","level":"Cơ bản"},{"id":"quote","question":"Vì sao phải quote đường dẫn từ biến?","answer":"Để tránh word splitting và pathname expansion ngoài ý định của shell.","explanation":"Chuỗi chứa khoảng trắng hoặc ký tự glob có thể trở thành nhiều đối số.","followUp":"Single quote khác double quote thế nào?","note":"shell","level":"Cơ bản"},{"id":"permission","question":"Vì sao chmod 777 là lựa chọn kém?","answer":"Nó cấp quyền rộng và có thể che nguyên nhân ownership hoặc cấu hình sai.","explanation":"Xác định process chạy bằng user nào và cấp quyền tối thiểu cần thiết.","followUp":"Quyền x trên directory có nghĩa gì?","note":"files","level":"Cơ bản"},{"id":"link","question":"Hard link khác symlink thế nào?","answer":"Hard link liên kết cùng inode; symlink lưu đường dẫn tới đích.","explanation":"Symlink có thể hỏng khi đích mất; hard link bị giới hạn theo file system và loại đối tượng.","followUp":"Xóa một tên hard link có xóa ngay dữ liệu không?","note":"files","level":"Cơ bản"},{"id":"signal","question":"SIGTERM khác SIGKILL thế nào?","answer":"SIGTERM có thể được xử lý để shutdown; SIGKILL buộc dừng và không thể bắt để cleanup.","explanation":"Dừng có trật tự cần deadline vì handler có thể bị treo.","followUp":"Ứng dụng nên làm gì với request đang xử lý?","note":"process-tools","level":"Cơ bản"},{"id":"load","question":"Load average cao có luôn nghĩa CPU cao không?","answer":"Không. Trên Linux nó còn phản ánh các task trong trạng thái chờ không ngắt được.","explanation":"Cần xem CPU, run queue, I/O wait và disk/network để xác định nguyên nhân.","followUp":"Server ít CPU nhưng chậm có thể do đâu?","note":"process-tools","level":"Vận dụng"},{"id":"disk","question":"df và du khác nhau vì sao?","answer":"df báo mức sử dụng file system; du cộng dung lượng các file được duyệt.","explanation":"File đã unlink nhưng còn mở, permission hoặc mount khác có thể tạo chênh lệch.","followUp":"Hết inode thì còn block trống có ghi file mới được không?","note":"process-tools","level":"Cơ bản"},{"id":"dns","question":"curl báo không resolve được host thì kiểm tra gì?","answer":"DNS configuration, tên miền, resolver và kết quả truy vấn trước khi kiểm tra HTTP handler.","explanation":"Điều tra theo tầng giúp tránh sửa application khi lỗi xảy ra trước kết nối.","followUp":"Gọi bằng IP có bỏ qua đầy đủ DNS/TLS hostname không?","note":"network-tools","level":"Cơ bản"},{"id":"listen","question":"Service bind 127.0.0.1 có truy cập từ máy khác được không?","answer":"Thông thường không trực tiếp qua interface mạng bên ngoài.","explanation":"Cần xét bind address, namespace/container, port mapping và firewall.","followUp":"0.0.0.0 có phải địa chỉ client nên dùng để gọi không?","note":"network-tools","level":"Cơ bản"},{"id":"logs","question":"Bạn xem log production như thế nào?","answer":"Giới hạn theo thời gian/request ID, bảo vệ dữ liệu nhạy cảm và đối chiếu metrics/traces.","explanation":"Không tải cả file khổng lồ hoặc in toàn bộ environment để debug.","followUp":"Bạn phát hiện log rotation không hoạt động bằng cách nào?","note":"process-tools","level":"Cơ bản"}],"order":6},{"id":"network","title":"Web, DNS & HTTP","group":"02 · Web & Frontend","description":"Theo một request từ trình duyệt qua mạng tới ứng dụng.","sources":[{"title":"MDN HTTP","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Overview"},{"title":"HTTP/3 RFC 9114","url":"https://www.rfc-editor.org/rfc/rfc9114.html"}],"imageRefs":["A03","D04","F02–F03"],"prerequisites":["linux"],"notes":[{"id":"journey","title":"Từ URL đến nội dung hiển thị","body":["Trình duyệt phân tích URL, xét cache và policy, phân giải tên nếu cần, thiết lập kết nối rồi gửi request. HTTPS cần xác thực server và bảo vệ dữ liệu bằng TLS. Server có thể gọi database/cache rồi trả response; trình duyệt phân tích HTML và tải tài nguyên liên quan.","DNS trả dữ liệu phục vụ phân giải tên, không chuyển tiếp HTTP. Kết nối tái sử dụng hoặc cache có thể bỏ qua một số bước. HTTP/1.1 và HTTP/2 thường dùng TCP; HTTP/3 dùng QUIC trên UDP."],"example":"","pitfall":"","exercise":"Chỉ ra bước không cần thực hiện lại khi tái sử dụng kết nối.","diagram":{"type":"sequence","title":"Một request HTTPS thông thường","actors":["Trình duyệt","DNS","API server","Database"],"steps":[[0,1,"Tra tên → địa chỉ"],[1,0,"Kết quả DNS"],[0,2,"Kết nối + TLS; gửi HTTP"],[2,3,"Truy vấn dữ liệu"],[3,2,"Kết quả truy vấn"],[2,0,"Status + headers + body"]],"caption":"Sơ đồ minh họa: bỏ qua proxy/CDN và giả định chưa có kết nối phù hợp."}},{"id":"semantics","title":"Methods, status và tính idempotent","body":["GET có ngữ nghĩa đọc và safe; PUT thay thế representation của resource đích theo hợp đồng; PATCH áp dụng thay đổi; POST thực hiện xử lý theo resource; DELETE yêu cầu xóa. Idempotent nghĩa tác động mong muốn khi lặp giống một lần, không đòi status/body giống nhau.","2xx thành công, 3xx chuyển hướng hoặc cache validation theo mã cụ thể, 4xx vấn đề từ request/ngữ cảnh client, 5xx server không hoàn thành. 401 thiếu credential hợp lệ; 403 server từ chối quyền truy cập."],"example":"GET /orders/42 HTTP/1.1\nHost: api.example.com\nAccept: application/json\n\nHTTP/1.1 200 OK\nContent-Type: application/json","pitfall":"PATCH không mặc định idempotent; “tăng số dư thêm 1” khác “đặt số dư bằng 1”.","exercise":"Thiết kế retry cho GET, POST thanh toán và DELETE tài nguyên đã mất."},{"id":"transport","title":"TCP, UDP, TLS và kết nối","body":["TCP cung cấp byte stream có thứ tự và truyền lại trong một kết nối; ứng dụng vẫn phải định nghĩa framing, timeout và thành công nghiệp vụ. UDP là datagram, không tự bảo đảm giao nhận/thứ tự. Giao thức phía trên như QUIC có thể bổ sung tính tin cậy.","TLS dùng chứng chỉ và kiểm tra hostname để xác thực server, đồng thời bảo vệ bí mật/toàn vẹn đường truyền. HTTPS không xác nhận nội dung nghiệp vụ an toàn hay người dùng được quyền thao tác."],"example":"","pitfall":"Timeout ở client không chứng minh server chưa thực hiện thao tác.","exercise":"Mô tả xử lý khi client timeout ngay sau khi server ghi đơn hàng thành công.","diagram":{"type":"sequence","title":"TLS: xác thực và tạo kênh mã hóa","actors":["Client","TLS server"],"steps":[[0,1,"Hello + tham số/key share"],[1,0,"Chứng chỉ + tham số/key share"],[0,1,"Kiểm tra danh tính, hoàn tất handshake"],[0,1,"Application data được bảo vệ"],[1,0,"Response được bảo vệ"]],"caption":"Sơ đồ khái niệm, không chép từng bản tin TLS. Phiên bản, resumption và QUIC thay đổi handshake; chứng chỉ được kiểm tra ở client, không phải gửi password để mã hóa."}},{"id":"proxy","title":"Proxy, HTTP cache và kết nối dài","body":["Forward proxy đại diện phía client; reverse proxy đứng trước server để routing, TLS termination hoặc cân bằng tải. CDN cache nội dung gần người dùng theo cấu hình. Cache-Control, Vary và validator như ETag quyết định cách tái sử dụng response.","Connection reuse giảm chi phí bắt tay; HTTP/2 multiplex nhiều stream nhưng vẫn chịu đặc điểm TCP bên dưới. WebSocket/SSE là lựa chọn giao tiếp ứng dụng, cần hiểu auth, reconnect và khả năng resume."],"example":"Cache-Control: private, max-age=60\nETag: \"revision-42\"\n# Client lần sau có thể gửi:\nIf-None-Match: \"revision-42\"","pitfall":"Không cache chung dữ liệu riêng tư chỉ vì response có HTTP 200.","exercise":"Phân biệt cache tài nguyên versioned với cache thông tin hồ sơ người dùng."}],"questions":[{"id":"url","question":"Nhập URL vào browser thì xảy ra gì?","answer":"Phân tích URL, xét cache/policy, DNS nếu cần, kết nối/TLS, HTTP và render tài nguyên.","explanation":"Một số bước được bỏ qua nhờ cache/kết nối tái sử dụng; HTTP/3 dùng QUIC.","followUp":"DNS có nằm trên đường chuyển tiếp body HTTP không?","note":"journey","level":"Cơ bản"},{"id":"https","question":"HTTPS bảo vệ điều gì?","answer":"Bí mật, toàn vẹn và xác thực server trên đường truyền khi TLS được kiểm tra đúng.","explanation":"Không thay thế authorization hoặc validation ở ứng dụng.","followUp":"TLS termination ở proxy thay đổi ranh giới tin cậy ra sao?","note":"transport","level":"Cơ bản"},{"id":"tcp","question":"TCP có bảo đảm request nghiệp vụ chỉ chạy một lần không?","answer":"Không. TCP bảo vệ truyền byte trong kết nối, không cung cấp exactly-once nghiệp vụ.","explanation":"Retry sau mất kết nối có thể lặp xử lý đã hoàn tất.","followUp":"API thanh toán cần thêm cơ chế gì?","note":"transport","level":"Cơ bản"},{"id":"put","question":"PUT khác PATCH thế nào?","answer":"PUT có ngữ nghĩa thay thế representation; PATCH mô tả thay đổi theo định dạng/hợp đồng.","explanation":"PUT là idempotent theo ngữ nghĩa; PATCH phụ thuộc thao tác cụ thể.","followUp":"PATCH increment có an toàn để retry không?","note":"semantics","level":"Cơ bản"},{"id":"delete","question":"DELETE lần hai trả 404 có mất idempotency không?","answer":"Không. Tài nguyên vẫn không tồn tại sau cả hai lần.","explanation":"Idempotency nói về tác động mong muốn, không phải response phải giống hệt.","followUp":"Logging mỗi request có vi phạm idempotency không?","note":"semantics","level":"Cơ bản"},{"id":"status","question":"401 và 403 khác nhau thế nào?","answer":"401 nói credential chưa hợp lệ/thiếu; 403 nói request bị từ chối quyền.","explanation":"Một API có thể dùng 404 để không tiết lộ tài nguyên, theo policy nhất quán.","followUp":"User đăng nhập đúng nhưng không sở hữu order nên xử lý gì?","note":"semantics","level":"Cơ bản"},{"id":"h3","question":"HTTP/3 có chạy trên TCP không?","answer":"Không; HTTP/3 ánh xạ HTTP lên QUIC, thường trên UDP.","explanation":"QUIC cung cấp các cơ chế transport riêng; không suy ra HTTP/3 là truyền không tin cậy.","followUp":"Vì sao UDP và reliable application có thể cùng tồn tại?","note":"transport","level":"Cơ bản"},{"id":"dns","question":"DNS cache gây tình huống gì khi đổi IP?","answer":"Client/resolver có thể tiếp tục dùng record còn hiệu lực theo TTL và cache behavior.","explanation":"Cần kế hoạch chuyển traffic và thời gian sống record; TTL không phải nút xóa mọi cache ngay.","followUp":"Bạn kiểm tra resolver nào đang trả dữ liệu cũ?","note":"journey","level":"Cơ bản"},{"id":"304","question":"304 Not Modified dùng khi nào?","answer":"Khi conditional request cho phép tái dùng representation đã cache.","explanation":"Response thường không chứa lại toàn bộ body; client cần bản cache tương ứng.","followUp":"ETag khác Cache-Control thế nào?","note":"proxy","level":"Cơ bản"},{"id":"proxy","question":"Reverse proxy và load balancer có giống hệt nhau không?","answer":"Chức năng có thể chồng lấn; reverse proxy đại diện backend, load balancer phân phối tải.","explanation":"Một sản phẩm có thể làm cả hai; cần phân biệt L4 và L7.","followUp":"Nơi nào nên thêm request ID?","note":"proxy","level":"Cơ bản"}],"order":7},{"id":"html-css","title":"HTML, CSS & Accessibility","group":"02 · Web & Frontend","description":"Xây giao diện có cấu trúc, responsive và dùng được bằng bàn phím.","sources":[{"title":"MDN HTML","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Core/Structuring_content"},{"title":"WCAG overview","url":"https://www.w3.org/WAI/standards-guidelines/wcag/"}],"imageRefs":[],"prerequisites":["network"],"notes":[{"id":"semantics","title":"HTML biểu diễn ý nghĩa","body":["Dùng heading theo cấu trúc, main cho nội dung chính, nav cho điều hướng, button cho hành động và a cho liên kết. Semantic HTML cung cấp hành vi bàn phím và ý nghĩa cho công nghệ hỗ trợ. ARIA bổ sung ngữ nghĩa khi cần, không tự tạo hành vi tương tác."],"example":"\u003clabel for=\"email\">Email\u003c/label>\n\u003cinput id=\"email\" name=\"email\" type=\"email\" required>\n\u003cbutton type=\"submit\">Đăng ký\u003c/button>","pitfall":"div có onclick không tự có focus, Enter/Space hay vai trò button.","exercise":"Kiểm tra một form chỉ dùng Tab, Shift+Tab và Enter."},{"id":"layout","title":"Box model, cascade và layout","body":["Box model gồm content, padding, border và margin. box-sizing:border-box làm width/height gồm padding và border. Cascade chọn declaration theo nhiều yếu tố như origin, importance, layer, specificity và source order; không chỉ “selector dài hơn thắng”.","Flexbox phù hợp sắp xếp một chiều; Grid phù hợp bố cục hai chiều. Responsive ưu tiên nội dung và các điểm layout thực sự cần thay đổi. min-width:0 thường cần cho flex/grid child có nội dung dài."],"example":"* { box-sizing: border-box; }\n.cards { display: grid; gap: 1rem;\n  grid-template-columns: repeat(auto-fit, minmax(min(100%, 18rem), 1fr));\n}","pitfall":"Không dùng fixed width làm nội dung tràn màn hình nhỏ.","exercise":"Tạo layout ba cột tự chuyển thành một cột mà không cần đặt breakpoint cho từng thiết bị.","diagram":{"type":"boxes","title":"Box model: các lớp bao quanh content","labels":["MARGIN · khoảng cách bên ngoài","BORDER · đường viền","PADDING · khoảng đệm","CONTENT · nội dung"],"caption":"Với border-box, width gồm content + padding + border; margin ở ngoài kích thước khai báo. Các lớp lồng nhau, không phải luồng xử lý."}},{"id":"accessibility","title":"Focus, tương phản và trạng thái UI","body":["Tất cả thao tác chính phải dùng được bằng bàn phím, focus nhìn thấy và thứ tự đọc hợp lý. Icon button cần accessible name. Không chỉ dùng màu để báo lỗi; mô tả bằng chữ và gắn lỗi với field. Nội dung thay đổi quan trọng có thể cần live region nhưng không nên thông báo quá nhiều.","Ảnh mang thông tin cần alt mô tả ý nghĩa; ảnh trang trí có thể alt rỗng. Sơ đồ phức tạp cần caption hoặc mô tả tương đương bằng chữ."],"example":"","pitfall":"Ẩn outline toàn site làm người dùng bàn phím mất vị trí hiện tại.","exercise":"Phóng to 200%, giảm motion và kiểm tra giao diện ở chiều rộng 320px."},{"id":"forms","title":"Form và validation hai phía","body":["Form cần label, kiểu input phù hợp, trạng thái đang gửi, thông báo thành công/lỗi và tránh submit lặp. Validation phía client cải thiện trải nghiệm; server vẫn là nơi bắt buộc xác thực dữ liệu và quyền.","Dữ liệu lỗi cần giữ lại để người dùng sửa. Dùng autocomplete phù hợp cho trường quen thuộc và kiểm tra cả input rỗng, khoảng trắng, Unicode, độ dài."],"example":"\u003cform>\n  \u003clabel for=\"name\">Họ tên\u003c/label>\n  \u003cinput id=\"name\" name=\"name\" autocomplete=\"name\">\n  \u003cbutton>Lưu hồ sơ\u003c/button>\n\u003c/form>","pitfall":"Disable nút không thay thế idempotency ở backend cho thao tác quan trọng.","exercise":"Thiết kế lỗi cho email đã tồn tại mà không làm mất các trường khác."},{"id":"position","title":"Position, stacking context và các lỗi bố cục","body":["position relative giữ vị trí trong flow và tạo cơ sở cho một số positioned descendant; absolute lấy khỏi normal flow và định vị theo containing block; fixed thường theo viewport nhưng một số ancestor có thể thay containing block; sticky phụ thuộc scroll container và ngưỡng.","z-index so trong stacking context, không là bảng điểm toàn cục cho mọi element. Overflow/transform/opacity có thể ảnh hưởng layout/stacking theo quy tắc CSS. Dùng DevTools kiểm tra ancestor thay vì tăng z-index lên một số rất lớn."],"example":"","pitfall":"","exercise":"Modal z-index 9999 vẫn nằm dưới header: tìm stacking context nào đang giới hạn."}],"questions":[{"id":"semantic","question":"Vì sao dùng button thay div có click?","answer":"Button có sẵn ngữ nghĩa, focus và tương tác bàn phím phù hợp.","explanation":"Nếu tự tạo widget phải triển khai đầy đủ hành vi, không chỉ thêm role.","followUp":"Button trong form mặc định có thể làm gì?","note":"semantics","level":"Cơ bản"},{"id":"label","question":"Placeholder có thay label được không?","answer":"Không nên. Nó biến mất khi nhập và không phải cách thay thế label đầy đủ.","explanation":"Label rõ giúp hiểu trường và tăng vùng click/focus của input.","followUp":"Một input chỉ có icon cần accessible name thế nào?","note":"forms","level":"Cơ bản"},{"id":"box","question":"border-box giải quyết điều gì?","answer":"Giúp kích thước khai báo gồm padding và border, dễ tính layout.","explanation":"Margin vẫn nằm ngoài; intrinsic sizing và min-width vẫn ảnh hưởng bố cục.","followUp":"Vì sao item flex vẫn tràn dù width 100%?","note":"layout","level":"Cơ bản"},{"id":"grid","question":"Khi nào dùng Grid thay Flexbox?","answer":"Khi cần phối hợp hàng và cột theo bố cục hai chiều.","explanation":"Flexbox thuận tiện phân phối item trên một trục; hai công cụ có thể kết hợp.","followUp":"Bạn bố trí sidebar và content responsive thế nào?","note":"layout","level":"Cơ bản"},{"id":"cascade","question":"Specificity có phải yếu tố duy nhất của cascade?","answer":"Không. Origin, importance, layer và các quy tắc khác được xét trước một số bước specificity.","explanation":"Source order thường giải quyết khi các yếu tố ưu tiên trước đó bằng nhau.","followUp":"Lạm dụng !important gây khó bảo trì ra sao?","note":"layout","level":"Cơ bản"},{"id":"alt","question":"Alt text nên viết gì?","answer":"Diễn đạt thông tin hoặc chức năng mà ảnh đóng góp trong ngữ cảnh.","explanation":"Ảnh trang trí dùng alt rỗng; không lặp toàn bộ caption một cách máy móc.","followUp":"Biểu đồ có nhiều dữ liệu cần mô tả thêm ở đâu?","note":"accessibility","level":"Cơ bản"},{"id":"focus","question":"Một modal đúng cần xử lý focus thế nào?","answer":"Đưa focus vào modal, giữ tương tác phù hợp và trả focus về nơi mở khi đóng.","explanation":"Cần hỗ trợ Escape khi thích hợp và làm nội dung nền không tương tác.","followUp":"Nếu phần tử mở modal đã bị xóa thì trả focus đâu?","note":"accessibility","level":"Cơ bản"},{"id":"responsive","question":"Responsive có phải chỉ thêm media query?","answer":"Không. Cần layout linh hoạt, nội dung co giãn, ảnh phù hợp và kiểm tra zoom.","explanation":"Breakpoints theo nội dung thay vì danh sách model điện thoại.","followUp":"Bảng rộng và code dài nên xử lý thế nào?","note":"layout","level":"Cơ bản"},{"id":"validate","question":"Client validation đủ bảo vệ dữ liệu chưa?","answer":"Chưa. Request có thể bỏ qua UI; server cần validate và authorize độc lập.","explanation":"Client giúp phản hồi nhanh; server giữ quy tắc chính thức.","followUp":"Hai phía cần chia sẻ những quy tắc nào?","note":"forms","level":"Vận dụng"},{"id":"color","question":"Chỉ dùng đỏ/xanh báo đúng sai có vấn đề gì?","answer":"Người không phân biệt màu hoặc dùng công nghệ hỗ trợ có thể mất thông tin.","explanation":"Bổ sung text, icon có nhãn và liên kết lỗi tới field.","followUp":"Bạn thông báo kết quả submit động thế nào?","note":"accessibility","level":"Cơ bản"},{"id":"zindex","question":"z-index thật lớn có luôn nổi trên mọi element không?","answer":"Không. Nó bị giới hạn bởi stacking context và còn có các cơ chế như top layer.","explanation":"Cần kiểm tra context cha và mô hình overlay đúng.","followUp":"Transform trên ancestor có ảnh hưởng fixed element không?","note":"position","level":"Vận dụng"},{"id":"sticky","question":"position sticky không chạy thì kiểm tra gì?","answer":"Ngưỡng top/inset, scroll container, overflow ancestor và không gian để sticky hoạt động.","explanation":"Không chỉ thêm z-index; layout/containing block quyết định.","followUp":"Sticky trong container quá ngắn sẽ ra sao?","note":"position","level":"Vận dụng"}],"order":8},{"id":"javascript","title":"JavaScript & Browser APIs","group":"02 · Web & Frontend","description":"Closure, event loop, DOM và các luồng dữ liệu trong trình duyệt.","sources":[{"title":"MDN JS Guide","url":"https://developer.mozilla.org/en-US/docs/Web/JavaScript/Guide"},{"title":"MDN Fetch","url":"https://developer.mozilla.org/en-US/docs/Web/API/Fetch_API/Using_Fetch"}],"imageRefs":[],"prerequisites":["programming","html-css"],"notes":[{"id":"scope","title":"Scope, closure và this","body":["let/const có block scope; var có function scope và hành vi hoisting khác. Closure truy cập lexical environment của nơi tạo hàm. this của function thường phụ thuộc cách gọi; arrow function lấy this từ môi trường bao ngoài.","=== so sánh không chuyển kiểu như ==, nhưng object so theo identity. Object.is khác ở một số giá trị như NaN và -0. Khi xử lý dữ liệu cần hiểu đúng equality thay vì học thuộc một khẩu hiệu."],"example":"const user = { name: \"An\", say() { return this.name; } };\nconst say = user.say;\n// say() không còn được gọi với receiver user\nconst bound = user.say.bind(user);","pitfall":"Hoisting không có nghĩa let được truy cập an toàn trước khai báo; temporal dead zone vẫn áp dụng.","exercise":"Dự đoán this của callback truyền trực tiếp và callback arrow bọc ngoài."},{"id":"loop","title":"Task, microtask và promise","body":["Code đồng bộ chạy trên call stack. Promise reaction và queueMicrotask đưa microtask; nhiều callback timer/event chạy như task. Sau khi task hiện tại hoàn tất, browser có các điểm xử lý microtask trước cơ hội render tiếp theo.","await không chặn main thread; nó tạm dừng async function rồi tiếp tục qua promise. Nhưng tính toán CPU nặng trước/sau await vẫn có thể làm UI đứng. Web Worker chuyển công việc sang worker với cơ chế truyền dữ liệu."],"example":"console.log(\"A\");\nsetTimeout(() => console.log(\"B\"), 0);\nPromise.resolve().then(() => console.log(\"C\"));\nconsole.log(\"D\"); // A D C B","pitfall":"Chuỗi microtask liên tục có thể trì hoãn task/render. Event loop browser và Node không nên bị coi là một sơ đồ y hệt.","exercise":"Giải thích vì sao setTimeout(fn, 0) không bảo đảm chạy ngay."},{"id":"dom","title":"DOM events, delegation và lifecycle","body":["Event thường đi qua capture, target rồi bubble tùy loại. Delegation gắn listener ở ancestor rồi nhận diện target phù hợp, hữu ích cho danh sách động. preventDefault ngăn hành vi mặc định khi cho phép; stopPropagation tác động lan truyền, hai việc khác nhau.","Gỡ listener, timer và observer khi thành phần hết vòng đời. Khi chèn dữ liệu không tin cậy, ưu tiên textContent thay innerHTML; sanitize theo ngữ cảnh nếu thật sự cần HTML."],"example":"list.addEventListener(\"click\", (event) => {\n  const button = event.target.closest(\"button[data-id]\");\n  if (!button || !list.contains(button)) return;\n  selectItem(button.dataset.id);\n});","pitfall":"Không phải mọi event đều bubble; delegation cần hiểu loại event đang dùng.","exercise":"Tạo danh sách thêm item động mà không gắn listener riêng cho từng item."},{"id":"fetch","title":"Fetch, hủy request và lưu dữ liệu","body":["fetch thường chỉ reject vì lỗi mạng hoặc hủy, không tự reject mọi HTTP 4xx/5xx. Kiểm tra response.ok/status và parse theo content type/hợp đồng. Khi tìm kiếm liên tục, dùng AbortController hoặc kiểm tra request identity để response cũ không ghi đè mới.","localStorage lưu chuỗi và chạy đồng bộ; không chứa secret nhạy cảm theo mặc định. Cookie có thể được cấu hình HttpOnly để JS không đọc được; mọi lựa chọn auth cần xét XSS/CSRF và kiến trúc."],"example":"const controller = new AbortController();\nconst response = await fetch(\"/api/products\", { signal: controller.signal });\nif (!response.ok) throw new Error(`HTTP ${response.status}`);\nconst products = await response.json();","pitfall":"Hủy phía client không bảo đảm server ngừng hoặc hoàn tác công việc.","exercise":"Mô phỏng response của từ khóa cũ tới sau từ khóa mới và xử lý race."},{"id":"async-patterns","title":"Các promise combinator và dữ liệu bất biến","body":["Promise.all hợp khi cần tất cả; allSettled khi cần thống kê từng kết quả; race theo input settle đầu tiên; any theo fulfillment đầu tiên và reject khi mọi input reject. Không combinator nào mặc định hủy tác vụ khác.","Object spread/array spread tạo shallow copy. structuredClone hỗ trợ một số cấu trúc sâu nhưng không mọi giá trị như function/DOM node; serialization JSON có giới hạn về kiểu, chu kỳ và undefined. Chọn cách sao chép theo dữ liệu chứ không như một thủ thuật chung."],"example":"const results = await Promise.allSettled(urls.map(load));\nconst ok = results.filter(r => r.status === \"fulfilled\");\n// Cần limit concurrency riêng nếu urls rất nhiều.","pitfall":"","exercise":"Viết worker pool giới hạn 5 request thay vì Promise.all cho 100.000 URL."}],"questions":[{"id":"let","question":"let, const và var khác nhau thế nào?","answer":"let/const có block scope; var có function scope. const cấm gán lại binding.","explanation":"let/const có temporal dead zone; const object vẫn có thể thay thuộc tính.","followUp":"Một closure trong vòng lặp var khác let thế nào?","note":"scope","level":"Cơ bản"},{"id":"this","question":"Arrow function khác function thường ở this ra sao?","answer":"Arrow dùng lexical this; function thường lấy this theo cách gọi và mode.","explanation":"bind/call/apply không đổi lexical this của arrow.","followUp":"Vì sao tách method ra biến có thể làm mất receiver?","note":"scope","level":"Cơ bản"},{"id":"output","question":"Đoạn log sync, Promise.then và setTimeout(0) chạy theo thứ tự nào?","answer":"Code đồng bộ trước; promise microtask sau khi stack rỗng; timer task tới sau khi đủ điều kiện.","explanation":"Timer delay là ngưỡng tối thiểu theo scheduling, không phải deadline chính xác.","followUp":"Promise.then tự thêm microtask liên tục ảnh hưởng gì?","note":"loop","level":"Cơ bản"},{"id":"await","question":"await có làm JavaScript đa luồng không?","answer":"Không. Nó giúp tiếp tục async function sau khi promise settle.","explanation":"CPU-heavy loop vẫn chặn thread nơi nó thực thi; worker là cơ chế khác.","followUp":"Khi nào dùng Promise.all thay await tuần tự?","note":"loop","level":"Cơ bản"},{"id":"all","question":"Promise.all khác allSettled thế nào?","answer":"all reject khi có input reject; allSettled đợi kết quả trạng thái của tất cả.","explanation":"all reject không tự hủy công việc khác; cần cancellation riêng nếu muốn.","followUp":"race khác any thế nào khi có rejection?","note":"loop","level":"Cơ bản"},{"id":"bubble","question":"preventDefault khác stopPropagation thế nào?","answer":"Một cái ngăn default action, một cái dừng propagation theo semantics của event.","explanation":"Không tự thay thế nhau; listener passive không cho preventDefault có tác dụng như mong đợi.","followUp":"Delegation dựa vào điều gì?","note":"dom","level":"Cơ bản"},{"id":"fetch404","question":"fetch nhận 404 có vào catch ngay không?","answer":"Thường không; fetch resolve với Response, cần kiểm tra ok hoặc status.","explanation":"JSON parsing có thể reject riêng; phân biệt lỗi HTTP, mạng và dữ liệu.","followUp":"Bạn hiển thị lỗi 401 và 500 khác nhau thế nào?","note":"fetch","level":"Cơ bản"},{"id":"abort","question":"AbortController giải quyết race hoàn toàn chưa?","answer":"Nó hỗ trợ hủy thao tác phía client, nhưng vẫn cần quản lý identity/trạng thái phù hợp.","explanation":"Server có thể đã xử lý; UI nên chỉ áp dụng kết quả thuộc request hiện hành.","followUp":"Một request đã hoàn tất trước abort thì sao?","note":"fetch","level":"Đào sâu"},{"id":"debounce","question":"Debounce khác throttle thế nào?","answer":"Debounce chờ một khoảng yên; throttle giới hạn tần suất thực thi.","explanation":"Debounce hợp ô tìm kiếm; throttle có ích cho event dày. Cần cleanup timer.","followUp":"Bạn muốn gửi lần đầu, lần cuối hay cả hai?","note":"dom","level":"Cơ bản"},{"id":"storage","question":"localStorage và sessionStorage khác nhau thế nào?","answer":"Cả hai lưu chuỗi theo origin; sessionStorage gắn với phiên tab theo mô hình browser.","explanation":"localStorage tồn tại lâu hơn nhưng có thể bị chặn/xóa; cần xử lý quota và lỗi truy cập.","followUp":"Vì sao không coi browser storage là backup?","note":"fetch","level":"Vận dụng"},{"id":"any","question":"Promise.any khác Promise.race thế nào?","answer":"any chờ fulfillment đầu tiên; race settle theo kết quả đầu tiên kể cả reject.","explanation":"Nếu mọi input reject, any reject với AggregateError theo JS semantics.","followUp":"Cả hai có tự hủy request còn lại không?","note":"async-patterns","level":"Vận dụng"},{"id":"eventleak","question":"Một event listener có thể gây leak thế nào?","answer":"Nó có thể giữ closure/object sống lâu hơn nhu cầu qua tham chiếu còn reachable.","explanation":"Gỡ listener/cleanup và đo heap theo lifecycle, không chỉ gọi GC.","followUp":"Delegation có loại bỏ mọi leak không?","note":"dom","level":"Vận dụng"},{"id":"shallow","question":"Spread có deep clone object không?","answer":"Không. Nó sao chép tầng ngoài, object con vẫn có thể chia sẻ.","explanation":"structuredClone/serializer có phạm vi hỗ trợ riêng.","followUp":"Sửa clone.address.city có thể đổi original không?","note":"async-patterns","level":"Vận dụng"},{"id":"infinite","question":"Promise.all cho 100.000 request có vấn đề gì?","answer":"Có thể tạo concurrency quá lớn, tăng memory và làm bão hòa client/server.","explanation":"Dùng pool/queue giới hạn concurrency và policy lỗi.","followUp":"Bạn chọn concurrency dựa trên metric nào?","note":"async-patterns","level":"Vận dụng"},{"id":"worker","question":"Web Worker có truy cập DOM như main thread không?","answer":"Không trực tiếp. Nó giao tiếp qua message/transfer theo API browser.","explanation":"Chi phí serialize/transfer và cập nhật UI cần được tính.","followUp":"Transferable ArrayBuffer giúp gì?","note":"loop","level":"Vận dụng"},{"id":"unicode","question":"Đếm string.length có luôn là số ký tự người dùng thấy không?","answer":"Không. JavaScript length tính UTF-16 code units; grapheme có thể gồm nhiều code point.","explanation":"Emoji/ký tự kết hợp cần thuật toán theo yêu cầu, có thể dùng Intl.Segmenter khi phù hợp.","followUp":"Reverse bằng split('') có thể làm hỏng gì?","note":"scope","level":"Vận dụng"}],"order":9},{"id":"typescript","title":"TypeScript & hợp đồng dữ liệu","group":"02 · Web & Frontend","description":"Dùng type để mô tả bất biến nhưng vẫn kiểm tra dữ liệu lúc chạy.","sources":[{"title":"TypeScript Handbook","url":"https://www.typescriptlang.org/docs/handbook/intro.html"}],"imageRefs":[],"prerequisites":["javascript"],"notes":[{"id":"types","title":"Type inference, union và narrowing","body":["TypeScript phân tích kiểu trước khi chạy; type thông thường bị xóa khi tạo JavaScript. Inference giảm khai báo lặp nhưng type ở ranh giới giúp hợp đồng rõ. Union biểu diễn nhiều khả năng; narrowing dùng điều kiện để xác định khả năng hiện tại."],"example":"type Result = { ok: true; value: number } | { ok: false; error: string };\nfunction show(r: Result) {\n  if (r.ok) return r.value.toFixed(2);\n  return r.error;\n}","pitfall":"Type assertion “as User” không kiểm tra JSON lúc chạy.","exercise":"Thiết kế trạng thái loading/success/error không cho success thiếu data.","diagram":{"type":"graph","title":"Discriminated union: các trạng thái hợp lệ","nodes":[[320,55,"Result"],[150,170,"ok: true"],[490,170,"ok: false"],[150,270,"value: number"],[490,270,"error: string"]],"edges":[[0,1],[0,2],[1,3],[2,4]],"caption":"Kiểm tra field ok giúp TypeScript narrow về đúng nhánh; không tồn tại trạng thái ok:true mà thiếu value theo type."}},{"id":"unknown","title":"unknown, any, never và null","body":["any tắt nhiều kiểm tra, dễ truyền rủi ro sang code khác. unknown buộc kiểm tra trước khi dùng; phù hợp dữ liệu chưa biết. never đại diện trạng thái không thể xảy ra và hỗ trợ exhaustive checking. strictNullChecks buộc xử lý null/undefined rõ hơn."],"example":"function parseName(value: unknown): string {\n  if (typeof value !== \"object\" || value === null || !(\"name\" in value))\n    throw new Error(\"Invalid object\");\n  if (typeof value.name !== \"string\") throw new Error(\"Invalid name\");\n  return value.name;\n}","pitfall":"Non-null assertion ! chỉ yêu cầu compiler tin bạn; không ngăn runtime null.","exercise":"Xóa một nhánh trong switch discriminated union và dùng never để phát hiện."},{"id":"generics","title":"Generics và utility types","body":["Generics giữ quan hệ kiểu giữa đầu vào/đầu ra, không chỉ viết một hàm nhận any. Constraint giới hạn thao tác được phép. Pick/Omit/Partial/Readonly hữu ích khi mô tả biến thể hợp đồng nhưng không thay thiết kế authorization cho API."],"example":"function first\u003cT>(items: readonly T[]): T | undefined { return items[0]; }\ntype PublicUser = Pick\u003cUser, \"id\" | \"name\">;","pitfall":"Omit password ở type không tự xóa thuộc tính password khỏi object runtime.","exercise":"Viết mapper trả PublicUser thực sự chỉ chứa field công khai."},{"id":"boundaries","title":"Type ở ranh giới API","body":["Tách input từ bên ngoài, domain model và response DTO. Parse/validate dữ liệu trước khi coi là domain object; kiểm tra cả định dạng và quy tắc nghiệp vụ. Schema validation có thể chia sẻ giữa client/server nhưng server vẫn giữ quyết định cuối.","TypeScript structural typing so hình dạng; hai object giống shape có thể được gán cho nhau. Với ID dễ nhầm như UserId/OrderId, có thể dùng branded type ở code và kiểm tra runtime ở ranh giới."],"example":"","pitfall":"Generated type từ OpenAPI có thể lệch server đang deploy; cần versioning và contract tests.","exercise":"Thiết kế API update profile chỉ cho sửa name, không cho sửa role."}],"questions":[{"id":"runtime","question":"TypeScript có validate dữ liệu API lúc chạy không?","answer":"Không tự động. Type thông thường được xóa và assertion không parse dữ liệu.","explanation":"Cần runtime validation tại ranh giới trước khi dùng dữ liệu.","followUp":"Bạn dùng unknown hay any cho response chưa xác thực?","note":"boundaries","level":"Cơ bản"},{"id":"unknown","question":"unknown tốt hơn any khi nào?","answer":"Khi chưa biết kiểu và muốn buộc nơi dùng kiểm tra trước.","explanation":"any dễ bỏ qua lỗi và lan sang các phép gán/lời gọi khác.","followUp":"Bạn narrow object có field name ra sao?","note":"unknown","level":"Cơ bản"},{"id":"union","question":"Discriminated union giúp gì?","answer":"Mô tả các trạng thái loại trừ nhau bằng một field phân biệt.","explanation":"Compiler thu hẹp field theo trạng thái; tránh tổ hợp boolean khó kiểm soát.","followUp":"Bạn biểu diễn request chưa gửi, đang tải, thành công, lỗi thế nào?","note":"types","level":"Cơ bản"},{"id":"never","question":"never dùng để làm gì?","answer":"Mô tả giá trị không thể có và kiểm tra mọi nhánh đã được xử lý.","explanation":"Nếu thêm loại event mới mà switch bỏ sót, exhaustive check có thể báo lỗi.","followUp":"Khác void thế nào?","note":"unknown","level":"Cơ bản"},{"id":"generics","question":"Generic khác any thế nào?","answer":"Generic giữ thông tin và quan hệ kiểu; any bỏ qua nhiều kiểm tra.","explanation":"Hàm identity\u003cT> trả đúng T, còn identity(any) làm mất quan hệ hữu ích.","followUp":"Constraint extends giúp gì?","note":"generics","level":"Cơ bản"},{"id":"interface","question":"type alias và interface nên chọn thế nào?","answer":"Cả hai mô tả nhiều object shape; type alias còn biểu diễn union và nhiều tổ hợp kiểu.","explanation":"Interface hỗ trợ declaration merging; chọn theo nhu cầu và convention thay vì coi một loại luôn tốt hơn.","followUp":"Khi nào cần union thay interface đơn?","note":"types","level":"Cơ bản"},{"id":"readonly","question":"Readonly có làm object runtime immutable không?","answer":"Không. Nó hạn chế phép gán qua type ở thời điểm kiểm tra.","explanation":"Thường là shallow; cần giải pháp runtime nếu bất biến là yêu cầu thực thi.","followUp":"Alias mutable khác có sửa cùng object được không?","note":"generics","level":"Cơ bản"},{"id":"partial","question":"Dùng Partial\u003cUser> làm input update có rủi ro gì?","answer":"Có thể cho phép field không nên sửa như id, role hoặc trạng thái quản trị.","explanation":"Thiết kế DTO whitelist rõ và authorize ở server.","followUp":"Omit trong type có lọc field trong request body không?","note":"boundaries","level":"Cơ bản"},{"id":"nonnull","question":"Dùng ! sau biến có kiểm tra null không?","answer":"Không. Nó bỏ cảnh báo compiler mà không thêm guard runtime.","explanation":"Nên xác thực invariant hoặc xử lý trường hợp thiếu.","followUp":"Bạn xử lý querySelector không tìm thấy element thế nào?","note":"unknown","level":"Cơ bản"},{"id":"structural","question":"Structural typing nghĩa là gì?","answer":"Khả năng tương thích chủ yếu dựa trên shape thay vì chỉ tên khai báo.","explanation":"Có thể dùng brand để phân biệt các ID cùng kiểu nền khi hữu ích.","followUp":"UserId và OrderId đều string có thể bị nhầm ở đâu?","note":"boundaries","level":"Cơ bản"}],"order":10},{"id":"react","title":"Component, State & React","group":"02 · Web & Frontend","description":"Xây UI từ dữ liệu, giữ state đúng chỗ và xử lý vòng đời rõ ràng.","sources":[{"title":"React Learn","url":"https://react.dev/learn"},{"title":"React Effects","url":"https://react.dev/learn/you-might-not-need-an-effect"}],"imageRefs":[],"prerequisites":["javascript","typescript"],"notes":[{"id":"components","title":"Component, props và render","body":["Component mô tả UI từ props/state. Props truyền dữ liệu từ cha xuống; state giữ dữ liệu cần nhớ qua render. Render nên thuần: không gửi request hoặc sửa DOM tùy ý ngay trong thân render. Một render có thể không dẫn tới DOM change nếu kết quả không đổi.","Key giúp React nhận diện item giữa các render trong cùng danh sách. Dùng ID ổn định thay vị trí khi có insert/reorder để state không gắn nhầm item."],"example":"function Product({ product, onSelect }) {\n  return \u003cbutton onClick={() => onSelect(product.id)}>{product.name}\u003c/button>;\n}","pitfall":"Không gọi component như hàm tùy ý nếu nó cần Hooks; dùng mô hình component theo React.","exercise":"Reorder danh sách input với key=index và quan sát state bị gắn sai."},{"id":"state","title":"Đặt state và dẫn xuất dữ liệu","body":["Giữ state tối thiểu, không lưu lại những giá trị có thể tính từ state/props hiện tại. Lift state lên ancestor chung khi nhiều component cần cùng nguồn sự thật. Khi cập nhật dựa trên giá trị trước đó, functional updater giúp tránh dùng snapshot cũ."],"example":"setCount(c => c + 1);\nsetCount(c => c + 1);\n// Hai cập nhật dựa trên state trước, không phải count từ cùng render","pitfall":"Không mutate state object rồi chờ UI phát hiện; tạo cấu trúc mới phù hợp.","exercise":"Giỏ hàng: lưu items và tính total thay vì giữ hai state có thể lệch nhau.","diagram":{"type":"flow","title":"Dữ liệu xuống, sự kiện lên","nodes":["State tại cha","Props tới component con","Người dùng thao tác","Callback yêu cầu cập nhật cha"],"caption":"Render tiếp theo phản ánh state mới; tránh hai nguồn sự thật cho cùng dữ liệu."}},{"id":"effects","title":"Effect để đồng bộ với hệ bên ngoài","body":["Effect phù hợp kết nối WebSocket, listener hoặc một hệ bên ngoài sau render. Tính toán giá trị dẫn xuất và xử lý hành động người dùng thường không cần Effect. Dependencies phản ánh các reactive value được dùng, không phải tùy ý bỏ để “chỉ chạy một lần”.","Cleanup gỡ tài nguyên trước khi effect chạy lại hoặc unmount. Development Strict Mode có thể chạy thêm chu kỳ setup/cleanup để phát hiện lỗi; code cần cleanup đúng thay vì che chu kỳ đó."],"example":"useEffect(() => {\n  const connection = connect(roomId);\n  connection.open();\n  return () => connection.close();\n}, [roomId]);","pitfall":"Effect fetch cần xử lý request cũ, hủy hoặc bỏ qua kết quả cũ.","exercise":"Tạo component đổi room nhanh mà không để kết nối cũ còn sống."},{"id":"app","title":"Forms, routing, server state và performance","body":["Controlled input lấy value từ state và cập nhật bằng event. UI cần loading, empty, error và success. Client state như modal mở khác server state như danh sách đơn hàng có freshness/cache/invalidation. Routing cần xét URL, deep link và quyền truy cập phía server.","Memoization là tối ưu có chi phí; đo bằng profiler trước. React.memo/useMemo/useCallback không thay việc chia component, tránh render cascade và chọn cấu trúc dữ liệu đúng."],"example":"","pitfall":"useMemo không nên được dùng để tạo side effect hoặc bảo đảm correctness.","exercise":"Thiết kế trang tìm sản phẩm có URL query, debounce, hủy request, empty state và retry."},{"id":"component-tree","title":"Component tree và ownership state","body":["State nên ở ancestor gần nhất cần sở hữu quyết định. Context giúp truyền dữ liệu qua cây mà không chuyền props từng tầng, nhưng không tự thay state management hay miễn render. Reducer mô tả state transition rõ khi nhiều hành động liên quan; không cần reducer cho mọi input.","Server cache, URL state và local UI state có lifecycle khác nhau. Đồng bộ hai nguồn sự thật bằng effects tùy ý dễ gây loop hoặc stale state. Đặt tên nguồn chính và cách chuyển dữ liệu trước khi chọn library."],"example":"","pitfall":"","exercise":"Chọn nơi giữ filter: state cục bộ hay URL để chia sẻ/deep-link?","diagram":{"type":"graph","title":"Giỏ hàng: một nguồn state, nhiều nơi đọc","nodes":[[320,55,"Cart state"],[120,165,"Product list"],[320,165,"Cart badge"],[520,165,"Checkout"]],"edges":[[0,1],[0,2],[0,3]],"caption":"Các con nhận dữ liệu/hành động từ owner. Cập nhật hợp lệ tạo render mới, không mutate state chung tùy ý."}}],"questions":[{"id":"props","question":"Props và state khác nhau thế nào?","answer":"Props là input từ bên ngoài component; state là dữ liệu component nhớ và cập nhật qua API của React.","explanation":"Cả hai tạo snapshot cho render; không sửa trực tiếp props/state.","followUp":"Khi nào lift state lên cha?","note":"state","level":"Cơ bản"},{"id":"render","question":"Component render lại có nghĩa DOM đổi không?","answer":"Không. React tính kết quả rồi cập nhật DOM khi cần theo quá trình reconciliation/commit.","explanation":"Render nên thuần để an toàn khi được gọi lại.","followUp":"Vì sao không fetch trong thân render?","note":"components","level":"Cơ bản"},{"id":"key","question":"Vì sao tránh key=index cho danh sách có reorder?","answer":"Index có thể trỏ tới item khác sau thay đổi, làm state gắn sai identity.","explanation":"ID ổn định giúp giữ trạng thái đúng item; key chỉ có ý nghĩa trong ngữ cảnh sibling.","followUp":"Form đang nhập sẽ ra sao khi chèn item đầu danh sách?","note":"components","level":"Cơ bản"},{"id":"batch","question":"setCount(count+1) hai lần có luôn tăng 2 không?","answer":"Không. Cả hai có thể dùng cùng snapshot count.","explanation":"Functional updater xử lý cập nhật dựa trên trạng thái trước theo hàng đợi.","followUp":"setCount(c=>c+1) khác thế nào?","note":"state","level":"Vận dụng"},{"id":"effect","question":"Khi nào không cần useEffect?","answer":"Khi chỉ tính dữ liệu dẫn xuất hoặc xử lý trực tiếp một hành động người dùng.","explanation":"Dùng effect để sao chép state dễ tạo render thừa và lệch nguồn sự thật.","followUp":"Lọc danh sách theo query nên tính ở đâu?","note":"effects","level":"Cơ bản"},{"id":"cleanup","question":"Cleanup của Effect dùng để làm gì?","answer":"Dừng đồng bộ hoặc giải phóng tài nguyên từ lần setup tương ứng.","explanation":"Ví dụ unsubscribe, đóng connection, xóa timer; cần an toàn khi setup lại.","followUp":"Nếu dependency đổi nhưng không unmount thì cleanup có cần không?","note":"effects","level":"Cơ bản"},{"id":"deps","question":"Bỏ dependency để effect không chạy lại có nên không?","answer":"Không nên nếu effect thực sự dùng reactive value đó.","explanation":"Nó có thể giữ closure cũ; cần sửa thiết kế hoặc dependency thay vì che cảnh báo.","followUp":"Bạn tách giá trị không reactive bằng cách nào?","note":"effects","level":"Cơ bản"},{"id":"controlled","question":"Controlled input khác uncontrolled thế nào?","answer":"Controlled lấy value từ state; uncontrolled để DOM giữ giá trị chính và đọc qua cơ chế phù hợp.","explanation":"Chọn theo nhu cầu validation, integration và performance.","followUp":"Chuyển từ undefined sang string có vấn đề gì?","note":"app","level":"Cơ bản"},{"id":"memo","question":"Có nên dùng useMemo cho mọi phép tính?","answer":"Không. Nó thêm chi phí và độ phức tạp; ưu tiên đo điểm nghẽn.","explanation":"Correctness không nên phụ thuộc cache memo còn tồn tại.","followUp":"Bạn dùng React Profiler để chứng minh lợi ích thế nào?","note":"app","level":"Cơ bản"},{"id":"serverstate","question":"Server state khác UI state ở điểm nào?","answer":"Server state có nguồn sự thật từ xa, freshness và đồng bộ; UI state thường cục bộ theo tương tác.","explanation":"Cache invalidation, optimistic update và lỗi cần chiến lược riêng.","followUp":"Mutation thành công cần cập nhật danh sách nào?","note":"app","level":"Cơ bản"},{"id":"context","question":"Context có thay thế mọi state management không?","answer":"Không. Nó là cơ chế truyền dữ liệu qua cây; lifecycle, update và server cache vẫn cần thiết kế.","explanation":"Context value thay đổi có thể làm consumer render; đo trước tối ưu.","followUp":"Chia context theo tần suất thay đổi có ích gì?","note":"component-tree","level":"Đào sâu"},{"id":"reducer","question":"Khi nào useReducer có ích?","answer":"Khi nhiều transition liên quan cần mô tả tập trung và kiểm tra rõ.","explanation":"Reducer nên thuần; side effect ở ranh giới thích hợp, không trong reducer.","followUp":"Action có cần chứa toàn object UI không?","note":"component-tree","level":"Đào sâu"},{"id":"optimistic","question":"Optimistic UI cần xử lý gì khi server từ chối?","answer":"Rollback hoặc reconcile trạng thái với nguồn chính và thông báo phù hợp.","explanation":"Cần xử lý mutation cạnh tranh, response sai thứ tự và cache invalidation.","followUp":"Hai lần thay đổi cùng item thì rollback bản nào?","note":"app","level":"Đào sâu"},{"id":"ssrsecurity","question":"SSR có nghĩa dữ liệu riêng không bao giờ tới client không?","answer":"Không. Bất kỳ dữ liệu serialize vào HTML/hydration payload đều có thể bị người nhận đọc.","explanation":"Chỉ gửi field cần thiết theo quyền; không embed server secret.","followUp":"DTO public cần được tạo thực sự hay chỉ Omit type?","note":"app","level":"Đào sâu"}],"order":11},{"id":"rendering","title":"Rendering & hiệu năng Frontend","group":"02 · Web & Frontend","description":"Hiểu đường render và chọn CSR, SSR, SSG theo trải nghiệm cần đạt.","sources":[{"title":"web.dev Performance","url":"https://web.dev/learn/performance"},{"title":"MDN rendering","url":"https://developer.mozilla.org/en-US/docs/Web/Performance/Guides/How_browsers_work"}],"imageRefs":[],"prerequisites":["html-css","javascript","react"],"notes":[{"id":"pipeline","title":"Browser render và layout","body":["Browser xây DOM/CSSOM, xác định style, layout, paint và compositing theo công việc cần làm. Thay đổi geometry có thể yêu cầu layout; một số animation transform/opacity có thể được compositor xử lý nhưng không nên khẳng định luôn miễn phí.","Đọc layout sau khi liên tục ghi style có thể ép synchronous layout. Gom đọc/ghi, giảm DOM quá lớn và dùng DevTools để đo công việc thực sự."],"example":"// Gom đọc trước, ghi sau\nconst width = element.getBoundingClientRect().width;\nitems.forEach(item => { item.style.width = `${width}px`; });","pitfall":"Không phải mọi DOM update đều kích hoạt toàn bộ pipeline cho toàn trang.","exercise":"Ghi performance trace khi mở một danh sách lớn rồi xác định long task.","diagram":{"type":"flow","title":"Một đường render giản lược","nodes":["HTML/CSS → DOM/CSSOM","Style","Layout · vị trí/kích thước","Paint → Composite"],"caption":"Browser có thể bỏ qua hoặc giới hạn các bước tùy thay đổi và implementation."}},{"id":"modes","title":"CSR, SSR, SSG và hydration","body":["CSR dựng phần lớn UI bằng JavaScript ở client; SSR tạo HTML theo request; SSG tạo HTML trước khi phục vụ. Chúng có thể kết hợp theo route hoặc từng phần. Hydration gắn hành vi ứng dụng vào HTML dựng sẵn, cần đồng nhất dữ liệu/kết quả render ban đầu.","SSR có thể cải thiện nội dung ban đầu nhưng thêm compute/cache và không tự làm tương tác nhanh. Chọn theo freshness, SEO, personalization, tải JS và hạ tầng."],"example":"","pitfall":"HTML server có sẵn không có nghĩa browser đã tải và thực thi đủ JS để tương tác.","exercise":"Chọn cách render cho blog, dashboard riêng tư và trang sản phẩm thay đổi tồn kho."},{"id":"vitals","title":"Đo trải nghiệm thay vì chỉ bundle size","body":["LCP phản ánh thời điểm nội dung lớn nhất được hiển thị theo định nghĩa metric; INP phản ánh responsiveness; CLS phản ánh layout shift ngoài mong đợi. Dữ liệu lab giúp tái hiện; field data phản ánh thiết bị/mạng thật. Nhìn phân phối theo nhóm người dùng, không chỉ một lần chạy máy mạnh.","Ảnh đúng kích thước, reserved dimensions, font strategy, code splitting và ưu tiên tài nguyên quan trọng thường có ích. Tối ưu phải đo tác động sau thay đổi."],"example":"","pitfall":"Lazy-load ảnh hero có thể làm LCP tệ hơn; ưu tiên tài nguyên phải theo vị trí và vai trò.","exercise":"Tìm phần tử LCP và nguyên nhân delay của một trang bằng DevTools."},{"id":"delivery","title":"Cache asset, chia code và progressive enhancement","body":["Asset có tên gắn content hash có thể cache dài; HTML cần policy phù hợp để trỏ tới phiên bản mới. Chia code theo route/feature giúp tránh tải chức năng chưa dùng, nhưng quá nhiều request nhỏ cũng có chi phí.","Progressive enhancement giữ chức năng cơ bản từ HTML rồi thêm JS. Khi JS lỗi hoặc mạng chậm, người học vẫn nên đọc được nội dung thiết yếu. Khả năng truy cập và offline cần kiểm tra thay vì suy từ framework."],"example":"Cache-Control: public, max-age=31536000, immutable\n# Chỉ dùng khi URL asset thay đổi theo nội dung.","pitfall":"Đừng dùng cache bất biến dài hạn cho file JS có tên cố định nhưng liên tục ghi đè.","exercise":"Thiết kế deployment tránh HTML mới tham chiếu asset đã bị xóa."}],"questions":[{"id":"csr","question":"CSR, SSR và SSG khác nhau ở đâu?","answer":"Khác nơi/thời điểm tạo HTML: client, theo request ở server hoặc trước khi phục vụ.","explanation":"Một app có thể dùng nhiều chế độ; chọn theo từng route.","followUp":"Dashboard riêng tư có cần SSR vì SEO không?","note":"modes","level":"Cơ bản"},{"id":"hydrate","question":"Hydration mismatch là gì?","answer":"Kết quả render ban đầu phía client không khớp HTML/dữ liệu server gửi.","explanation":"Thời gian, random và dữ liệu khác phiên bản có thể gây lệch; cần invariant rõ.","followUp":"Date.now trong render có thể gây gì?","note":"modes","level":"Đào sâu"},{"id":"layout","question":"Layout thrashing là gì?","answer":"Đọc geometry xen kẽ ghi style khiến browser phải tính layout lặp.","explanation":"Gom công việc và đo bằng performance trace; không chỉ đo số dòng code.","followUp":"getBoundingClientRect có thể kích hoạt công việc gì?","note":"pipeline","level":"Cơ bản"},{"id":"lcp","question":"Tối ưu LCP bắt đầu từ đâu?","answer":"Xác định phần tử LCP và phân rã thời gian mạng, tải tài nguyên, render.","explanation":"Ảnh, font, server latency hoặc JS có thể là nguyên nhân khác nhau.","followUp":"Vì sao lazy-load ảnh đầu trang có thể hại?","note":"vitals","level":"Cơ bản"},{"id":"cls","question":"Làm sao giảm layout shift?","answer":"Dành sẵn kích thước ảnh/embed, quản lý font và tránh chèn nội dung đẩy UI bất ngờ.","explanation":"Cần đo shift thực tế; animation làm thay đổi geometry có thể góp phần.","followUp":"Loading skeleton nên có kích thước ra sao?","note":"vitals","level":"Cơ bản"},{"id":"inp","question":"Bundle nhỏ có bảo đảm UI responsive không?","answer":"Không. Handler CPU nặng và long task vẫn có thể chặn main thread.","explanation":"Đo interaction latency; tách việc, giảm compute hoặc dùng worker khi phù hợp.","followUp":"Bạn kiểm tra một click mất 800ms thế nào?","note":"vitals","level":"Cơ bản"},{"id":"split","question":"Code splitting có nhược điểm gì?","answer":"Thêm điểm tải/đợi, lỗi chunk và chi phí phối hợp cache/version.","explanation":"Cần fallback, retry hợp lý và tránh chia quá vụn.","followUp":"Route cũ sau deploy gọi chunk bị xóa thì sao?","note":"delivery","level":"Cơ bản"},{"id":"cache","question":"Vì sao asset content hash có thể cache dài?","answer":"Nội dung mới tạo URL mới nên bản cache cũ không bị dùng thay cho bản mới cùng URL.","explanation":"HTML và manifest vẫn cần cơ chế cập nhật phù hợp.","followUp":"Đặt immutable cho app.js cố định có rủi ro gì?","note":"delivery","level":"Cơ bản"},{"id":"lab","question":"Lab data và field data khác nhau thế nào?","answer":"Lab có môi trường kiểm soát; field thu từ trải nghiệm người dùng thật.","explanation":"Cần cả hai để tái hiện và xác nhận ảnh hưởng thực tế.","followUp":"Bạn chia nhóm thiết bị/mạng thế nào?","note":"vitals","level":"Cơ bản"},{"id":"ssr","question":"SSR có luôn nhanh hơn CSR không?","answer":"Không. Nó đổi trade-off giữa HTML sớm, server cost, cache và hydration/JS.","explanation":"Đánh giá theo workload và metric người dùng, không dựa tên kỹ thuật.","followUp":"Khi nào SSG đơn giản hơn cả hai?","note":"modes","level":"Đào sâu"}],"order":12},{"id":"backend","title":"Backend & luồng ứng dụng","group":"03 · Backend & API","description":"Nối Frontend, API, nghiệp vụ và dữ liệu thành một luồng hoàn chỉnh.","sources":[{"title":"MDN server-side","url":"https://developer.mozilla.org/en-US/docs/Learn_web_development/Extensions/Server-side/First_steps"}],"imageRefs":["A02","A05","F02"],"prerequisites":["network","programming"],"notes":[{"id":"request","title":"Luồng FE → API → BE → dữ liệu","body":["Frontend nhận tương tác và tạo request; reverse proxy/gateway có thể routing và áp dụng policy; middleware xử lý cross-cutting concerns; handler/service thực hiện nghiệp vụ; repository truy cập database. Response đi ngược về client để cập nhật UI.","Mỗi tầng có trách nhiệm riêng: input hợp lệ chưa đồng nghĩa user được quyền thao tác; query thành công chưa đồng nghĩa toàn bộ nghiệp vụ hoàn tất. Đặt request ID để nối các bước khi điều tra lỗi."],"example":"","pitfall":"","exercise":"Thêm payment provider và chỉ ra nơi không thể dùng một DB transaction để bao tất cả.","diagram":{"type":"sequence","title":"Ví dụ đặt hàng","actors":["Frontend","API / Middleware","Order Service","Database"],"steps":[[0,1,"POST /orders + thông tin xác thực"],[1,2,"Input hợp lệ, user đã được xác định"],[2,3,"Transaction: tồn kho + đơn hàng"],[3,2,"Commit hoặc rollback"],[2,1,"Kết quả nghiệp vụ"],[1,0,"201 + order ID hoặc lỗi có mã"]],"caption":"Client chỉ gọi API; kiểm tra quyền và tồn kho vẫn thực hiện ở server."}},{"id":"layers","title":"Controller, service, repository và middleware","body":["Controller chuyển HTTP thành input và response; service giữ quy tắc nghiệp vụ/use case; repository xử lý truy vấn/lưu trữ; middleware xử lý những việc phù hợp chuỗi request như auth, request ID và giới hạn body.","Không bắt buộc mỗi layer là một thư mục hoặc interface. Ranh giới có ích khi thay đổi độc lập, kiểm thử dễ và transaction được quản lý rõ. Logic phân quyền theo tài nguyên thường cần dữ liệu nghiệp vụ, không chỉ middleware xác thực."],"example":"// Pseudocode\nconst input = parseOrder(req.body);\nconst result = await placeOrder({ userId: req.user.id, input });\nres.status(201).json(result);","pitfall":"Đưa mọi logic vào controller làm test phụ thuộc HTTP; tạo layer chỉ chuyển tiếp cũng có thể thừa.","exercise":"Tách một handler vừa parse input, query DB, tính tiền và gửi email thành các trách nhiệm rõ."},{"id":"config","title":"Config, secrets và dependency lifecycle","body":["Cấu hình khác môi trường nên truyền từ ngoài code, kiểm tra lúc khởi động và báo lỗi rõ khi thiếu. Secrets cần quản lý vòng đời, quyền đọc và luân chuyển. Không log toàn bộ environment hoặc connection string.","Khởi tạo pool/client có vòng đời rõ để tái sử dụng, đóng khi shutdown. Một process nhiều request không nên tạo connection pool riêng cho từng request. Timeout và cancellation cần truyền xuyên các dependency khi hỗ trợ."],"example":"","pitfall":"Biến môi trường không tự là secret vault; người có quyền truy cập process/hạ tầng vẫn có thể đọc.","exercise":"Lập danh sách cấu hình bắt buộc và cách ứng dụng fail fast khi thiếu."},{"id":"errors","title":"Validation, error contract và tác dụng phụ","body":["Validate cả shape, giới hạn và quy tắc nghiệp vụ. Trả lỗi có mã ổn định, thông điệp hữu ích và request ID; không lộ stack trace hay query/secret. Client cần phân biệt lỗi có thể sửa với lỗi tạm thời.","Tác dụng phụ như gửi email sau ghi DB cần chiến lược nếu process chết giữa hai bước. Transactional outbox lưu ý định phát sự kiện cùng transaction, rồi worker gửi sau với khả năng lặp an toàn."],"example":"{\"error\":{\"code\":\"OUT_OF_STOCK\",\"message\":\"Sản phẩm đã hết hàng\",\"requestId\":\"r-42\"}}","pitfall":"Trả HTTP 200 cho mọi lỗi khiến monitoring và client khó hiểu hợp đồng.","exercise":"Thiết kế lỗi cho request sai kiểu, không có quyền, hết hàng và database timeout."}],"questions":[{"id":"frontend","question":"Frontend và Backend khác nhau ở trách nhiệm gì?","answer":"Frontend trình bày/tương tác; Backend giữ xử lý server, quyền truy cập và nghiệp vụ/data theo kiến trúc.","explanation":"Client không được coi là đáng tin; quy tắc quan trọng phải được thực thi ở server.","followUp":"Giá tiền có nên lấy nguyên từ request của client không?","note":"request","level":"Cơ bản"},{"id":"middleware","question":"Middleware là gì?","answer":"Một thành phần trong pipeline xử lý request/response hoặc cơ chế tương đương của framework.","explanation":"Thứ tự ảnh hưởng auth, body parsing, logging và error handling.","followUp":"Middleware auth có đủ để kiểm tra quyền sở hữu order không?","note":"layers","level":"Cơ bản"},{"id":"service","question":"Service layer nên chứa gì?","answer":"Use case và quy tắc nghiệp vụ độc lập nhất có thể với HTTP representation.","explanation":"Tách dependency để test nhưng tránh tạo lớp chuyển tiếp không mang giá trị.","followUp":"Transaction nhiều repository nên bắt đầu ở đâu?","note":"layers","level":"Cơ bản"},{"id":"stateless","question":"Stateless backend có nghĩa không lưu dữ liệu không?","answer":"Không. Nó thường không dựa vào trạng thái phiên cục bộ của instance giữa request.","explanation":"Dữ liệu có thể nằm trong DB/session store chung để replica khác xử lý được.","followUp":"JWT có tự làm cả hệ thống hoàn toàn stateless không?","note":"config","level":"Cơ bản"},{"id":"validate","question":"Validation khác authorization thế nào?","answer":"Validation kiểm tra dữ liệu/hợp đồng; authorization quyết định chủ thể có được thực hiện hành động trên tài nguyên không.","explanation":"Input đúng shape vẫn có thể yêu cầu truy cập tài nguyên của người khác.","followUp":"Bạn kiểm tra tenant_id từ client thế nào?","note":"errors","level":"Vận dụng"},{"id":"pool","question":"Vì sao không tạo DB pool cho mỗi request?","answer":"Nó gây churn, tăng kết nối và có thể vượt giới hạn database.","explanation":"Pool nên có lifecycle, giới hạn và thời gian chờ; số replica nhân tổng kết nối.","followUp":"20 replica, mỗi pool 30 connection ảnh hưởng gì?","note":"config","level":"Vận dụng"},{"id":"error","question":"Một response lỗi tốt cần gì?","answer":"Status phù hợp, mã ổn định, thông tin có thể hành động và correlation/request ID.","explanation":"Thông tin nội bộ nên ở log được bảo vệ; không trả stack/secret cho client.","followUp":"Bạn biểu diễn lỗi validation nhiều field thế nào?","note":"errors","level":"Vận dụng"},{"id":"money","question":"Tại sao không tin total gửi từ client?","answer":"Client có thể sửa request; server phải tính lại từ nguồn giá và policy được kiểm soát.","explanation":"Cần xét tiền tệ, rounding, promotion và phiên bản giá theo nghiệp vụ.","followUp":"Giá đổi giữa xem giỏ và checkout thì xử lý sao?","note":"request","level":"Vận dụng"},{"id":"email","question":"Ghi đơn thành công rồi gửi email lỗi thì làm gì?","answer":"Tách email thành tác vụ có thể retry và lưu ý định đáng tin, thường qua outbox/queue.","explanation":"Không rollback máy móc một đơn đã commit chỉ vì notification lỗi.","followUp":"Làm sao tránh email gửi hai lần?","note":"errors","level":"Vận dụng"},{"id":"shutdown","question":"Backend shutdown có trật tự gồm những bước gì?","answer":"Ngừng nhận việc mới, xử lý/nhả việc đang chạy trong deadline rồi đóng tài nguyên.","explanation":"Phải phối hợp load balancer, readiness và queue ACK; cuối cùng có thể bị kill.","followUp":"Request đang ghi DB có nên ngắt ngay không?","note":"config","level":"Vận dụng"}],"order":13},{"id":"nodejs","title":"Node.js, Event Loop & Express","group":"03 · Backend & API","description":"Hiểu I/O bất đồng bộ và tránh chặn luồng xử lý request.","sources":[{"title":"Node event loop","url":"https://nodejs.org/learn/asynchronous-work/event-loop-timers-and-nexttick"},{"title":"Express errors","url":"https://expressjs.com/en/guide/error-handling/"}],"imageRefs":["A05","A16","F06–F09"],"prerequisites":["javascript","backend"],"notes":[{"id":"runtime","title":"V8, libuv và mô hình thực thi","body":["V8 thực thi JavaScript; Node cung cấp API runtime và tích hợp hệ điều hành. libuv hỗ trợ event loop và thread pool cho một số công việc. Network I/O thường dựa vào cơ chế OS; không nên mô tả mọi async call đều chạy trong thread pool.","JavaScript callback mặc định chạy trên một thread của event loop đó, nhưng process còn có thread khác và có thể dùng worker_threads. Concurrency I/O không loại được CPU bottleneck."],"example":"","pitfall":"","exercise":"Phân loại readFile, network socket, JSON.parse lớn và PBKDF2 theo loại công việc.","diagram":{"type":"flow","title":"Runtime Node.js giản lược","nodes":["JavaScript / V8","Node APIs","libuv + hệ điều hành","I/O hoàn tất → callback"],"caption":"Một số API dùng worker pool; đường đi cụ thể phụ thuộc API và nền tảng."}},{"id":"event-loop","title":"Event loop, microtask và timer","body":["Các phase liên quan timers, pending callbacks, poll, check và close callbacks. Promise microtasks và process.nextTick có cơ chế xếp lịch riêng; nextTick dùng quá mức có thể làm I/O bị trì hoãn. Thứ tự chi tiết phụ thuộc ngữ cảnh, CommonJS/ESM và phiên bản runtime.","Không học một thứ tự setTimeout(0)/setImmediate áp dụng cho mọi nơi. Ghi rõ môi trường và chạy ví dụ để quan sát; hành vi timer/libuv có thể thay đổi theo phiên bản."],"example":"setImmediate(() => console.log(\"check\"));\nsetTimeout(() => console.log(\"timer\"), 0);\n// Không khẳng định một thứ tự toàn cục cho mọi ngữ cảnh.","pitfall":"await một hàm sync CPU-heavy không biến nó thành non-blocking.","exercise":"So sánh timer/immediate ở top-level và trong callback I/O, ghi phiên bản Node."},{"id":"express","title":"Routing, middleware và lỗi async","body":["Express đi qua middleware theo thứ tự đăng ký. Middleware có thể kết thúc response hoặc chuyển tiếp bằng next. Error middleware nhận bốn tham số và cần đứng sau các route liên quan.","Express 5 tự chuyển rejection/throw từ handler trả Promise sang error handling; Express 4 thường cần wrapper/next(err). Ghi rõ phiên bản để ví dụ không gây unhandled rejection hoặc request treo. Không tiếp tục gửi response sau khi đã gửi."],"example":"// Express 5\napp.get(\"/users/:id\", async (req, res) => {\n  const user = await loadUser(req.params.id);\n  res.json(user);\n});\napp.use((err, req, res, next) => {\n  if (res.headersSent) return next(err);\n  res.status(500).json({ error: \"INTERNAL_ERROR\" });\n});","pitfall":"Không log raw body/headers có token trong middleware chung.","exercise":"Thử route resolve/reject và xác nhận request luôn kết thúc với response đúng.","diagram":{"type":"flow","title":"Một middleware pipeline theo thứ tự","nodes":["Request ID / logging","Body parser + size limit","Xác thực / routing","Handler + quyền tài nguyên","Response hoặc error middleware"],"caption":"Một middleware có thể kết thúc response sớm; thứ tự thật theo app.use/route registration và phiên bản Express."}},{"id":"throughput","title":"Streams, backpressure và công việc CPU","body":["Stream xử lý dữ liệu theo phần thay vì giữ toàn bộ file trong RAM. Backpressure cho producer biết downstream chưa theo kịp. pipeline giúp phối hợp lỗi và cleanup; vẫn phải giới hạn kích thước, timeout và quyền truy cập.","CPU-heavy work có thể chuyển worker/process/job queue; tăng replica không sửa thuật toán quá đắt hay database nghẽn. Theo dõi event loop lag cùng CPU, memory và latency để chọn cách tối ưu."],"example":"// Node.js\nimport { pipeline } from \"node:stream/promises\";\nawait pipeline(readable, transform, writable);","pitfall":"Stream không đồng nghĩa vô hạn bộ nhớ an toàn nếu bạn tự gom mọi chunk vào array.","exercise":"Thiết kế endpoint export dữ liệu lớn, có client disconnect và giới hạn tài nguyên."}],"questions":[{"id":"single","question":"Node.js có hoàn toàn single-threaded không?","answer":"Không. JavaScript mặc định có một event-loop thread, nhưng runtime/OS có thread khác và có worker threads.","explanation":"Đừng nhầm execution model của JS với toàn bộ process.","followUp":"Worker pool và worker_threads khác nhau thế nào?","note":"runtime","level":"Cơ bản"},{"id":"io","question":"Mọi I/O async đều chạy trong libuv thread pool đúng không?","answer":"Không. Đường xử lý phụ thuộc API; network thường dùng cơ chế I/O của OS.","explanation":"Một số file/crypto operations dùng thread pool; cần đo và đọc tài liệu API.","followUp":"Pool bị bão hòa ảnh hưởng API khác thế nào?","note":"runtime","level":"Cơ bản"},{"id":"timer","question":"setTimeout(0) và setImmediate cái nào chạy trước?","answer":"Không có câu trả lời đúng cho mọi ngữ cảnh.","explanation":"Nơi schedule, I/O và phiên bản runtime ảnh hưởng thứ tự.","followUp":"Trong callback I/O thì thường phase nào được xét tiếp?","note":"event-loop","level":"Cơ bản"},{"id":"nexttick","question":"Dùng process.nextTick đệ quy có rủi ro gì?","answer":"Có thể làm đói event loop và trì hoãn I/O.","explanation":"Ưu tiên thiết kế scheduling có giới hạn; không coi nextTick là cách tăng tốc mặc định.","followUp":"Bạn nhận biết event loop bị starvation bằng metric gì?","note":"event-loop","level":"Đào sâu"},{"id":"cpu","question":"async function có vòng lặp CPU nặng có chặn không?","answer":"Có. Phần sync của nó vẫn chạy trên thread hiện tại.","explanation":"Promise/await không tự offload compute; cân nhắc worker hoặc job queue.","followUp":"Bạn chia nhỏ hay chuyển worker dựa trên điều gì?","note":"throughput","level":"Vận dụng"},{"id":"next","question":"Quên next hoặc response trong middleware gây gì?","answer":"Request có thể không đi tiếp và chờ tới timeout.","explanation":"Mỗi nhánh cần có cách hoàn tất hoặc truyền xử lý rõ ràng.","followUp":"Gọi next sau res.json có thể gây vấn đề gì?","note":"express","level":"Cơ bản"},{"id":"asyncerror","question":"Express 4 và 5 khác nhau ở lỗi Promise ra sao?","answer":"Express 5 hỗ trợ tự chuyển rejection từ Promise handler; Express 4 thường cần chuyển next(err) rõ.","explanation":"Ví dụ phải gắn phiên bản; lỗi ngoài Promise chain vẫn cần xử lý thích hợp.","followUp":"Bạn test handler reject bằng integration test thế nào?","note":"express","level":"Đào sâu"},{"id":"stream","question":"Backpressure là gì?","answer":"Cơ chế downstream làm chậm hoặc tạm dừng upstream khi xử lý không kịp.","explanation":"Không có nó, buffer có thể tăng tới hết RAM.","followUp":"Writable.write trả false thì producer nên làm gì?","note":"throughput","level":"Cơ bản"},{"id":"modules","question":"require và import khác nhau thế nào?","answer":"Chúng thuộc CommonJS và ES Modules với quy tắc loading/export và ngữ cảnh khác nhau.","explanation":"Interop phụ thuộc Node/config; không chỉ là hai cách viết cùng một lệnh.","followUp":"package.json type ảnh hưởng file .js thế nào?","note":"runtime","level":"Cơ bản"},{"id":"lag","question":"CPU thấp nhưng request Node chậm có thể do đâu?","answer":"I/O, pool DB, dependency latency, queue hoặc giới hạn concurrency.","explanation":"Đối chiếu event loop lag, traces và thời gian chờ; đừng chỉ tăng thread pool.","followUp":"Nếu event loop lag cao thì bạn kiểm tra gì trước?","note":"throughput","level":"Vận dụng"}],"order":14},{"id":"api","title":"API, realtime & webhook","group":"03 · Backend & API","description":"Thiết kế hợp đồng dễ dùng, an toàn khi retry và tương thích khi thay đổi.","sources":[{"title":"HTTP semantics RFC 9110","url":"https://www.rfc-editor.org/rfc/rfc9110.html"},{"title":"OpenAPI","url":"https://spec.openapis.org/oas/latest.html"}],"imageRefs":["A04","D04","D12","F04","F16"],"prerequisites":["backend","network"],"notes":[{"id":"contract","title":"Resource, hợp đồng và versioning","body":["Thiết kế API bắt đầu từ use case, tài nguyên, quyền, input/output và lỗi. Dùng đường dẫn/method nhất quán, không biến mọi thao tác thành GET. REST là architectural style, không đồng nghĩa chỉ JSON CRUD. GraphQL cho client chọn dữ liệu nhưng cần giới hạn query; gRPC dùng hợp đồng/service và phù hợp nhiều giao tiếp nội bộ.","OpenAPI mô tả hợp đồng để review, tạo client và test. Thêm field thường dễ tương thích hơn đổi kiểu/xóa field; phải xét client có parse chặt hay không."],"example":"GET /orders?status=paid&limit=20\nPOST /orders\nGET /orders/{id}\n# Response cần quy ước time zone, tiền tệ và nullable fields.","pitfall":"","exercise":"Thiết kế API hủy đơn có điều kiện trạng thái và response khi đơn đã giao."},{"id":"pagination","title":"Pagination, filtering và thứ tự ổn định","body":["Offset dễ triển khai và nhảy trang nhưng offset lớn có thể tốn chi phí; dữ liệu thay đổi khiến trùng/bỏ sót giữa trang. Cursor dựa trên vị trí theo sort key, cần tie-breaker ổn định như (created_at, id). Cursor nên opaque ở hợp đồng client, có validation và không phải bằng chứng được quyền đọc."],"example":"SELECT id, created_at FROM orders\nWHERE (created_at, id) \u003c ($1, $2)\nORDER BY created_at DESC, id DESC\nLIMIT 20; -- PostgreSQL, cursor theo cặp khóa","pitfall":"ORDER BY created_at đơn lẻ không ổn định khi nhiều hàng trùng timestamp.","exercise":"Thiết kế cursor cho danh sách có lọc theo tenant và status."},{"id":"idempotency","title":"Idempotency key và chống xử lý trùng","body":["POST quan trọng như thanh toán cần một key đại diện một ý định nghiệp vụ. Server lưu key cùng fingerprint input, trạng thái và kết quả trong phạm vi user/operation. Cần ràng buộc unique và phối hợp transaction để hai request đồng thời không cùng thực hiện.","Key lặp với payload khác nên bị từ chối theo hợp đồng. Thời gian giữ key, trạng thái đang xử lý và cách phục hồi sau crash phải được xác định. Cache response đơn thuần ở RAM của một instance không đủ cho nhiều replica."],"example":"","pitfall":"","exercise":"Mô phỏng hai request cùng key đến hai replica đồng thời.","diagram":{"type":"flow","title":"Retry cùng một ý định","nodes":["Nhận key + payload","Claim key bằng unique constraint","Thực hiện + lưu kết quả","Retry đọc lại kết quả đã lưu"],"caption":"Tác dụng phụ tới hệ bên ngoài cần cơ chế idempotency/outbox tương ứng; không chỉ khóa trong process."}},{"id":"realtime","title":"Polling, SSE, WebSocket và webhook","body":["Polling đơn giản nhưng có độ trễ/chi phí request; SSE là stream server→client trên HTTP; WebSocket hỗ trợ hai chiều. Cả hai cần quản lý reconnect, auth, heartbeat và cách lấy lại sự kiện bỏ lỡ.","Webhook là server gọi endpoint của bên khác khi có sự kiện. Xác minh signature trên raw payload theo hợp đồng, kiểm tra timestamp/replay, deduplicate event ID và xử lý nhanh hoặc đưa vào queue. Retry là bình thường, không có bảo đảm chỉ giao một lần."],"example":"","pitfall":"Webhook đến trễ hoặc sai thứ tự; không áp trạng thái cũ đè trạng thái mới mà không kiểm tra.","exercise":"Thiết kế nhận webhook payment trùng, đến trước response checkout và đến sai thứ tự."}],"questions":[{"id":"rest","question":"REST có bắt buộc dùng JSON không?","answer":"Không. REST mô tả ràng buộc kiến trúc và representation có thể dùng nhiều định dạng.","explanation":"Một API JSON dùng HTTP chưa tự đáp ứng mọi ràng buộc REST.","followUp":"Uniform interface mang lợi ích gì?","note":"contract","level":"Cơ bản"},{"id":"graphql","question":"Khi nào GraphQL có ích?","answer":"Khi client có nhu cầu dữ liệu đa dạng và cần chọn shape hợp đồng rõ.","explanation":"Cần xử lý authorization theo field/resource, query cost, caching và N+1.","followUp":"Bạn giới hạn query quá sâu thế nào?","note":"contract","level":"Cơ bản"},{"id":"grpc","question":"Khi nào cân nhắc gRPC?","answer":"Khi cần contract rõ, code generation hoặc streaming theo nhu cầu hệ thống.","explanation":"Cân nhắc môi trường client, proxy, debugging và compatibility; không mặc định nhanh hơn trong mọi workload.","followUp":"Thay field protobuf cần chú ý gì?","note":"contract","level":"Cơ bản"},{"id":"cursor","question":"Cursor pagination tốt hơn offset ở đâu?","answer":"Có thể tránh scan offset lớn và ổn định hơn khi duyệt dữ liệu thay đổi theo sort phù hợp.","explanation":"Cần index và tie-breaker; không tự hỗ trợ nhảy tới trang bất kỳ.","followUp":"Vì sao chỉ timestamp chưa đủ?","note":"pagination","level":"Vận dụng"},{"id":"idempotent","question":"Idempotency key cần lưu những gì?","answer":"Phạm vi key, fingerprint input, trạng thái và kết quả với cơ chế claim nguyên tử.","explanation":"Hai replica phải dùng nguồn phối hợp chung; quy định TTL và xử lý pending.","followUp":"Payload khác nhưng cùng key nên trả gì?","note":"idempotency","level":"Đào sâu"},{"id":"retry","question":"Client timeout có nên tạo key thanh toán mới không?","answer":"Không nếu vẫn là cùng ý định thanh toán cần kiểm tra/lặp an toàn.","explanation":"Key mới có thể tạo giao dịch mới dù giao dịch cũ đã thành công.","followUp":"Bạn cung cấp endpoint kiểm tra trạng thái thế nào?","note":"idempotency","level":"Vận dụng"},{"id":"sse","question":"SSE và WebSocket chọn thế nào?","answer":"SSE phù hợp luồng một chiều server→client; WebSocket khi cần hai chiều theo yêu cầu.","explanation":"Cần xét hạ tầng proxy, auth, reconnect, ordering và load.","followUp":"Thông báo cập nhật trạng thái đơn có cần WebSocket không?","note":"realtime","level":"Cơ bản"},{"id":"webhook","question":"Xử lý webhook trùng thế nào?","answer":"Xác minh nguồn, deduplicate event ID và áp nghiệp vụ idempotent.","explanation":"Lưu event/ý định trong transaction phù hợp rồi ACK theo hợp đồng; không chỉ Set trong RAM.","followUp":"Nếu xử lý xong nhưng response ACK bị mất thì sao?","note":"realtime","level":"Vận dụng"},{"id":"version","question":"Thêm field vào response có luôn backward compatible không?","answer":"Không tuyệt đối; client parse chặt, signature hoặc validation có thể bị ảnh hưởng.","explanation":"Hợp đồng và consumer tests quyết định; tránh thay semantics âm thầm.","followUp":"Đổi nullable thành required thì sao?","note":"contract","level":"Vận dụng"},{"id":"ordering","question":"Webhook sự kiện cũ tới sau sự kiện mới thì xử lý sao?","answer":"Dùng version/state transition hợp lệ hoặc truy vấn trạng thái chuẩn trước khi cập nhật.","explanation":"Timestamp đơn lẻ có thể không đủ do clock/skew và semantics provider.","followUp":"Bạn ngăn paid bị ghi đè về pending thế nào?","note":"realtime","level":"Đào sâu"}],"order":15},{"id":"auth","title":"Xác thực, Session & Phân quyền","group":"03 · Backend & API","description":"Phân biệt người dùng là ai với họ được làm gì trên từng tài nguyên.","sources":[{"title":"OWASP Authentication","url":"https://cheatsheetseries.owasp.org/cheatsheets/Authentication_Cheat_Sheet.html"},{"title":"OAuth security RFC 9700","url":"https://datatracker.ietf.org/doc/html/rfc9700"}],"imageRefs":["A10","D12","F05","F14"],"prerequisites":["api"],"notes":[{"id":"identity","title":"Authentication khác authorization","body":["Authentication xác minh chủ thể; authorization đánh giá quyền cho hành động/tài nguyên trong ngữ cảnh. Session hợp lệ hoặc JWT có chữ ký đúng chưa chứng minh người dùng được đọc mọi order.","Kiểm tra quyền phía server cho từng tài nguyên, bao gồm tenant. RBAC gán quyền theo role; ABAC dùng thuộc tính và policy. Không lấy userId/tenantId từ request rồi tin rằng nó đại diện danh tính hiện tại."],"example":"SELECT * FROM orders\nWHERE id = $1 AND tenant_id = $2;\n-- tenant_id lấy từ ngữ cảnh đã xác thực/kiểm tra quyền.","pitfall":"","exercise":"Thiết kế quyền owner, support và admin khi xem thông tin đơn hàng."},{"id":"sessions","title":"Session, cookie và thuộc tính bảo vệ","body":["Session thường lưu trạng thái phía server và gửi một ID khó đoán cho client. Cookie là cơ chế browser lưu/gửi dữ liệu theo scope và policy, không đồng nghĩa session. HttpOnly hạn chế JS đọc cookie; Secure giới hạn gửi qua HTTPS; SameSite kiểm soát gửi trong ngữ cảnh cross-site.","Xoay session ID sau login/đổi quyền để giảm session fixation. Có thời hạn idle/absolute và thu hồi phía server. Cookie auth cần chiến lược CSRF; HttpOnly không làm XSS vô hại."],"example":"","pitfall":"","exercise":"Mô tả logout một thiết bị và logout mọi thiết bị.","diagram":{"type":"sequence","title":"Đăng nhập bằng session","actors":["Browser","Auth server","Session store"],"steps":[[0,1,"Credentials qua HTTPS"],[1,2,"Tạo session mới"],[1,0,"Set-Cookie: session ID"],[0,1,"Request tiếp theo + Cookie"],[1,2,"Tra session và kiểm tra quyền"]],"caption":"Cookie cần policy phù hợp; server không tin session ID do client tự đặt trước login."}},{"id":"tokens","title":"JWT, access token và refresh token","body":["JWT là định dạng token, không phải giao thức đăng nhập. JWT ký thường đọc được payload; chữ ký bảo vệ toàn vẹn, không mặc định mã hóa. Verifier cần kiểm tra thuật toán được phép, key, issuer, audience, expiry và các claim theo hợp đồng.","Access token nên có thời hạn phù hợp; refresh token dùng lấy token mới, cần bảo vệ, rotation và phát hiện reuse theo thiết kế. Logout với JWT cần chính sách revocation/session/version; xóa token ở browser không thu hồi bản đã bị đánh cắp."],"example":"","pitfall":"Decode base64 không phải verify token. Không đưa password hoặc dữ liệu bí mật vào payload JWT ký thông thường.","exercise":"Thiết kế xử lý khi refresh token cũ bị dùng lại sau rotation."},{"id":"oauth","title":"OAuth, OIDC và Authorization Code + PKCE","body":["OAuth là khung ủy quyền truy cập; OIDC bổ sung lớp xác thực danh tính, thường có ID token. Authorization Code flow đổi code tại token endpoint; PKCE ràng buộc code với client đã tạo verifier, giúp chống đánh cắp code.","Cần kiểm tra redirect URI, state và các kiểm tra OIDC như nonce khi phù hợp. Theo RFC 9700, không chọn password grant cho thiết kế mới; implicit có các rủi ro và nên dùng code flow phù hợp thay thế. Không coi access token dùng cho API là ID token cho ứng dụng."],"example":"","pitfall":"Scope không thay thế việc kiểm tra quyền tới từng tài nguyên trong API.","exercise":"Vẽ redirect và đổi code: phân biệt app, authorization server, resource server và browser.","diagram":{"type":"sequence","title":"Authorization Code + PKCE giản lược","actors":["Browser / App","Authorization server","Resource API"],"steps":[[0,1,"Authorize + challenge + state"],[1,0,"Redirect: code + state"],[0,1,"Đổi code + verifier"],[1,0,"Token theo hợp đồng"],[0,2,"Access token cho API"],[2,0,"Dữ liệu được phép"]],"caption":"App/client tạo verifier và kiểm tra state; auth server kiểm tra challenge. Vị trí đổi code phụ thuộc public client hay confidential server. OIDC còn có kiểm tra ID token."}}],"questions":[{"id":"identity","question":"Authentication và authorization khác nhau thế nào?","answer":"Một cái xác minh chủ thể, một cái quyết định quyền hành động trên tài nguyên.","explanation":"Cần authorize sau khi biết danh tính và trong đúng tenant/ngữ cảnh.","followUp":"JWT hợp lệ có đọc order của người khác được không?","note":"identity","level":"Cơ bản"},{"id":"cookie","question":"Session khác cookie thế nào?","answer":"Session là mô hình trạng thái; cookie là một cơ chế browser lưu/gửi dữ liệu.","explanation":"Session ID có thể đi trong cookie; cookie cũng có thể chứa dữ liệu không liên quan session.","followUp":"Session store chung giúp nhiều replica thế nào?","note":"sessions","level":"Cơ bản"},{"id":"httponly","question":"HttpOnly có chống được mọi tác hại XSS không?","answer":"Không. Nó hạn chế đọc cookie bằng JS, nhưng script độc có thể vẫn gửi request bằng phiên người dùng.","explanation":"Cần phòng XSS, quyền tối thiểu và policy request; không chỉ một flag.","followUp":"SameSite và CSRF token giải quyết gì?","note":"sessions","level":"Cơ bản"},{"id":"jwt","question":"JWT có mã hóa nội dung không?","answer":"JWT ký phổ biến không mặc định mã hóa payload.","explanation":"Dùng chữ ký để verify integrity; nội dung có thể đọc được. Mã hóa là cấu hình/định dạng khác.","followUp":"Bạn kiểm tra những claim nào?","note":"tokens","level":"Cơ bản"},{"id":"logout","question":"Logout với JWT hoạt động thế nào?","answer":"Phải xác định xóa client token, thu hồi refresh/session và khả năng vô hiệu access token theo thiết kế.","explanation":"Access token đã phát có thể còn hiệu lực tới expiry nếu không có kiểm tra thu hồi.","followUp":"Đổi password có cần thu hồi session khác không?","note":"tokens","level":"Đào sâu"},{"id":"refresh","question":"Refresh token rotation giúp gì?","answer":"Giảm việc tái sử dụng token cũ và hỗ trợ phát hiện reuse trong một token family.","explanation":"Cần lưu trạng thái, xử lý cạnh tranh giữa tab/request và policy khi nghi compromise.","followUp":"Hai refresh đồng thời hợp lệ được xử lý ra sao?","note":"tokens","level":"Đào sâu"},{"id":"oauth","question":"OAuth khác OIDC thế nào?","answer":"OAuth tập trung ủy quyền; OIDC bổ sung hợp đồng xác thực danh tính.","explanation":"Không dùng một access token tùy ý như bằng chứng login cho app không đúng audience.","followUp":"ID token gửi tới resource API thay access token có đúng không?","note":"oauth","level":"Cơ bản"},{"id":"pkce","question":"PKCE bảo vệ điều gì?","answer":"Ràng buộc authorization code với bên giữ code verifier.","explanation":"Không thay redirect URI validation, TLS, state hoặc toàn bộ kiểm tra OIDC.","followUp":"Ai tạo verifier và ai kiểm tra challenge?","note":"oauth","level":"Cơ bản"},{"id":"rbac","question":"RBAC có đủ cho ứng dụng nhiều tenant không?","answer":"Chưa chắc. Role cần được đánh giá trong tenant/resource scope.","explanation":"Admin tenant A không tự là admin tenant B; query và policy phải giữ ranh giới.","followUp":"Bạn ngăn client tự chọn tenant khác thế nào?","note":"identity","level":"Vận dụng"},{"id":"storage","question":"Token nên lưu localStorage hay cookie?","answer":"Phụ thuộc kiến trúc và threat model; không có lựa chọn miễn mọi rủi ro.","explanation":"localStorage dễ bị đọc khi XSS; cookie tự gửi cần xét CSRF và flags.","followUp":"BFF thay đổi nơi giữ token thế nào?","note":"sessions","level":"Vận dụng"}],"order":16},{"id":"security","title":"Bảo mật ứng dụng & API","group":"03 · Backend & API","description":"Nhận diện ranh giới tin cậy và bảo vệ từng bước xử lý dữ liệu.","sources":[{"title":"OWASP REST Security","url":"https://cheatsheetseries.owasp.org/cheatsheets/REST_Security_Cheat_Sheet.html"},{"title":"OWASP Cheat Sheets","url":"https://cheatsheetseries.owasp.org/"}],"imageRefs":["A11","F15","F16"],"prerequisites":["auth"],"notes":[{"id":"injection","title":"SQL injection, XSS và encoding","body":["SQL injection xảy ra khi dữ liệu bị diễn giải thành cấu trúc query. Dùng parameterized queries cho value; identifier như tên cột sort cần allowlist thay vì nhét vào placeholder tùy ý.","XSS là chạy script ngoài ý định trong origin của ứng dụng. Dùng output encoding theo context, textContent cho text, sanitizer đáng tin khi cần HTML và CSP như một lớp bổ sung. Input validation không thay thế encoding đầu ra."],"example":"// PostgreSQL placeholder qua driver\nawait db.query(\"SELECT id FROM users WHERE email = $1\", [email]);\n// Browser: textContent thay vì nối user input vào innerHTML","pitfall":"Escape SQL thủ công và một regex “lọc script” không phải giải pháp tổng quát.","exercise":"Review một endpoint sort theo tên cột từ query string."},{"id":"browser-security","title":"CSRF, CORS và quyền tài nguyên","body":["CSRF lợi dụng credential được browser tự gửi để thực hiện request ngoài ý định. Có thể dùng anti-CSRF token, SameSite và kiểm tra nguồn theo kiến trúc. CORS là policy browser cho phép code origin khác đọc response; nó không ngăn mọi request và không là authorization.","BOLA/IDOR xảy ra khi thay ID để truy cập tài nguyên không có quyền. Mỗi query/action phải áp policy, không dựa vào việc ID khó đoán hoặc nút UI bị ẩn."],"example":"","pitfall":"Không dùng Access-Control-Allow-Origin:* với kỳ vọng bảo vệ dữ liệu riêng tư. curl không bị CORS ràng buộc như JS browser.","exercise":"User A đổi /orders/42 thành /orders/43: kiểm tra server nào ngăn truy cập?","diagram":{"type":"sequence","title":"CSRF: credential được browser tự gửi","actors":["Trang bên ngoài","Browser user","API tin cậy"],"steps":[[0,1,"Kích hoạt request ngoài ý định"],[1,2,"Request + cookie theo policy"],[2,1,"Thao tác nếu thiếu kiểm tra"]],"caption":"Đây là mô hình nguy cơ: SameSite, anti-CSRF token, origin checks và hợp đồng endpoint có thể chặn luồng. CORS không thay authorization."}},{"id":"secrets","title":"Password, secrets và SSRF","body":["Password cần password hashing có salt và cost phù hợp; không dùng hash nhanh như SHA-256 đơn thuần cho password. Secrets cần tối thiểu quyền, rotation và redaction log.","SSRF là server bị điều khiển gọi đích ngoài ý định. Endpoint fetch URL cần allowlist/scheme policy, chặn mạng nội bộ/metadata theo threat model, xử lý redirect và DNS resolution cẩn thận. Chỉ kiểm tra chuỗi URL ban đầu là chưa đủ."],"example":"","pitfall":"Hash không phải encryption; không “giải mã password hash” để đăng nhập.","exercise":"Thiết kế dịch vụ preview link: giới hạn egress, timeout, kích thước và redirect."},{"id":"abuse","title":"Rate limiting, upload và phòng thủ nhiều lớp","body":["Rate limit có thể theo user, tenant, IP hoặc loại thao tác; chọn thuật toán fixed/sliding window, token bucket hoặc leaky bucket theo yêu cầu burst. Cần xét proxy headers đáng tin và phối hợp nhiều replica.","Upload phải kiểm tra quyền, kích thước, loại nội dung thực, tên file/path, nơi lưu và cách phục vụ. MIME từ client không đáng tin. Antivirus/quarantine và signed URL có thể cần theo nghiệp vụ. Giới hạn tài nguyên cũng là một phần bảo mật."],"example":"","pitfall":"","exercise":"Thiết kế rate limit login tránh khóa toàn bộ người dùng chung một NAT.","diagram":{"type":"flow","title":"Các lớp kiểm tra upload","nodes":["Xác thực + quyền","Giới hạn size + định dạng","Lưu tên do server tạo","Quarantine / kiểm tra","Cấp quyền tải phù hợp"],"caption":"Không thực thi file người dùng tải lên; không chỉ tin extension hoặc Content-Type."}}],"questions":[{"id":"sqli","question":"Parameterized query ngăn SQL injection thế nào?","answer":"Tách cấu trúc query khỏi dữ liệu value để input không trở thành cú pháp SQL.","explanation":"Tên bảng/cột động thường cần allowlist hoặc API identifier an toàn riêng.","followUp":"ORDER BY từ client nên xử lý thế nào?","note":"injection","level":"Cơ bản"},{"id":"xss","question":"Stored, reflected và DOM XSS khác nhau ở đâu?","answer":"Khác đường dữ liệu đi tới điểm thực thi: lưu trữ, phản hồi tức thời hoặc xử lý DOM phía client.","explanation":"Phòng vệ phải theo sink/context; sanitize/encode đúng chỗ.","followUp":"CSP có thay thế sửa sink nguy hiểm không?","note":"injection","level":"Cơ bản"},{"id":"csrf","question":"API JSON có chắc không bị CSRF không?","answer":"Không thể kết luận chỉ từ JSON; cần xét credential, content type, CORS và endpoint behavior.","explanation":"Cookie tự gửi là điểm cần phân tích; không dựa vào một nhãn công nghệ.","followUp":"SameSite có giới hạn gì trong deployment của bạn?","note":"browser-security","level":"Cơ bản"},{"id":"cors","question":"CORS có bảo vệ API khỏi curl không?","answer":"Không. Nó là cơ chế thực thi ở browser cho truy cập cross-origin.","explanation":"API vẫn cần authentication/authorization độc lập.","followUp":"Preflight thành công có chứng minh user được quyền không?","note":"browser-security","level":"Cơ bản"},{"id":"idor","question":"ID ngẫu nhiên có thay kiểm tra quyền không?","answer":"Không. Khó đoán giảm khả năng dò, không cấp hoặc kiểm tra quyền.","explanation":"Server cần ràng buộc chủ sở hữu/tenant và action.","followUp":"Bạn test BOLA với hai tài khoản thế nào?","note":"browser-security","level":"Cơ bản"},{"id":"password","question":"Vì sao không dùng SHA-256 trực tiếp cho password?","answer":"Nó quá nhanh cho mục tiêu chống thử mật khẩu hàng loạt khi hash bị lộ.","explanation":"Dùng password hashing chuyên dụng với salt/cost theo hướng dẫn hiện hành.","followUp":"Salt khác pepper ở đâu?","note":"secrets","level":"Cơ bản"},{"id":"ssrf","question":"SSRF khác XSS thế nào?","answer":"SSRF lợi dụng request từ server; XSS chạy script trong ngữ cảnh browser/origin.","explanation":"SSRF có thể chạm metadata hoặc mạng nội bộ mà client không gọi trực tiếp được.","followUp":"Redirect tới IP nội bộ sau URL hợp lệ thì sao?","note":"secrets","level":"Cơ bản"},{"id":"limit","question":"Fixed window rate limit có điểm yếu gì?","answer":"Có thể cho burst lớn quanh ranh giới hai window.","explanation":"Token bucket/sliding window có trade-off về trạng thái, độ chính xác và chi phí.","followUp":"Nhiều replica dùng counter riêng có giữ tổng limit không?","note":"abuse","level":"Vận dụng"},{"id":"upload","question":"Kiểm tra extension file đã đủ chưa?","answer":"Chưa. Nội dung, size, quyền, path và cách phục vụ đều cần xét.","explanation":"Client có thể giả tên và MIME; server nên sinh tên và tránh public execution.","followUp":"File HTML hoặc SVG tải lên có rủi ro gì?","note":"abuse","level":"Vận dụng"},{"id":"secret","question":"Lỡ log access token cần làm gì?","answer":"Ngăn tiếp tục ghi, xác định phạm vi lộ và thu hồi/rotate theo khả năng hệ thống.","explanation":"Xóa dòng log không bảo đảm mọi bản sao/backup đã hết token.","followUp":"Bạn redaction ở layer nào để ít bỏ sót?","note":"secrets","level":"Vận dụng"}],"order":17},{"id":"sql","title":"SQL & bài tập truy vấn","group":"04 · Dữ liệu","description":"Học bằng bảng dữ liệu nhỏ, kết quả mong đợi và truy vấn có thể chạy.","sources":[{"title":"PostgreSQL SELECT","url":"https://www.postgresql.org/docs/current/sql-select.html"},{"title":"Window functions","url":"https://www.postgresql.org/docs/current/tutorial-window.html"}],"imageRefs":["G02–G15","C11–C13","C16–C18","F10"],"prerequisites":["backend"],"notes":[{"id":"select","title":"SELECT, WHERE và thứ tự xử lý logic","body":["Các ví dụ trong topic dùng PostgreSQL trừ khi ghi khác. Luồng logic hữu ích: FROM/JOIN → WHERE → GROUP BY → HAVING → SELECT → DISTINCT → ORDER BY → LIMIT. Optimizer có thể thực thi vật lý khác mà vẫn giữ semantics.","WHERE lọc hàng trước aggregate; HAVING lọc nhóm sau aggregate. Không dựa vào thứ tự vật lý mặc định: muốn kết quả ổn định phải ORDER BY đủ khóa. NULL không bằng chính nó theo phép = thông thường, dùng IS NULL."],"example":"SELECT department, COUNT(*) AS employees\nFROM employees\nWHERE active = true\nGROUP BY department\nHAVING COUNT(*) >= 3\nORDER BY employees DESC, department;","pitfall":"Alias SELECT không dùng được ở mọi clause; quy tắc có khác biệt giữa DBMS.","exercise":"Giải thích vì sao đưa điều kiện active từ WHERE sang HAVING có thể đổi ý nghĩa."},{"id":"joins","title":"JOIN qua bảng dữ liệu thay vì chỉ Venn diagram","body":["INNER JOIN giữ cặp hàng khớp; LEFT JOIN giữ mọi hàng bên trái và thêm NULL khi không khớp. Một hàng có thể khớp nhiều hàng nên số dòng tăng. CROSS JOIN tạo tích Descartes; self join nối bảng với chính nó qua alias.","Điều kiện trên bảng phải đặt trong WHERE có thể loại các hàng NULL của LEFT JOIN. Đặt điều kiện trong ON hay WHERE cần theo ý nghĩa mong muốn. DISTINCT không phải cách mặc định sửa JOIN sai cardinality."],"example":"SELECT c.id, c.name, o.id AS order_id\nFROM customers c\nLEFT JOIN orders o ON o.customer_id = c.id AND o.status = 'paid'\nORDER BY c.id, o.id;","pitfall":"","exercise":"Giữ cả khách không có đơn paid: nếu chuyển o.status sang WHERE thì kết quả đổi thế nào?","table":{"headers":["Customers","Orders","LEFT JOIN kết quả"],"rows":[["1 · An","10 · customer 1","An · 10"],["2 · Bình","11 · customer 1","An · 11"],["","Không có đơn customer 2","Bình · NULL"]]}},{"id":"aggregates","title":"COUNT, GROUP BY và set operations","body":["COUNT(*) đếm hàng; COUNT(column) đếm giá trị không NULL; SUM/AVG thường bỏ qua NULL theo semantics của aggregate. GROUP BY gom theo khóa nhóm; DISTINCT loại hàng kết quả trùng. UNION loại trùng; UNION ALL giữ trùng và thường tránh công việc dedup. INTERSECT/EXCEPT xử lý giao/hiệu theo quy tắc tập và biến thể ALL.","Cần hiểu kiểu dữ liệu và rounding khi tính doanh thu/tỉ lệ. Chia số nguyên có thể cắt phần lẻ; NULLIF tránh mẫu số 0 và cho kết quả NULL cần được giải thích."],"example":"SELECT DATE_TRUNC('month', created_at) AS month,\n       SUM(amount) AS revenue, COUNT(*) AS orders\nFROM orders\nWHERE status = 'paid'\nGROUP BY 1 ORDER BY 1;","pitfall":"COALESCE(AVG(x),0) không giống AVG(COALESCE(x,0)); trường hợp thiếu dữ liệu có nghĩa nghiệp vụ khác.","exercise":"Tạo nhóm có 3 hàng với salary 100, NULL, 200 rồi tính COUNT và AVG."},{"id":"cte","title":"Subquery, EXISTS và CTE","body":["Subquery là query lồng trong query; correlated subquery tham chiếu hàng bên ngoài. EXISTS kiểm tra tồn tại mà không cần lấy mọi cột. NOT EXISTS thường rõ cho anti-join; NOT IN có thể cho UNKNOWN khi subquery chứa NULL.","CTE đặt tên cho phần query để dễ đọc và hỗ trợ recursive query. Nó không mặc định nhanh hơn hoặc luôn materialize; optimizer/version và cú pháp quyết định. Recursive CTE cần điều kiện dừng và chiến lược chống cycle theo dữ liệu."],"example":"SELECT c.id, c.name FROM customers c\nWHERE NOT EXISTS (\n  SELECT 1 FROM orders o WHERE o.customer_id = c.id\n);","pitfall":"JOIN không luôn nhanh hơn subquery; cần plan và semantics đúng.","exercise":"Viết CTE lấy nhân viên lương cao hơn trung bình phòng, không làm nhân số hàng."},{"id":"windows","title":"Window functions, xếp hạng và running total","body":["Window function giữ từng hàng và tính trên partition/frame. ROW_NUMBER đánh số hàng; RANK chừa khoảng khi hòa; DENSE_RANK không chừa khoảng. “Top 3 nhân viên” khác “top 3 mức lương”. Với ROW_NUMBER cần tie-breaker nếu muốn chọn xác định.","Frame mặc định có thể gom peer rows; running total theo từng hàng nên ghi ROWS và thứ tự đủ ổn định. “3 hàng gần nhất” không đồng nghĩa “3 ngày gần nhất” nếu thiếu ngày hoặc nhiều hàng/ngày."],"example":"WITH ranked AS (\n SELECT id, department, salary,\n   DENSE_RANK() OVER (PARTITION BY department ORDER BY salary DESC) AS r\n FROM employees WHERE salary IS NOT NULL\n)\nSELECT * FROM ranked WHERE r \u003c= 3;\n\nSELECT id, amount, SUM(amount) OVER (\n ORDER BY created_at, id ROWS BETWEEN UNBOUNDED PRECEDING AND CURRENT ROW\n) AS running_total FROM orders;","pitfall":"Không lọc trực tiếp window alias bằng WHERE cùng tầng SELECT; dùng CTE/subquery phù hợp.","exercise":"Với salary 100,100,90,80 so sánh ROW_NUMBER, RANK và DENSE_RANK.","diagram":{"type":"flow","title":"Xếp hạng trong từng phòng","nodes":["Chia PARTITION BY department","Sắp salary DESC","Gán rank cho từng hàng","Query ngoài lọc r \u003c= 3"],"caption":"DENSE_RANK lấy các mức lương; ROW_NUMBER chọn số hàng khi order đã xác định."}},{"id":"write","title":"INSERT, UPDATE, DELETE và thực hành an toàn","body":["DML thay đổi dữ liệu; dùng transaction khi nhiều bước cần cùng thành công. DELETE bỏ hàng, DROP bỏ object; TRUNCATE có semantics lock, trigger, identity và transaction tùy DBMS. Không học “TRUNCATE không rollback được” như quy tắc chung.","Trước UPDATE/DELETE, viết SELECT cùng predicate, xét khóa/foreign key và dữ liệu NULL. PostgreSQL có RETURNING để lấy hàng bị tác động. Upsert cần constraint xác định conflict, không thay thế mọi kiểm tra nghiệp vụ."],"example":"BEGIN;\nUPDATE accounts SET balance = balance - 100\nWHERE id = 1 AND balance >= 100\nRETURNING id, balance;\n-- Ứng dụng kiểm tra số hàng cập nhật trước bước tiếp theo.\nROLLBACK; -- dùng trong buổi thử; chưa chuyển tiền hoàn chỉnh","pitfall":"Code minh họa không phải giao dịch chuyển tiền đầy đủ; còn cần tài khoản đích, currency, khóa, lỗi và idempotency.","exercise":"Viết script dựng bảng mẫu, truy vấn và expected output cho một bài SQL trước khi tối ưu."},{"id":"lab","title":"SQL lab: dữ liệu nhỏ và kết quả kiểm chứng","body":["Một bài SQL tốt có schema, dữ liệu mẫu và kết quả mong đợi. Dataset dưới đây có salary trùng và NULL để kiểm tra semantics. Với ba nhân viên phòng Dev có lương 100,100,90, top hai mức lương giữ cả ba; top hai hàng chỉ giữ hai người theo tie-breaker.","Chạy trong database thử nghiệm hoặc dùng CTE VALUES để không thay dữ liệu hiện có. CTE dưới độc lập và không cần tạo bảng. Đáp án nên nói rõ xử lý NULL, tie và trường hợp thiếu dữ liệu."],"example":"WITH employees(id, department, salary) AS (\n VALUES (1,'Dev',100),(2,'Dev',100),(3,'Dev',90),\n        (4,'Ops',80),(5,'Ops',NULL)\n), ranked AS (\n SELECT *, DENSE_RANK() OVER (\n   PARTITION BY department ORDER BY salary DESC\n ) AS r\n FROM employees WHERE salary IS NOT NULL\n)\nSELECT id, department, salary FROM ranked\nWHERE r \u003c= 2 ORDER BY department, salary DESC, id;","pitfall":"","exercise":"Đổi DENSE_RANK sang ROW_NUMBER với ORDER BY salary DESC,id và so kết quả.","table":{"headers":["id","department","salary"],"rows":[["1","Dev","100"],["2","Dev","100"],["3","Dev","90"],["4","Ops","80"]]},"download":{"url":"examples/sql-lab.sql","title":"Tải SQL lab PostgreSQL: dữ liệu mẫu, truy vấn và kết quả mong đợi"}},{"id":"analytics","title":"LAG/LEAD, tăng trưởng và gaps & islands","body":["LAG/LEAD lấy giá trị hàng trước/sau theo window, không tự hiểu tháng hoặc ngày bị thiếu. Muốn tăng trưởng tháng, aggregate theo tháng rồi quyết định bổ sung tháng không dữ liệu hay coi thiếu là NULL. Dùng NULLIF(previous,0) và giải thích ý nghĩa khi mẫu bằng 0.","Gaps & islands thường gom các ngày/số liên tiếp bằng hiệu giữa giá trị và số thứ tự, hoặc đánh dấu điểm bắt đầu nhóm rồi cumulative sum. Cần loại duplicate theo đơn vị ngày và xác định timezone trước khi tạo streak."],"example":"WITH monthly AS (\n SELECT DATE_TRUNC('month',created_at) AS month, SUM(amount) AS revenue\n FROM orders WHERE status='paid' GROUP BY 1\n), comparison AS (\n SELECT *, LAG(revenue) OVER (ORDER BY month) AS previous\n FROM monthly\n)\nSELECT month, revenue,\n  (revenue-previous)*100.0/NULLIF(previous,0) AS growth_pct\nFROM comparison ORDER BY month;","pitfall":"Nếu thiếu tháng, LAG lấy tháng có dữ liệu trước đó, chưa chắc là tháng lịch trước.","exercise":"Thêm calendar series để tháng không có đơn được biểu diễn theo quy tắc nghiệp vụ."},{"id":"cte-recursive","title":"Recursive CTE và dữ liệu phân cấp","body":["Adjacency list lưu parent_id để biểu diễn cây. Recursive CTE gồm anchor và bước đệ quy ghép vào kết quả trước, kèm điều kiện dừng. Dữ liệu có cycle cần chống lặp hoặc dùng tính năng cycle detection theo DBMS.","Độ sâu, fan-out và index parent_id ảnh hưởng hiệu năng. Với nhu cầu đọc ancestor/subtree dày, có thể cân nhắc closure table hoặc materialized path; mỗi cách đổi chi phí ghi, dung lượng và độ phức tạp."],"example":"WITH RECURSIVE tree AS (\n SELECT id,parent_id,name,1 AS depth FROM categories WHERE id=$1\n UNION ALL\n SELECT c.id,c.parent_id,c.name,t.depth+1\n FROM categories c JOIN tree t ON c.parent_id=t.id\n WHERE t.depth \u003c 20\n) SELECT * FROM tree;\n-- Giới hạn depth chỉ là một lớp bảo vệ, không thay ràng buộc chống cycle.","pitfall":"","exercise":"Thiết kế category không được trở thành con của chính hậu duệ của mình."}],"questions":[{"id":"where","question":"WHERE khác HAVING thế nào?","answer":"WHERE lọc hàng trước grouping; HAVING lọc nhóm sau aggregate theo logic query.","explanation":"Chọn vị trí theo semantics, không chỉ vì clause nào cho phép COUNT.","followUp":"Điều kiện department và COUNT(*) nên đặt ở đâu?","note":"select","level":"Cơ bản"},{"id":"null","question":"Vì sao x = NULL không tìm hàng NULL?","answer":"So sánh thông thường với NULL cho UNKNOWN, không phải TRUE.","explanation":"WHERE chỉ giữ TRUE; dùng IS NULL/IS NOT NULL hoặc phép so sánh null-safe khi DBMS hỗ trợ.","followUp":"NOT IN chứa NULL ảnh hưởng gì?","note":"cte","level":"Đào sâu"},{"id":"count","question":"COUNT(*) và COUNT(salary) khác nhau thế nào?","answer":"COUNT(*) đếm hàng; COUNT(salary) chỉ đếm salary không NULL.","explanation":"LEFT JOIN có hàng không khớp vẫn tạo một hàng kết quả; count khóa bảng phải sẽ khác count(*).","followUp":"Đếm số đơn của khách chưa có đơn nên dùng gì?","note":"aggregates","level":"Cơ bản"},{"id":"left","question":"LEFT JOIN rồi WHERE bảng phải có thể gây gì?","answer":"Predicate loại NULL có thể loại hàng không khớp, khiến kết quả tương tự INNER JOIN trong trường hợp đó.","explanation":"Muốn giữ bên trái cần đặt điều kiện theo đúng ngữ nghĩa ở ON hoặc xử lý NULL có chủ đích.","followUp":"Giữ khách có 0 đơn paid bằng cách nào?","note":"joins","level":"Cơ bản"},{"id":"many","question":"JOIN khiến doanh thu tăng gấp đôi thì kiểm tra gì?","answer":"Cardinality và quan hệ một-nhiều/nhiều-nhiều giữa các bảng.","explanation":"Aggregate trước hoặc sửa khóa join theo yêu cầu; DISTINCT không sửa mọi lỗi cộng trùng.","followUp":"Join orders với order_items và payments có thể nhân như thế nào?","note":"joins","level":"Cơ bản"},{"id":"rank","question":"ROW_NUMBER, RANK, DENSE_RANK khác nhau thế nào?","answer":"ROW_NUMBER đánh số từng hàng; RANK chừa khoảng sau tie; DENSE_RANK xếp liên tiếp các mức.","explanation":"Chọn theo yêu cầu top N hàng hay N giá trị, thêm tie-breaker cho thứ tự hàng.","followUp":"Với 100,100,90 kết quả ba hàm là gì?","note":"windows","level":"Cơ bản"},{"id":"second","question":"Tìm mức lương cao thứ hai không tính trùng thế nào?","answer":"Có thể dùng DENSE_RANK trên salary giảm dần rồi lọc rank=2, hoặc MAX nhỏ hơn MAX.","explanation":"Cần định nghĩa NULL và trường hợp có ít hơn hai mức lương.","followUp":"Khác gì lấy hàng thứ hai sau ORDER BY?","note":"windows","level":"Cơ bản"},{"id":"topgroup","question":"Lấy top 3 nhân viên mỗi phòng thế nào?","answer":"ROW_NUMBER partition theo phòng, order theo salary và tie-breaker, rồi lọc rn\u003c=3 ở query ngoài.","explanation":"Nếu cần gồm mọi người ở 3 mức lương cao nhất, dùng DENSE_RANK theo salary.","followUp":"Tie-breaker có nên đưa vào DENSE_RANK mức lương không?","note":"windows","level":"Cơ bản"},{"id":"exists","question":"NOT EXISTS có lợi gì so với NOT IN?","answer":"Nó mô tả rõ điều kiện không có hàng khớp và tránh bẫy NULL của NOT IN trong nhiều trường hợp.","explanation":"Không nên kết luận luôn nhanh hơn; optimizer và index quyết định performance.","followUp":"Dữ liệu khóa nullable thay đổi kết quả thế nào?","note":"cte","level":"Đào sâu"},{"id":"union","question":"UNION khác UNION ALL thế nào?","answer":"UNION loại trùng hàng; UNION ALL giữ mọi hàng.","explanation":"Chọn theo yêu cầu; loại trùng thêm công việc và có thể làm sai khi bản ghi trùng mang ý nghĩa.","followUp":"Hai hàng cùng số tiền có phải cùng giao dịch không?","note":"aggregates","level":"Cơ bản"},{"id":"window","question":"Window function khác GROUP BY thế nào?","answer":"Window giữ từng hàng; GROUP BY tạo hàng theo nhóm.","explanation":"Có thể kết hợp ở các tầng query để tính tỉ lệ hoặc xếp hạng sau aggregate.","followUp":"Tính phần trăm doanh thu mỗi phòng cần những bước gì?","note":"windows","level":"Vận dụng"},{"id":"running","question":"Running total cần lưu ý gì?","answer":"Thứ tự ổn định và frame phù hợp, thường ROWS với khóa phân biệt hàng.","explanation":"Peer rows và default frame có thể cho kết quả khác mong đợi.","followUp":"Cộng theo ngày hay theo giao dịch khác nhau thế nào?","note":"windows","level":"Cơ bản"},{"id":"dedup","question":"Xóa duplicate giữ một hàng nên làm thế nào?","answer":"Định nghĩa khóa trùng, tiêu chí giữ, xếp hàng rồi xóa theo primary key trong transaction phù hợp.","explanation":"Cú pháp DELETE qua CTE khác DBMS; test trước, xét FK và concurrent writes.","followUp":"Làm sao ngăn duplicate xuất hiện lại?","note":"write","level":"Vận dụng"},{"id":"truncate","question":"TRUNCATE có luôn không rollback được không?","answer":"Không. Hành vi transaction phụ thuộc DBMS; PostgreSQL có thể rollback TRUNCATE trong transaction.","explanation":"Còn cần xét lock, trigger, identity và reference constraints.","followUp":"Vì sao không dùng bảng so sánh chung cho mọi DB?","note":"write","level":"Cơ bản"},{"id":"date","question":"Moving average 3 rows có phải trung bình 3 ngày?","answer":"Không nếu dữ liệu thiếu ngày hoặc có nhiều hàng mỗi ngày.","explanation":"Aggregate theo ngày và bổ sung lịch nếu nghiệp vụ yêu cầu; frame phải theo đúng đơn vị.","followUp":"Ngày không có doanh thu được tính 0 hay bỏ qua?","note":"windows","level":"Đào sâu"},{"id":"plan","question":"Làm sao tối ưu SQL mà giữ kết quả đúng?","answer":"Xác minh expected output trước, đọc plan và đo với dữ liệu đại diện rồi mới đổi query/index.","explanation":"JOIN và subquery có thể được optimizer biến đổi; đừng chọn bằng khẩu hiệu.","followUp":"Bạn kiểm tra row estimate lệch thực tế thế nào?","note":"cte","level":"Vận dụng"},{"id":"coalesce","question":"COALESCE và NULLIF dùng khi nào?","answer":"COALESCE chọn giá trị không NULL đầu tiên; NULLIF trả NULL khi hai biểu thức bằng nhau.","explanation":"Hay dùng default hiển thị và tránh chia 0, nhưng phải giữ ý nghĩa missing/zero.","followUp":"AVG(COALESCE(x,0)) đổi mẫu số thế nào?","note":"aggregates","level":"Vận dụng"},{"id":"case","question":"CASE có thể dùng để pivot thế nào?","answer":"Conditional aggregation như SUM(CASE WHEN condition THEN amount ELSE 0 END).","explanation":"Cần group key và định nghĩa cột đầu ra; PIVOT riêng là cú pháp theo DBMS.","followUp":"Dữ liệu năm không xuất hiện thì trả 0 hay NULL?","note":"aggregates","level":"Vận dụng"},{"id":"lag","question":"LAG có tự lấy đúng ngày hôm trước không?","answer":"Không. Nó lấy hàng trước theo ordering của window.","explanation":"Cần dữ liệu theo ngày và calendar khi muốn khoảng lịch đầy đủ.","followUp":"Hai hàng cùng ngày cần aggregate trước không?","note":"analytics","level":"Vận dụng"},{"id":"growth","question":"Tính tăng trưởng khi tháng trước bằng 0 ra sao?","answer":"Không chia trực tiếp; xác định policy và dùng NULLIF hoặc CASE theo nghiệp vụ.","explanation":"NULL, 0% và “không xác định” có ý nghĩa khác nhau.","followUp":"Nếu tháng trước không có dữ liệu thì sao?","note":"analytics","level":"Đào sâu"},{"id":"recursive","question":"Recursive CTE có rủi ro gì?","answer":"Cycle, fan-out lớn và query chạy quá sâu/lâu nếu thiếu kiểm soát.","explanation":"Cần invariant dữ liệu, điều kiện dừng và giới hạn tài nguyên phù hợp.","followUp":"Adjacency list khác closure table thế nào?","note":"cte-recursive","level":"Đào sâu"},{"id":"nullorder","question":"ORDER BY salary DESC có luôn để NULL cuối không?","answer":"Không theo mọi DBMS/default. Trong PostgreSQL DESC mặc định NULLS FIRST.","explanation":"Nêu rõ NULLS LAST hoặc loại NULL khi tìm mức lương có giá trị.","followUp":"Window rank có thể xếp NULL thành hạng đầu không?","note":"windows","level":"Đào sâu"},{"id":"timezones","question":"Đếm DAU cần làm rõ điều gì?","answer":"Định nghĩa active, ID người dùng, timezone/ngày và cách xử lý event trễ/trùng.","explanation":"COUNT(DISTINCT user_id) theo DATE không tự giải quyết mọi semantics analytics.","followUp":"User hoạt động gần nửa đêm được tính ngày nào?","note":"analytics","level":"Vận dụng"},{"id":"orderlimit","question":"LIMIT 10 không ORDER BY có ổn định không?","answer":"Không có bảo đảm thứ tự cần thiết cho chọn 10 hàng cụ thể.","explanation":"Plan/index/concurrency thay đổi có thể làm kết quả khác.","followUp":"ORDER BY created_at chưa đủ nếu timestamp trùng thì thêm gì?","note":"select","level":"Vận dụng"},{"id":"upsert","question":"Upsert có thay được mọi transaction không?","answer":"Không. Nó giải quyết insert/update theo conflict cụ thể, không bao mọi invariant nhiều hàng.","explanation":"Cần unique constraint và semantics cập nhật đúng theo DBMS.","followUp":"Hai upsert stock có thể giữ invariant nào?","note":"write","level":"Vận dụng"},{"id":"distinct","question":"Dùng DISTINCT để sửa JOIN bị nhân hàng có ổn không?","answer":"Chỉ khi semantics yêu cầu loại trùng toàn bộ hàng được chọn; không là cách sửa mặc định.","explanation":"Aggregate sai có thể vẫn sai sau DISTINCT; cần hiểu cardinality và khóa.","followUp":"Hai order cùng total có nên gộp thành một không?","note":"joins","level":"Vận dụng"}],"order":18},{"id":"database","title":"Database, Index & Transaction","group":"04 · Dữ liệu","description":"Giữ dữ liệu đúng trước, đo truy vấn rồi mới tối ưu.","sources":[{"title":"PostgreSQL isolation","url":"https://www.postgresql.org/docs/current/transaction-iso.html"},{"title":"PostgreSQL EXPLAIN","url":"https://www.postgresql.org/docs/current/using-explain.html"}],"imageRefs":["A06","A08–A09","C10","C14–C15","C19–C20","D06–D07","F11"],"prerequisites":["sql"],"notes":[{"id":"schema","title":"Keys, constraints và chuẩn hóa","body":["Primary key định danh hàng; foreign key ràng buộc quan hệ; unique/check/not-null bảo vệ invariant ngay trong DB. Cardinality, nullable và delete behavior là quyết định nghiệp vụ. Chuẩn hóa giảm redundancy/anomaly theo phụ thuộc dữ liệu; denormalization cần kế hoạch đồng bộ và đo lợi ích.","Schema tốt diễn đạt bất biến như mỗi ghế chỉ có một booking active theo mô hình phù hợp. Kiểm tra ở ứng dụng vẫn cần, nhưng constraint giúp chống race giữa nhiều writer."],"example":"CREATE TABLE accounts (\n id bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,\n email text NOT NULL UNIQUE,\n balance numeric(18,2) NOT NULL CHECK (balance >= 0)\n);","pitfall":"Kiểm tra “chưa tồn tại” rồi INSERT không đủ chống cạnh tranh nếu thiếu unique constraint.","exercise":"Vẽ ERD customers–orders–order_items–products; chỉ rõ giá snapshot trong order item.","diagram":{"type":"graph","title":"ERD giản lược cho đặt hàng","nodes":[[115,70,"customers"],[320,70,"orders"],[320,215,"order_items"],[535,215,"products"]],"edges":[[0,1],[1,2],[3,2]],"caption":"customers 1→N orders; orders 1→N order_items; products 1→N order_items. Mỗi item giữ quantity và giá snapshot theo nghiệp vụ; arrow diễn đạt quan hệ, không là HTTP flow."}},{"id":"indexes","title":"B-tree, composite index và query plan","body":["Index là cấu trúc hỗ trợ một số truy cập, kèm chi phí ghi, dung lượng và bảo trì. B-tree phục vụ nhiều truy vấn equality/range/order; hash phục vụ trường hợp khác theo DBMS. Composite index cần xét thứ tự cột, predicate, sort và selectivity.","EXPLAIN cho plan ước lượng; EXPLAIN ANALYZE thực thi query và đo actual nên cần cẩn trọng với câu lệnh ghi. Sequential scan có thể đúng và nhanh hơn index khi đọc nhiều dữ liệu. Clustered/nonclustered có semantics khác giữa PostgreSQL, MySQL và SQL Server."],"example":"CREATE INDEX orders_customer_created\nON orders (customer_id, created_at DESC, id DESC);\nEXPLAIN SELECT id FROM orders\nWHERE customer_id = 42\nORDER BY created_at DESC, id DESC LIMIT 20;","pitfall":"Không kết luận index cột sau luôn vô dụng nếu thiếu cột đầu; khả năng plan còn phụ thuộc DBMS, phiên bản và dữ liệu.","exercise":"So sánh estimate/actual rows và thời gian trước/sau index với dữ liệu đại diện."},{"id":"transactions","title":"ACID, isolation và MVCC","body":["Atomicity: nhóm thay đổi cùng thành công/thất bại. Consistency: transaction giữ invariant được thiết kế. Isolation: kiểm soát quan sát/tương tác đồng thời. Durability: commit bền theo cấu hình và cam kết hệ thống. ACID consistency khác consistency trong CAP.","MVCC giữ nhiều phiên bản để đọc theo snapshot; không có nghĩa không cần lock hoặc không có conflict. Isolation level có hành vi cụ thể theo DBMS; PostgreSQL Read Uncommitted hoạt động như Read Committed. Serializable có thể buộc ứng dụng retry transaction."],"example":"","pitfall":"Transaction không tự sửa invariant chưa được biểu diễn đúng trong query/constraint/isolation.","exercise":"Mô phỏng lost update và sửa bằng atomic UPDATE hoặc locking/version check.","diagram":{"type":"sequence","title":"Lost update nếu đọc rồi ghi thiếu phối hợp","actors":["Request A","Database","Request B"],"steps":[[0,1,"Đọc stock = 1"],[2,1,"Đọc stock = 1"],[0,1,"Ghi stock = 0; bán 1"],[2,1,"Ghi stock = 0; bán thêm 1"]],"caption":"Hai lần bán cùng một đơn vị hàng. Dùng phép cập nhật có điều kiện và kiểm tra kết quả để giữ invariant."}},{"id":"locks","title":"Lock, optimistic concurrency và deadlock","body":["Pessimistic locking giữ tài nguyên trong transaction; optimistic concurrency kiểm tra version/predicate khi cập nhật. UPDATE products SET stock=stock-1 WHERE id=? AND stock>0 là một mẫu nguyên tử trong DB phù hợp; ứng dụng phải kiểm tra số hàng tác động.","Deadlock được DB phát hiện có thể khiến một transaction bị hủy. Giữ transaction ngắn, lấy lock theo thứ tự nhất quán và retry toàn transaction khi lỗi cho phép; không retry vô hạn hoặc lặp tác dụng phụ ngoài DB."],"example":"UPDATE products SET stock = stock - 1\nWHERE id = $1 AND stock > 0\nRETURNING id, stock;\n\nUPDATE documents SET body = $1, version = version + 1\nWHERE id = $2 AND version = $3;","pitfall":"Không giữ transaction/lock trong lúc chờ người dùng hay API ngoài chậm.","exercise":"Thiết kế đặt vé có reservation hết hạn và unique constraint phù hợp."},{"id":"scale","title":"Replication, partitioning và migration","body":["Read replica tăng khả năng đọc nhưng có replication lag; đọc ngay sau ghi có thể cần primary hoặc cơ chế đảm bảo theo hệ. Partition chia dữ liệu trong hệ quản trị; sharding chia qua các node theo kiến trúc. Chọn shard key cần xét hot key, cross-shard query và rebalance.","Migration tương thích thường dùng expand–migrate–contract: thêm cấu trúc mới, chuyển code/dữ liệu có theo dõi, rồi loại cũ khi không còn consumer. Thêm index/constraint có thể lock hoặc làm tải tăng, cần cách rollout theo DBMS."],"example":"","pitfall":"Backup chưa được thử restore chưa chứng minh đạt RPO/RTO.","exercise":"Thêm cột bắt buộc cho bảng lớn trong khi hai phiên bản ứng dụng cùng chạy.","diagram":{"type":"graph","title":"Read replica và phân tách đường đọc","nodes":[[110,150,"Ứng dụng"],[340,65,"Primary"],[340,245,"Read replica"],[550,150,"Replication"]],"edges":[[0,1],[1,3],[3,2],[0,2]],"caption":"Ghi đi primary; đọc có thể đi replica khi chấp nhận guarantee tương ứng. Replication có độ trễ; đường đọc cuối không có nghĩa mọi read đều được phép stale."}},{"id":"normalization","title":"1NF, 2NF, 3NF và snapshot nghiệp vụ","body":["Trong cách trình bày quan hệ phổ biến, 1NF yêu cầu giá trị thuộc domain theo mô hình quan hệ, không dùng nhóm lặp tùy tiện; “atomic” phụ thuộc domain đã định nghĩa. 2NF loại phụ thuộc một phần của thuộc tính không khóa vào một phần candidate key tổng hợp. 3NF kiểm soát phụ thuộc bắc cầu theo định nghĩa phụ thuộc hàm.","Ví dụ order_items(order_id,product_id,product_name,quantity) có product_name phụ thuộc product_id; có thể tách products. Nhưng giá/name snapshot tại lúc mua là dữ liệu lịch sử nghiệp vụ, không nhất thiết phải luôn trỏ tới giá/name hiện tại. Chuẩn hóa phải đi cùng semantics."],"example":"","pitfall":"","exercise":"Tách bảng enrollment(student_id,course_id,student_name,course_name,grade) rồi chỉ ra candidate key và phụ thuộc hàm."},{"id":"read-models","title":"View, materialized view, procedure và trigger","body":["View thông thường định nghĩa query, không tự lưu kết quả như bảng riêng; materialized view lưu kết quả và cần refresh/maintenance. Stored procedure/function đặt logic gần dữ liệu theo khả năng DBMS. Trigger chạy theo event bảng và có thể giữ invariant hoặc audit, nhưng tạo tác dụng phụ khó thấy nếu thiếu tài liệu.","Đọc code ứng dụng không đủ để biết toàn bộ hành vi khi có trigger. Cần migration, permissions, test và monitoring cho logic DB. Cursor xử lý theo từng hàng có chỗ dùng nhưng thường nên xem set-based operation trước."],"example":"","pitfall":"","exercise":"Chọn view hay materialized view cho dashboard có thể trễ 5 phút; xác định refresh và quyền truy cập."}],"questions":[{"id":"key","question":"Primary key và unique khác nhau thế nào?","answer":"Primary key là khóa định danh chính với NOT NULL; unique bảo đảm tính duy nhất theo semantics DBMS.","explanation":"NULL, index backing và constraint behavior có khác biệt; cần đọc hệ đang dùng.","followUp":"Foreign key có tự tạo index ở mọi DBMS không?","note":"schema","level":"Cơ bản"},{"id":"normalize","question":"Khi nào denormalize?","answer":"Khi có nhu cầu đọc đã đo và chấp nhận chi phí đồng bộ/bất nhất được kiểm soát.","explanation":"Giữ nguồn sự thật và cách rebuild dữ liệu dẫn xuất rõ ràng.","followUp":"Giá sản phẩm trong đơn có nên lấy giá hiện tại không?","note":"schema","level":"Cơ bản"},{"id":"index","question":"Thêm index có luôn làm nhanh không?","answer":"Không. Có chi phí ghi/bộ nhớ/storage và optimizer có thể chọn scan tốt hơn.","explanation":"Đánh giá workload đọc–ghi, selectivity, sort và actual plan.","followUp":"Tại sao bảng nhỏ có thể không dùng index?","note":"indexes","level":"Cơ bản"},{"id":"explain","question":"EXPLAIN khác EXPLAIN ANALYZE thế nào?","answer":"EXPLAIN mô tả plan; ANALYZE thực thi để đo actual.","explanation":"Cần chú ý tác dụng phụ với statement ghi và overhead đo.","followUp":"Estimate rows lệch nhiều gợi ý gì?","note":"indexes","level":"Vận dụng"},{"id":"acid","question":"ACID có bảo đảm không overselling tự động không?","answer":"Không nếu quy tắc tồn kho chưa được mã hóa với query/constraint/isolation phù hợp.","explanation":"Atomic transaction không ngăn mọi logic đọc-rồi-ghi cạnh tranh ở mọi level.","followUp":"Một atomic conditional UPDATE giải quyết gì?","note":"transactions","level":"Cơ bản"},{"id":"mvcc","question":"MVCC có nghĩa không dùng lock không?","answer":"Không. Nó hỗ trợ nhiều phiên bản để giảm một số xung đột đọc/ghi.","explanation":"Writer vẫn có lock/conflict; snapshot và isolation quyết định quan sát.","followUp":"Long transaction ảnh hưởng cleanup phiên bản ra sao?","note":"transactions","level":"Cơ bản"},{"id":"isolation","question":"Repeatable Read có hành vi giống nhau mọi DB không?","answer":"Không. Tên level theo chuẩn nhưng implementation và anomaly được ngăn có thể khác.","explanation":"Phải mô tả PostgreSQL/MySQL cụ thể và test tình huống.","followUp":"Serializable failure cần xử lý ở ứng dụng thế nào?","note":"transactions","level":"Đào sâu"},{"id":"optimistic","question":"Optimistic locking dùng khi nào?","answer":"Khi conflict không quá thường xuyên và có thể phát hiện qua version/predicate rồi retry/báo conflict.","explanation":"Không giữ lock trong toàn thời gian người dùng sửa; update 0 row cần được xử lý.","followUp":"Hai editor cùng lưu sẽ thấy gì?","note":"locks","level":"Vận dụng"},{"id":"deadlock","question":"DB báo deadlock thì ứng dụng nên làm gì?","answer":"Rollback/retry transaction theo loại lỗi và policy có giới hạn.","explanation":"Giảm thời gian giữ lock, thống nhất thứ tự và tách side effect ngoài DB.","followUp":"Retry chỉ statement cuối có đúng không?","note":"locks","level":"Cơ bản"},{"id":"replica","question":"Đọc ngay sau ghi từ replica có rủi ro gì?","answer":"Có thể thấy dữ liệu cũ do replication lag.","explanation":"Routing, session consistency hoặc DB feature có thể đáp ứng yêu cầu read-your-writes.","followUp":"UI nên làm gì khi đơn mới chưa xuất hiện?","note":"scale","level":"Vận dụng"},{"id":"shard","question":"Partitioning khác sharding thế nào?","answer":"Partitioning phân chia dữ liệu; sharding thường chỉ việc phân bố qua nhiều node/database.","explanation":"Thuật ngữ theo sản phẩm có thể chồng lấn; cần mô tả topology cụ thể.","followUp":"Shard theo tenant gặp hot tenant thì sao?","note":"scale","level":"Đào sâu"},{"id":"migration","question":"Expand–contract giải quyết vấn đề gì?","answer":"Cho nhiều phiên bản ứng dụng cùng tồn tại trong khi thay schema.","explanation":"Không xóa field cũ trước khi mọi consumer chuyển; cần backfill và quan sát.","followUp":"Rollback code khi schema đã đổi cần điều kiện gì?","note":"scale","level":"Đào sâu"},{"id":"fkindex","question":"Foreign key có tự được index trong PostgreSQL không?","answer":"Không tự tạo index cho cột referencing chỉ vì khai báo foreign key.","explanation":"Index trên phía được tham chiếu gắn với constraint tương ứng; phía referencing cần cân nhắc theo truy vấn/delete/update.","followUp":"Xóa parent có nhiều child mà thiếu index ảnh hưởng gì?","note":"schema","level":"Đào sâu"},{"id":"thirdnf","question":"3NF giúp ngăn những anomaly nào?","answer":"Giảm một số update/insert/delete anomaly do phụ thuộc dữ liệu bị lưu lặp.","explanation":"Cần xác định candidate key và phụ thuộc hàm, không chỉ đếm số bảng.","followUp":"Snapshot giá đơn hàng có phải redundancy sai không?","note":"normalization","level":"Đào sâu"},{"id":"view","question":"View khác materialized view thế nào?","answer":"View định nghĩa query; materialized view lưu kết quả cần được làm mới.","explanation":"Freshness, chi phí refresh và quyền quyết định lựa chọn.","followUp":"Khi nào refresh làm người dùng thấy dữ liệu cũ?","note":"read-models","level":"Đào sâu"},{"id":"trigger","question":"Trigger có nhược điểm gì?","answer":"Hành vi ẩn, coupling và khó debug nếu không quản lý/test tốt.","explanation":"Có thể hữu ích cho invariant/audit nhưng cần thấy rõ transaction và lỗi.","followUp":"Trigger gửi API ngoài trực tiếp có rủi ro gì?","note":"read-models","level":"Đào sâu"},{"id":"oltp","question":"OLTP khác OLAP thế nào?","answer":"OLTP ưu tiên giao dịch ngắn/ghi và truy cập nghiệp vụ; OLAP ưu tiên phân tích nhiều dữ liệu.","explanation":"Schema, index, storage và freshness khác; có thể tách workload để giảm cạnh tranh.","followUp":"Chạy report lớn trên primary checkout gây gì?","note":"scale","level":"Đào sâu"},{"id":"nplusdb","question":"Connection pooling có giới hạn nào cần đặt?","answer":"Max connections, thời gian chờ, idle/lifetime và tổng pool qua mọi replica.","explanation":"Pool lớn quá làm DB contention; pool nhỏ quá làm queue wait.","followUp":"Autoscale từ 5 lên 50 Pod tác động tổng connections thế nào?","note":"scale","level":"Đào sâu"},{"id":"write-skew","question":"Write skew khác lost update thế nào?","answer":"Write skew có thể do transaction đọc cùng điều kiện rồi ghi các hàng khác nhau, phá invariant chung.","explanation":"Không nhất thiết có hai writer cùng một row; snapshot isolation không tự ngăn mọi trường hợp.","followUp":"Quy tắc luôn có một bác sĩ trực bị phá ra sao?","note":"transactions","level":"Đào sâu"},{"id":"migrationback","question":"Backfill bảng lớn cần chú ý gì?","answer":"Chia batch, giới hạn tải, resumability, kiểm tra consistency và tương thích code cũ/mới.","explanation":"Một UPDATE khổng lồ có thể giữ lock, tạo WAL và tăng replica lag.","followUp":"Làm sao biết backfill đã đủ trước khi contract?","note":"scale","level":"Đào sâu"}],"order":19},{"id":"nosql","title":"NoSQL & mô hình truy cập","group":"04 · Dữ liệu","description":"Chọn mô hình dữ liệu từ query và invariant thay vì khẩu hiệu SQL/NoSQL.","sources":[{"title":"MongoDB data modeling","url":"https://www.mongodb.com/docs/manual/data-modeling/"},{"title":"MongoDB transactions","url":"https://www.mongodb.com/docs/manual/core/transactions/"}],"imageRefs":["A07","F12"],"prerequisites":["database"],"notes":[{"id":"models","title":"Document, key-value, wide-column và graph","body":["NoSQL là nhóm hệ thống đa dạng, không phải một loại database đồng nhất. Document phù hợp dữ liệu có cấu trúc lồng; key-value tối ưu truy cập theo khóa; wide-column và graph giải các mẫu truy cập khác.","SQL/NoSQL không chia đơn giản thành “ACID vs không ACID” hoặc “vertical vs horizontal”. Mỗi sản phẩm có transaction, consistency và scaling riêng. Bắt đầu từ query, kích thước dữ liệu, invariant, latency và năng lực vận hành."],"example":"","pitfall":"","exercise":"Chọn mô hình cho profile, quan hệ bạn bè, session và ledger thanh toán; giải thích từng lựa chọn."},{"id":"mongo","title":"MongoDB: document, embed và reference","body":["MongoDB lưu document BSON trong collection. Embed dữ liệu thường đọc cùng nhau và có vòng đời gắn kết; reference khi dữ liệu chia sẻ, tăng không giới hạn hoặc cần cập nhật độc lập. Document có giới hạn kích thước; mảng comment tăng mãi trong một post dễ gây vấn đề.","Schema linh hoạt không có nghĩa không cần schema/validation. Index và aggregation pipeline cần được thiết kế theo workload. $match/$project và cardinality của $lookup ảnh hưởng chi phí."],"example":"db.orders.createIndex({ customerId: 1, createdAt: -1 });\ndb.orders.aggregate([\n { $match: { status: \"paid\" } },\n { $group: { _id: \"$customerId\", total: { $sum: \"$amount\" } } }\n]);","pitfall":"Không chuyển schema quan hệ sang document một-một mà bỏ qua access pattern.","exercise":"Thiết kế post/comments khi mỗi post có thể có hàng triệu comment.","diagram":{"type":"graph","title":"Embed hoặc reference tùy vòng đời","nodes":[[140,70,"Order document"],[140,210,"Items snapshot"],[475,70,"Post document"],[475,210,"Comments riêng"]],"edges":[[0,1],[2,3]],"caption":"Trái: các item hữu hạn đọc cùng đơn có thể embed. Phải: comment tăng không giới hạn thường cần mô hình tách và pagination. Đây là hai lựa chọn minh họa, không quy tắc tuyệt đối."}},{"id":"consistency","title":"Consistency, transaction và lựa chọn công nghệ","body":["Atomicity trên một document không tự bao mọi thao tác qua nhiều document. Transaction nhiều document có hỗ trợ trong cấu hình phù hợp nhưng có chi phí và giới hạn cần đọc. Read/write concern và topology ảnh hưởng guarantee.","Không gắn nhãn CP/AP cố định cho một thương hiệu rồi coi đó là toàn bộ behavior. Khi chọn database, ghi rõ yêu cầu nhất quán, failure behavior, query và kế hoạch backup/restore."],"example":"","pitfall":"Flexible schema đẩy trách nhiệm tương thích dữ liệu sang code nếu thiếu validation/migration.","exercise":"Thay cấu trúc field trong collection khi còn document cũ và nhiều phiên bản ứng dụng."}],"questions":[{"id":"sql","question":"Khi nào chọn SQL thay document database?","answer":"Khi quan hệ, transaction và truy vấn phù hợp mô hình quan hệ cùng năng lực hệ thống.","explanation":"Không chỉ dựa số lượng dữ liệu; cần invariant và access pattern.","followUp":"Hệ thống có cả SQL và NoSQL thì đồng bộ thế nào?","note":"models","level":"Cơ bản"},{"id":"noschema","question":"NoSQL có phải không cần schema?","answer":"Không. Schema vẫn tồn tại trong dữ liệu/hợp đồng code và có thể được validate.","explanation":"Không quản lý schema làm dữ liệu nhiều phiên bản khó đọc và migrate.","followUp":"Field đổi kiểu từ string sang object xử lý ra sao?","note":"mongo","level":"Cơ bản"},{"id":"embed","question":"Khi nào embed thay reference?","answer":"Khi đọc/cập nhật cùng nhau, quan hệ gắn kết và kích thước được kiểm soát.","explanation":"Reference phù hợp dữ liệu chia sẻ hoặc tăng không giới hạn; có trade-off join/lookup.","followUp":"Mảng comment vô hạn nên thiết kế thế nào?","note":"mongo","level":"Cơ bản"},{"id":"bson","question":"BSON có phải JSON thuần không?","answer":"Không. Đó là định dạng nhị phân có thêm kiểu dữ liệu so với JSON.","explanation":"Cần hiểu mapping driver và serialization khi trả API.","followUp":"ObjectId có tự là authorization không?","note":"mongo","level":"Cơ bản"},{"id":"index","question":"MongoDB có cần index không?","answer":"Có cho các access pattern phù hợp, cùng chi phí ghi và storage.","explanation":"Compound index cần xét filter/sort và plan, không tạo index mọi field.","followUp":"Bạn đo query chậm bằng công cụ nào?","note":"mongo","level":"Cơ bản"},{"id":"lookup","question":"$lookup có thay thế miễn phí mọi relational join không?","answer":"Không. Nó có semantics và chi phí cần đánh giá theo pipeline/dữ liệu.","explanation":"Thiết kế document nên xét truy cập thay vì mặc định join sau cùng.","followUp":"Stage làm tăng số document ảnh hưởng memory thế nào?","note":"mongo","level":"Cơ bản"},{"id":"atomic","question":"Một update document có bảo vệ nhiều document không?","answer":"Không tự động. Atomicity single-document không bao các thao tác ở document khác.","explanation":"Cần transaction hoặc thiết kế invariant khác theo sản phẩm.","followUp":"Chuyển tiền giữa hai document cần đảm bảo gì?","note":"consistency","level":"Cơ bản"},{"id":"acid","question":"NoSQL có transaction ACID không?","answer":"Một số hệ có, theo phạm vi và cấu hình cụ thể.","explanation":"Không dùng hai nhãn SQL/NoSQL để suy ra toàn bộ guarantee.","followUp":"Transaction distributed có chi phí gì?","note":"consistency","level":"Cơ bản"},{"id":"scale","question":"NoSQL có tự scale vô hạn không?","answer":"Không. Shard key, hot partition, index và giới hạn hạ tầng vẫn quyết định.","explanation":"Một key nóng có thể trở thành bottleneck dù tổng cluster còn dư.","followUp":"Bạn phát hiện phân bố shard lệch thế nào?","note":"models","level":"Vận dụng"},{"id":"choice","question":"Bạn đánh giá database mới bằng những gì?","answer":"Query/invariant, failure semantics, latency, cost, vận hành, migration và restore.","explanation":"Benchmark phải đại diện workload và bao cả tình huống lỗi.","followUp":"Ai sẽ vận hành hệ khi on-call?","note":"consistency","level":"Vận dụng"}],"order":20},{"id":"cache","title":"Caching, Redis & CDN","group":"04 · Dữ liệu","description":"Tăng tốc nhưng vẫn hiểu dữ liệu cũ, mất cache và các tình huống cạnh tranh.","sources":[{"title":"Redis cache","url":"https://redis.io/docs/latest/develop/use/"},{"title":"MDN HTTP caching","url":"https://developer.mozilla.org/en-US/docs/Web/HTTP/Guides/Caching"}],"imageRefs":["A12","D08","F13"],"prerequisites":["database","network"],"notes":[{"id":"strategies","title":"Cache-aside và các chiến lược ghi","body":["Cache-aside: ứng dụng tra cache; miss thì đọc DB và điền cache. Read-through giao việc nạp cho lớp cache. Write-through đồng bộ ghi qua lớp cache tới backing store theo hợp đồng; write-back ghi backing store sau nên có cửa sổ mất dữ liệu.","Cache không phải nguồn sự thật mặc định. Xác định key, namespace/tenant, TTL, dữ liệu nhạy cảm và cách hệ hoạt động khi cache mất. Redis còn là data structure store với nhiều vai trò; guarantee phụ thuộc cách dùng."],"example":"","pitfall":"","exercise":"Thêm tenant/version vào cache key để tránh trả nhầm dữ liệu.","diagram":{"type":"sequence","title":"Cache-aside khi cache miss","actors":["Ứng dụng","Redis","Database"],"steps":[[0,1,"GET product:42"],[1,0,"Miss"],[0,2,"SELECT product"],[2,0,"Dữ liệu"],[0,1,"SET + TTL"]],"caption":"Cache hit bỏ qua DB; cập nhật/invalidations cần một thiết kế riêng."}},{"id":"invalidation","title":"TTL, eviction và race khi cập nhật","body":["TTL hết hạn theo tuổi; eviction đẩy key ra khi áp lực tài nguyên theo policy. Hai việc khác nhau. Cập nhật DB rồi xóa cache là mẫu phổ biến nhưng vẫn có race: một reader lấy bản cũ trước commit rồi điền cache sau invalidation.","Mức độ chấp nhận stale quyết định chiến lược: TTL ngắn, versioned values, event invalidation hoặc phối hợp chặt hơn. Không tuyên bố “xóa cache sau commit” tự bảo đảm strong consistency."],"example":"","pitfall":"Cache key không chứa quyền/tenant có thể gây lộ dữ liệu, không chỉ sai performance.","exercise":"Vẽ timeline reader/writer tạo stale cache sau khi writer đã xóa key.","diagram":{"type":"sequence","title":"Một race tạo stale cache sau invalidation","actors":["Reader","Database","Writer","Cache"],"steps":[[0,1,"Đọc giá trị cũ"],[2,1,"Commit giá trị mới"],[2,3,"Xóa key cache"],[0,3,"Điền lại dữ liệu cũ đã đọc"]],"caption":"Reader lấy dữ liệu trước commit nhưng điền cache sau invalidation. TTL/version/coordination phải phù hợp mức stale được phép."}},{"id":"stampede","title":"Stampede, penetration và hot key","body":["Stampede: nhiều request cùng miss/expire gây tải đột biến tới DB. Có thể dùng request coalescing, refresh sớm, TTL jitter hoặc stale-while-revalidate theo yêu cầu. Cache penetration lặp truy vấn dữ liệu không có; negative cache hữu ích nhưng phải xét dữ liệu có thể xuất hiện sau đó.","Hot key tập trung tải; thêm shard không tự chia được một key theo mọi thiết kế. Cần giới hạn concurrency và load shedding để cache failure không kéo sập DB."],"example":"","pitfall":"","exercise":"Lập kế hoạch hệ hoạt động khi toàn bộ Redis unavailable trong 5 phút."},{"id":"http-cache","title":"ETag, private/public và CDN","body":["Cache-Control quy định policy; ETag là validator dùng conditional request. no-cache thường yêu cầu validate trước tái sử dụng, không đồng nghĩa cấm lưu; no-store yêu cầu không lưu theo semantics HTTP. Vary ảnh hưởng key của representation.","CDN cần phân biệt public asset và response cá nhân hóa. Signed URL, authorization, purge và query-string normalization cần được cấu hình cùng threat model. Đo hit ratio đi kèm latency, DB load và freshness."],"example":"Cache-Control: private, no-cache\nETag: \"profile-v7\"\nVary: Accept-Encoding","pitfall":"Không đưa token vào URL nếu có thể bị log/cache và leak theo cơ chế khác.","exercise":"Thiết kế cache cho ảnh versioned và thông tin số dư tài khoản."}],"questions":[{"id":"aside","question":"Cache-aside hoạt động thế nào?","answer":"Ứng dụng tra cache, miss thì đọc nguồn chính và lưu cache cho lần sau.","explanation":"Cần policy TTL, invalidation và fallback khi cache lỗi.","followUp":"Hai reader cùng miss thì sao?","note":"strategies","level":"Cơ bản"},{"id":"ttl","question":"TTL và eviction khác nhau thế nào?","answer":"TTL là hết hạn theo thời gian; eviction là loại dữ liệu theo policy áp lực tài nguyên.","explanation":"Key có thể bị evict trước TTL hoặc sống không TTL tùy cấu hình.","followUp":"Có nên mặc định mọi key tồn tại đến expiry không?","note":"invalidation","level":"Cơ bản"},{"id":"write","question":"Write-back có rủi ro gì?","answer":"Dữ liệu chưa ghi backing store có thể mất khi cache/buffer lỗi.","explanation":"Phải xét durability, replay và semantics xác nhận thành công.","followUp":"Nó có phù hợp ledger tài chính không và vì sao?","note":"strategies","level":"Cơ bản"},{"id":"race","question":"Ghi DB rồi xóa cache có bảo đảm không stale không?","answer":"Không tuyệt đối. Reader đang nạp bản cũ có thể điền cache sau bước xóa.","explanation":"Cần phân tích timeline và mức consistency nghiệp vụ yêu cầu.","followUp":"Versioned value hoặc refresh policy giúp gì?","note":"invalidation","level":"Đào sâu"},{"id":"stampede","question":"Ngăn cache stampede bằng cách nào?","answer":"Coalesce request, TTL jitter, refresh sớm và giới hạn tải về nguồn.","explanation":"Lock cache cần timeout/ownership và không làm mọi request chờ vô hạn.","followUp":"Cache lock holder chết thì sao?","note":"stampede","level":"Cơ bản"},{"id":"negative","question":"Negative caching là gì?","answer":"Lưu kết quả không tồn tại/lỗi phù hợp trong thời gian xác định để tránh truy vấn lặp.","explanation":"Không nên cache mọi lỗi tạm thời như dữ liệu không tồn tại; chú ý thời gian dữ liệu mới xuất hiện.","followUp":"TTL negative nên khác positive thế nào?","note":"stampede","level":"Cơ bản"},{"id":"nocache","question":"no-cache khác no-store thế nào?","answer":"no-cache yêu cầu validation trước tái sử dụng trong semantics HTTP; no-store yêu cầu không lưu.","explanation":"Cần xét browser/shared cache và dữ liệu nhạy cảm.","followUp":"ETag đóng vai trò gì khi no-cache?","note":"http-cache","level":"Cơ bản"},{"id":"redisdown","question":"Redis lỗi có nên mọi request xuống DB không?","answer":"Không mặc định. Có thể làm DB sập vì lượng tải trước đó cache hấp thụ.","explanation":"Cần concurrency limit, fallback, stale response hoặc từ chối bớt theo nghiệp vụ.","followUp":"Bạn ưu tiên endpoint nào khi degraded?","note":"stampede","level":"Vận dụng"},{"id":"hit","question":"Hit ratio cao có chứng minh cache hiệu quả không?","answer":"Chưa đủ. Cần xét latency, chi phí, freshness và phân phối theo key/endpoint.","explanation":"Hit nhiều ở request rẻ có thể không giúp bottleneck chính.","followUp":"Bạn đo savings DB thế nào?","note":"http-cache","level":"Vận dụng"},{"id":"privacy","question":"Cache response có auth cần lưu ý gì?","answer":"Scope theo user/tenant/quyền và policy private/shared cache rõ.","explanation":"Sai cache key có thể lộ dữ liệu dù auth handler đúng.","followUp":"Role đổi thì invalidation cache quyền ra sao?","note":"invalidation","level":"Vận dụng"}],"order":21},{"id":"messaging","title":"Messaging, Kafka & Jobs","group":"05 · Hệ thống phân tán","description":"Tách producer/consumer nhưng vẫn giữ retry, ordering và dữ liệu đúng.","sources":[{"title":"RabbitMQ confirms","url":"https://www.rabbitmq.com/docs/confirms"},{"title":"AWS outbox","url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/transactional-outbox.html"},{"title":"Kafka design","url":"https://kafka.apache.org/documentation/#design"}],"imageRefs":["A15","D11","F16–F17"],"prerequisites":["database","backend"],"notes":[{"id":"queue","title":"Queue khác event stream","body":["Work queue phân phối tác vụ cho worker; event stream giữ chuỗi sự kiện theo retention để consumer đọc và có thể replay theo mô hình. Kafka topic gồm partition với offset; consumer group phối hợp chia partition. Không có total order tự động giữa mọi partition.","Chọn message key để giữ order cần thiết trong partition nhưng tránh hot partition. Số consumer hữu ích trong group bị ràng buộc bởi số partition và cách assignment. RabbitMQ có các loại queue/stream, không nên suy mọi sản phẩm chỉ có một mô hình."],"example":"","pitfall":"","exercise":"Chọn partition key cho event đơn hàng: order ID hay user ID và đánh đổi?"},{"id":"delivery","title":"ACK, retry, DLQ và idempotent consumer","body":["Publisher confirm xác nhận broker nhận theo guarantee; consumer ACK xác nhận việc xử lý ở phía consumer theo protocol. Hai việc độc lập. At-least-once có thể giao lặp; ACK trước commit có thể mất công việc, ACK sau commit có thể lặp khi response/ACK mất.","Thiết kế consumer idempotent bằng event ID/business key và transaction với thay đổi nghiệp vụ. Retry có backoff/jitter, giới hạn và phân loại lỗi. Poison message vào DLQ cần alert, công cụ kiểm tra và quy trình replay."],"example":"","pitfall":"Đưa vào DLQ không tự giải quyết lỗi. Không mặc định exactly-once bao được email hoặc API bên ngoài.","exercise":"Consumer commit DB rồi chết trước ACK: chạy lại có tạo đơn trùng không?"},{"id":"outbox","title":"Dual-write và transactional outbox","body":["Ghi DB rồi publish message có cửa sổ chết giữa hai bước. Publish trước commit có thể tạo event cho dữ liệu chưa thành công. Outbox ghi dữ liệu nghiệp vụ và ý định event trong cùng transaction của một DB; relay đọc outbox rồi publish.","Relay có thể publish lặp sau crash, vì vậy consumer vẫn cần idempotency. Ordering, cleanup, CDC/polling và độ trễ là các quyết định vận hành. Đây không phải phép biến distributed side effect thành transaction toàn cục."],"example":"","pitfall":"","exercise":"Mô phỏng relay publish thành công nhưng chưa đánh dấu sent thì crash.","diagram":{"type":"flow","title":"Transactional outbox","nodes":["Transaction: order + outbox row","Commit DB","Relay đọc/publish","Broker → consumer","Deduplicate + thực hiện"],"caption":"Ranh giới nguyên tử là DB transaction; publish/ACK vẫn có thể lặp."}},{"id":"jobs","title":"Background jobs và backpressure","body":["Job cần payload/schema version, idempotency key, trạng thái, retry policy và khả năng quan sát. Queue hấp thụ burst nhưng không tạo công suất vô hạn; nếu tốc độ vào lớn hơn tốc độ xử lý lâu dài, backlog sẽ tăng.","Giới hạn concurrency theo downstream, theo dõi queue age cùng queue length. Scheduler cần phối hợp để không chạy một cron nhiều lần ngoài ý định. Cancellation và timeout không tự hoàn tác side effect đã hoàn tất."],"example":"","pitfall":"","exercise":"Thiết kế export báo cáo: nhận job, trả ID, poll trạng thái, lưu file hết hạn và retry an toàn."}],"questions":[{"id":"queue","question":"Queue và stream khác nhau thế nào?","answer":"Queue nhấn mạnh phân phối việc; stream nhấn mạnh log sự kiện có retention/replay theo mô hình.","explanation":"Sản phẩm có nhiều chế độ; cần mô tả cụ thể durability và consumption.","followUp":"Audit log có cần giữ event sau khi xử lý không?","note":"queue","level":"Cơ bản"},{"id":"partition","question":"Kafka bảo đảm ordering ở phạm vi nào?","answer":"Trong partition theo guarantee và cấu hình/usage cụ thể, không tự giữa mọi partition.","explanation":"Producer retries và consumer concurrency cũng cần thiết kế phù hợp.","followUp":"Giữ thứ tự cho cùng order bằng key nào?","note":"queue","level":"Cơ bản"},{"id":"group","question":"Thêm consumer có luôn tăng throughput không?","answer":"Không. Partition assignment, bottleneck downstream và công việc quyết định.","explanation":"Consumer vượt số partition có thể idle trong group; thêm concurrency còn gây contention.","followUp":"Database nghẽn thì scale consumer gây gì?","note":"queue","level":"Cơ bản"},{"id":"ack","question":"Publisher confirm khác consumer ACK thế nào?","answer":"Một cái phản hồi broker nhận từ producer; một cái báo consumer đã xử lý delivery.","explanation":"Confirm không chứng minh nghiệp vụ consumer hoàn tất.","followUp":"ACK trước DB commit có rủi ro gì?","note":"delivery","level":"Cơ bản"},{"id":"exactly","question":"Exactly-once có bao mọi side effect không?","answer":"Không tự động. Guarantee có phạm vi, ví dụ transaction trong một nền tảng.","explanation":"Email, payment hoặc DB ngoài cần phối hợp/idempotency riêng.","followUp":"Bạn mô tả ranh giới guarantee trong thiết kế thế nào?","note":"delivery","level":"Đào sâu"},{"id":"duplicate","question":"Consumer chống xử lý trùng thế nào?","answer":"Dùng event/business key và lưu dedup cùng thay đổi nghiệp vụ một cách nguyên tử khi có thể.","explanation":"Set trong RAM mất khi restart và không phối hợp replica.","followUp":"Dedup record giữ bao lâu?","note":"delivery","level":"Vận dụng"},{"id":"outbox","question":"Outbox giải quyết vấn đề gì?","answer":"Cửa sổ dual-write giữa lưu nghiệp vụ và ý định phát event.","explanation":"Không tự loại duplicate; relay và consumer vẫn cần thiết kế retry.","followUp":"Relay chết sau publish nhưng trước đánh dấu sent thì sao?","note":"outbox","level":"Đào sâu"},{"id":"dlq","question":"DLQ nên được vận hành thế nào?","answer":"Có alert, thông tin lỗi, kiểm tra dữ liệu và quy trình replay có kiểm soát.","explanation":"Không đổ retry vô hạn vào DLQ rồi bỏ quên; sửa lỗi trước replay.","followUp":"Poison message khác lỗi mạng tạm thời thế nào?","note":"delivery","level":"Vận dụng"},{"id":"backpressure","question":"Queue tăng liên tục thì thêm buffer đủ không?","answer":"Không. Nếu công suất xử lý thiếu lâu dài thì backlog và độ trễ vẫn tăng.","explanation":"Cần giảm tốc vào, tăng công suất thật, ưu tiên hoặc bỏ bớt theo nghiệp vụ.","followUp":"Queue age hay queue length phản ánh SLA tốt hơn khi nào?","note":"jobs","level":"Vận dụng"},{"id":"cron","question":"Cron nhiều replica có thể chạy trùng không?","answer":"Có nếu mỗi replica tự schedule mà không phối hợp.","explanation":"Có thể dùng scheduler chung, lease/lock phù hợp hoặc job idempotent; crash và expiry vẫn cần xét.","followUp":"Lock hết hạn trong khi job còn chạy thì sao?","note":"jobs","level":"Vận dụng"}],"order":22},{"id":"architecture","title":"Kiến trúc & Microservices","group":"05 · Hệ thống phân tán","description":"Chia hệ thống theo trách nhiệm và đánh đổi, không theo tên công nghệ.","sources":[{"title":"AWS saga","url":"https://docs.aws.amazon.com/prescriptive-guidance/latest/cloud-design-patterns/saga-orchestration.html"},{"title":"Microsoft architecture patterns","url":"https://learn.microsoft.com/en-us/azure/architecture/patterns/"}],"imageRefs":["A14","D10","D18","F17"],"prerequisites":["backend","messaging"],"notes":[{"id":"boundaries","title":"Monolith, modular monolith và microservices","body":["Monolith triển khai như một đơn vị nhưng vẫn có thể chia module tốt và scale nhiều replica. Modular monolith giữ ranh giới logic với chi phí mạng thấp. Microservices cho deployment/scaling độc lập khi ranh giới và ownership phù hợp, đổi lại có network failure, dữ liệu phân tán và vận hành phức tạp.","DDD bounded context định nghĩa phạm vi một mô hình/ngôn ngữ nghiệp vụ có nghĩa nhất quán. Ranh giới service nên theo năng lực và mức độ thay đổi, không chỉ tách mỗi bảng thành service."],"example":"","pitfall":"Microservices không tự làm code loosely coupled. Gọi vòng đồng bộ và chia sẻ schema có thể tạo distributed monolith.","exercise":"Phân tích một ứng dụng nhóm 3 người: lợi ích tách payment service có bù chi phí vận hành không?"},{"id":"communication","title":"Gateway, discovery và ownership dữ liệu","body":["Gateway là entry point cho routing và policy chung, không nên gom mọi nghiệp vụ vào đó. Service discovery tìm instance theo môi trường. Database per service là ownership và quyền thay đổi; không nhất thiết mỗi service luôn cần một máy DB riêng.","Gọi sync cần timeout/deadline và xử lý lỗi; async cần event contract, retry và consistency. Tránh service A trực tiếp sửa bảng riêng của B vì phá ranh giới dù nhanh ban đầu."],"example":"","pitfall":"","exercise":"Một trang cần dữ liệu từ 3 service: so sánh API composition với read model."},{"id":"patterns","title":"CQRS, event sourcing và saga","body":["CQRS tách mô hình đọc/ghi, không bắt buộc hai database hay event sourcing. Event sourcing lưu chuỗi domain events làm nguồn sự thật và dựng state từ event; cần versioning, projection, snapshot và chiến lược dữ liệu nhạy cảm.","Saga chia use case thành local transaction và compensation khi cần. Compensation là hành động nghiệp vụ bù, không phải rollback kỹ thuật luôn khôi phục như chưa từng xảy ra. Orchestration có coordinator; choreography qua phản ứng event."],"example":"","pitfall":"","exercise":"Xử lý thanh toán thành công nhưng giữ hàng thất bại; xác định trạng thái trung gian và tác vụ bù.","diagram":{"type":"flow","title":"Saga đặt hàng","nodes":["Giữ tồn kho","Ủy quyền thanh toán","Xác nhận đơn","Nếu lỗi: giải phóng/hoàn tiền theo policy"],"caption":"Nếu đã giao hàng hoặc email đã gửi, compensation không xóa lịch sử thực tế."}},{"id":"evolution","title":"Strangler, adapter và tiến hóa kiến trúc","body":["Strangler chuyển dần use case/traffic từ hệ cũ sang mới. Adapter cô lập hợp đồng bên ngoài; sidecar chạy chức năng phụ cạnh ứng dụng theo topology. Chọn pattern khi giải vấn đề thực như compatibility, migration hoặc isolation.","Đo coupling, deploy frequency, latency và failure modes trước khi tách service. Ghi quyết định bằng ADR: bối cảnh, lựa chọn, đánh đổi, hệ quả và điều kiện xem xét lại."],"example":"","pitfall":"Tách code mà không tách ownership và quy trình release có thể không đạt lợi ích độc lập.","exercise":"Lập migration từng bước cho module thông báo, có rollback và đối soát dữ liệu."}],"questions":[{"id":"when","question":"Khi nào không nên dùng microservices?","answer":"Khi quy mô nhóm/vận hành và nhu cầu độc lập chưa bù chi phí phân tán.","explanation":"Modular monolith có thể giữ code tốt và triển khai đơn giản.","followUp":"Dấu hiệu nào chứng minh cần tách một module?","note":"boundaries","level":"Vận dụng"},{"id":"context","question":"Bounded context là gì?","answer":"Phạm vi mà một mô hình và thuật ngữ nghiệp vụ có ý nghĩa nhất quán.","explanation":"Customer ở billing có thể khác customer ở support; không phải mọi concept chung đều một model.","followUp":"Nó liên quan service boundary thế nào?","note":"boundaries","level":"Cơ bản"},{"id":"dbservice","question":"Database per service có nghĩa gì?","answer":"Service sở hữu hợp đồng dữ liệu và quyền thay đổi, tránh service khác truy cập ghi tùy ý.","explanation":"Có thể cùng hạ tầng vật lý nhưng phải giữ isolation/ownership theo thiết kế.","followUp":"Report cần join nhiều domain thì giải quyết thế nào?","note":"communication","level":"Cơ bản"},{"id":"gateway","question":"API gateway có nên chứa toàn bộ business logic không?","answer":"Không nên; nó thường giữ routing và policy cross-cutting phù hợp.","explanation":"Gateway phình to thành điểm coupling/SPOF nếu thiếu giới hạn và redundancy.","followUp":"Authentication ở gateway có thay authorization trong service không?","note":"communication","level":"Cơ bản"},{"id":"cqrs","question":"CQRS có bắt buộc event sourcing không?","answer":"Không. Một cái tách mô hình đọc/ghi; cái kia chọn event log làm nguồn sự thật.","explanation":"Có thể dùng độc lập hoặc kết hợp theo nhu cầu.","followUp":"Read model bị trễ thì UI và nghiệp vụ xử lý ra sao?","note":"patterns","level":"Đào sâu"},{"id":"eventsourcing","question":"Event sourcing khác audit log thế nào?","answer":"Event sourcing dùng event để dựng state chính; audit log có thể chỉ ghi lại thay đổi của state lưu nơi khác.","explanation":"Replay, schema evolution và privacy là trách nhiệm lớn.","followUp":"Event cũ thay đổi schema thì replay thế nào?","note":"patterns","level":"Đào sâu"},{"id":"saga","question":"Saga có rollback như một DB transaction không?","answer":"Không. Nó dùng local transaction và compensation theo nghiệp vụ.","explanation":"Tác động bên ngoài có thể không đảo hoàn toàn; cần state machine và xử lý bù thất bại.","followUp":"Hoàn tiền lỗi sau hủy đơn thì sao?","note":"patterns","level":"Đào sâu"},{"id":"orchestrate","question":"Orchestration khác choreography thế nào?","answer":"Orchestration có điều phối tường minh; choreography dựa phản ứng giữa các bên theo event.","explanation":"Một bên dễ thấy luồng tập trung, bên kia giảm coordinator nhưng khó theo dõi dependency.","followUp":"Bạn debug vòng event vô tình thế nào?","note":"patterns","level":"Cơ bản"},{"id":"strangler","question":"Strangler pattern dùng khi nào?","answer":"Khi thay hệ cũ từng phần để giảm rủi ro so với chuyển toàn bộ một lần.","explanation":"Cần routing, dữ liệu chung/chuyển đổi và rollback được phân tích.","followUp":"Làm sao biết traffic nào còn dùng hệ cũ?","note":"evolution","level":"Vận dụng"},{"id":"adr","question":"Một ADR có ích cần gì?","answer":"Bối cảnh, quyết định, các lựa chọn và hệ quả/đánh đổi.","explanation":"Ghi cả điều kiện xem xét lại giúp tránh coi lựa chọn hiện tại là chân lý vĩnh viễn.","followUp":"Bạn đo quyết định tách service có thành công không?","note":"evolution","level":"Vận dụng"}],"order":23},{"id":"distributed","title":"Consistency & khả năng chịu lỗi","group":"05 · Hệ thống phân tán","description":"Thiết kế với mạng chậm, partition, lỗi từng phần và retry.","sources":[{"title":"AWS retries","url":"https://aws.amazon.com/builders-library/timeouts-retries-and-backoff-with-jitter/"},{"title":"Raft paper","url":"https://raft.github.io/raft.pdf"}],"imageRefs":["A20","D09","D13"],"prerequisites":["database","messaging"],"notes":[{"id":"consistency","title":"CAP, consistency và consensus","body":["CAP nói về không thể cùng giữ linearizability và availability theo định nghĩa của theorem khi có network partition trong mô hình đó. Không phải bảng chọn tùy ý hai trong ba cho mọi thời điểm. PACELC nhắc thêm trade-off consistency/latency khi không partition.","Consistency model như linearizable, causal hoặc eventual mô tả quan sát được; ACID consistency nói về invariant. Consensus giúp node thống nhất quyết định trong giả định lỗi cụ thể; Raft/Paxos không làm mạng hết lỗi."],"example":"","pitfall":"Không gắn CP/AP cố định cho mọi cấu hình của một database.","exercise":"Chuyển tiền và số lượt like có thể chấp nhận stale khác nhau thế nào?"},{"id":"quorum","title":"Quorum, election và distributed lock","body":["Quorum dựa vào tập node chồng lấn theo giao thức; công thức R+W>N một mình chưa chứng minh linearizability cho mọi hệ. Leader election cần term/epoch hoặc cơ chế để leader cũ không tiếp tục tạo tác động.","Lease có thể hết hạn trong lúc process pause hoặc mạng chia cắt. Fencing token tăng đơn điệu, được nơi ghi tài nguyên kiểm tra, giúp từ chối holder cũ. “Có lock trong Redis” chưa đủ kết luận đúng cho nghiệp vụ quan trọng."],"example":"","pitfall":"","exercise":"Vẽ tình huống process A pause, lease hết hạn, B lấy lock, A chạy lại ghi đè B."},{"id":"resilience","title":"Timeout, retry, circuit breaker và bulkhead","body":["Timeout giới hạn chờ; deadline là ngân sách end-to-end cần truyền qua các bước. Retry chỉ cho lỗi phù hợp và thao tác lặp an toàn, với backoff/jitter và retry budget. Retry ở nhiều tầng có thể nhân tải.","Circuit breaker ngừng gọi dependency đang lỗi trong một thời gian, thử hồi phục theo state. Bulkhead cô lập tài nguyên để lỗi một phần không chiếm hết pool. Fallback phải đúng semantics; không trả số dư cũ như xác nhận thanh toán mới."],"example":"","pitfall":"","exercise":"Một request gọi ba tầng, mỗi tầng retry 3 lần: tính tải tệ nhất và chọn nơi retry.","diagram":{"type":"flow","title":"Circuit breaker giản lược","nodes":["Closed · gọi bình thường","Lỗi vượt ngưỡng → Open","Hết thời gian → Half-open","Probe thành công → Closed"],"caption":"Probe thất bại quay Open; ngưỡng và trạng thái cần theo implementation."}},{"id":"recovery","title":"Availability, RPO/RTO và khôi phục","body":["Availability phản ánh khả năng phục vụ theo định nghĩa đo; reliability là vận hành đúng theo thời gian/ngữ cảnh. Redundancy giảm một số điểm lỗi nhưng shared dependency vẫn có thể là SPOF. Failover cần xét dữ liệu trễ và split-brain.","RPO là mức mất dữ liệu chấp nhận theo thời gian; RTO là mục tiêu thời gian khôi phục. Backup cần kiểm tra restore; multi-AZ khác multi-region và không tự thay backup. Chaos test nên có phạm vi, giả thuyết và điều kiện dừng."],"example":"","pitfall":"","exercise":"Thiết kế recovery cho mất một AZ; liệt kê dependency còn dùng chung và bước kiểm tra sau phục hồi."}],"questions":[{"id":"cap","question":"CAP có phải chọn bất kỳ hai trong ba không?","answer":"Không. Trade-off cốt lõi là consistency/availability theo định nghĩa khi network partition xảy ra.","explanation":"Hệ có thể thay hành vi theo operation/cấu hình; không rút gọn thành nhãn sản phẩm.","followUp":"Khi không partition, latency có vai trò gì?","note":"consistency","level":"Đào sâu"},{"id":"acid","question":"Consistency trong ACID và CAP có giống nhau không?","answer":"Không. ACID nói về invariant dữ liệu; CAP nói về mô hình quan sát nhất quán trong hệ phân tán.","explanation":"Cần dùng đúng nghĩa khi trình bày trade-off.","followUp":"Một DB ACID có thể vẫn có stale read từ replica không?","note":"consistency","level":"Cơ bản"},{"id":"eventual","question":"Eventual consistency bảo đảm gì?","answer":"Trong điều kiện phù hợp và không có update mới, các replica sẽ hội tụ theo mô hình hệ thống.","explanation":"Cần nói cách resolve conflict và thời gian trễ; không đồng nghĩa mọi stale đều chấp nhận được.","followUp":"Read-your-writes khác eventual thế nào?","note":"consistency","level":"Cơ bản"},{"id":"quorum","question":"R+W>N có tự chứng minh strong consistency không?","answer":"Không. Còn phụ thuộc protocol, phiên bản, failure behavior và cách chọn/read-repair dữ liệu.","explanation":"Quorum overlap là một điều kiện trong phân tích, không phải toàn bộ proof.","followUp":"Concurrent write được sắp thứ tự ở đâu?","note":"quorum","level":"Đào sâu"},{"id":"fence","question":"Fencing token giải quyết vấn đề gì?","answer":"Ngăn holder cũ tiếp tục ghi sau khi lease hết hạn và holder mới được cấp quyền.","explanation":"Nơi nhận write phải kiểm tra token; chỉ cấp token mà không enforce không đủ.","followUp":"Process pause lâu có thể gây lỗi gì với lock TTL?","note":"quorum","level":"Đào sâu"},{"id":"timeout","question":"Timeout có chứng minh thao tác thất bại không?","answer":"Không. Nó chỉ cho biết bên chờ chưa nhận kết quả trong thời gian cho phép.","explanation":"Server có thể đã commit; dùng idempotency hoặc status lookup khi retry.","followUp":"Thanh toán timeout thì UI nên thông báo thế nào?","note":"resilience","level":"Cơ bản"},{"id":"jitter","question":"Vì sao retry cần jitter?","answer":"Để các client không đồng loạt thử lại đúng cùng thời điểm, giảm thundering herd.","explanation":"Cần backoff, giới hạn và retry budget; jitter không sửa thiếu công suất.","followUp":"Lỗi validation có nên retry không?","note":"resilience","level":"Vận dụng"},{"id":"breaker","question":"Circuit breaker khác retry thế nào?","answer":"Retry thử lại một lỗi; breaker tạm ngừng call khi dependency có dấu hiệu lỗi kéo dài.","explanation":"Kết hợp sai có thể tăng tải hoặc trì hoãn phục hồi; cần metrics và policy.","followUp":"Half-open cho bao nhiêu probe là hợp lý?","note":"resilience","level":"Cơ bản"},{"id":"rpo","question":"RPO và RTO khác nhau thế nào?","answer":"RPO là mất dữ liệu chấp nhận; RTO là thời gian khôi phục mục tiêu.","explanation":"Phải được kiểm chứng bằng backup/restore và diễn tập, không chỉ tài liệu.","followUp":"Backup mỗi ngày có đáp ứng RPO 5 phút không?","note":"recovery","level":"Cơ bản"},{"id":"az","question":"Multi-AZ có loại hết SPOF không?","answer":"Không. Config, control plane, region hoặc dependency ngoài có thể còn dùng chung.","explanation":"Cần vẽ dependency và thử failure theo giả thuyết.","followUp":"Bạn phục hồi khi người vận hành xóa dữ liệu nhầm thế nào?","note":"recovery","level":"Vận dụng"}],"order":24},{"id":"storage-search","title":"File, Search & Data Pipeline","group":"05 · Hệ thống phân tán","description":"Thiết kế upload lớn, tìm kiếm và dữ liệu dẫn xuất có khả năng phục hồi.","sources":[{"title":"S3 multipart","url":"https://docs.aws.amazon.com/AmazonS3/latest/userguide/mpuoverview.html"},{"title":"Elasticsearch overview","url":"https://www.elastic.co/guide/en/elasticsearch/reference/current/elasticsearch-intro.html"}],"imageRefs":["D14–D15","F16","C19"],"prerequisites":["database","messaging"],"notes":[{"id":"storage","title":"Block, file và object storage","body":["Block cung cấp khối lưu trữ cho tầng phía trên; file storage tổ chức theo file/path; object storage dùng object key và metadata theo API. Object storage phù hợp blob/media nhưng không nên giả định thao tác rename hoặc append giống POSIX filesystem.","Lưu file bytes và metadata có vòng đời khác nhau: DB có owner, status, key, checksum; object store giữ nội dung. Cần đối soát file mồ côi, retention, versioning và quyền tải."],"example":"","pitfall":"","exercise":"Thiết kế metadata một file có owner, kích thước, hash, trạng thái scan và hạn dùng."},{"id":"uploads","title":"Multipart upload và signed URL","body":["Client xin quyền upload; server kiểm tra quyền/quota rồi cấp URL giới hạn scope/thời hạn. Client gửi phần dữ liệu trực tiếp object storage, hoàn tất multipart, server xác nhận kích thước/checksum và chuyển trạng thái.","Resume cần biết phần nào đã được xác nhận; multipart chưa hoàn tất cần cleanup để tránh chi phí. Signed URL là capability có thời hạn, phải tránh leak và không cấp quyền rộng hơn use case."],"example":"","pitfall":"","exercise":"Client rời trang sau khi upload 80%: trạng thái và cleanup thế nào?","diagram":{"type":"sequence","title":"Upload trực tiếp object storage","actors":["Client","API","Object storage"],"steps":[[0,1,"Xin upload + metadata"],[1,0,"Upload ID / URL có giới hạn"],[0,2,"Gửi các part"],[0,1,"Yêu cầu finalize"],[1,2,"Xác minh / complete"],[1,0,"File sẵn sàng hoặc đang kiểm tra"]],"caption":"Việc cấp URL không thay validation nội dung và quyền truy cập khi tải."}},{"id":"search","title":"Inverted index, autocomplete và index lag","body":["Inverted index ánh xạ term tới tài liệu để tìm full-text. Analyzer/tokenization ảnh hưởng kết quả theo ngôn ngữ; tìm substring, prefix, fuzzy và semantic search là nhu cầu khác nhau. Database index và search index có mục tiêu khác nhưng có thể cùng phục vụ một số query.","Search thường là dữ liệu dẫn xuất có độ trễ. Đồng bộ bằng event/CDC cần versioning, replay và xử lý delete. Luôn kiểm tra quyền theo tài liệu/tenant, không để search index lộ dữ liệu đã thu hồi quyền."],"example":"","pitfall":"","exercise":"Thiết kế autocomplete tiếng Việt có dấu/không dấu, ranking và giới hạn tốc độ.","diagram":{"type":"graph","title":"Inverted index giản lược","nodes":[[120,70,"Term: database"],[120,215,"Term: cache"],[490,45,"Document 1"],[490,150,"Document 2"],[490,255,"Document 3"]],"edges":[[0,2],[0,3],[1,3],[1,4]],"caption":"Index ánh xạ term tới tài liệu chứa term sau analyzer. Một query kết hợp term có thể giao/hợp tập kết quả và xếp hạng."}},{"id":"pipeline","title":"Batch, stream và recommendation","body":["Batch xử lý tập dữ liệu theo đợt; stream xử lý chuỗi sự kiện liên tục. Stream cần event time vs processing time, late/out-of-order data và cách cập nhật kết quả. Pipeline cần checkpoint/replay và idempotent sink phù hợp.","Recommendation có thể dựa nội dung, tương tác cộng tác hoặc kết hợp. Cần cold start, đánh giá offline/online, privacy và tránh coi click là chất lượng duy nhất. Đây là phần mở rộng khái niệm; không cần triển khai ML để học nền tảng pipeline."],"example":"","pitfall":"","exercise":"Tính DAU theo event time khi sự kiện login đến chậm một ngày."}],"questions":[{"id":"object","question":"Object storage khác file system thế nào?","answer":"Nó cung cấp object theo key/API, không mặc định đầy đủ semantics POSIX của file/path.","explanation":"Chọn theo workload bytes/metadata, latency và thao tác cần có.","followUp":"Rename một folder object có thể thực chất là gì?","note":"storage","level":"Cơ bản"},{"id":"metadata","question":"Vì sao không chỉ lưu URL file trong DB?","answer":"Cần ownership, lifecycle, status, checksum, policy và key ổn định thay vì một URL có thể hết hạn.","explanation":"URL phục vụ có thể được sinh theo quyền tại thời điểm request.","followUp":"Signed URL hết hạn có nghĩa file bị xóa không?","note":"storage","level":"Cơ bản"},{"id":"multipart","question":"Multipart upload giúp gì?","answer":"Cho chia file thành part, song song và retry/resume một phần theo API hỗ trợ.","explanation":"Có chi phí quản lý upload chưa complete và kiểm tra toàn vẹn.","followUp":"Mất một part thì có phải gửi lại toàn bộ file không?","note":"uploads","level":"Cơ bản"},{"id":"signed","question":"Signed URL có tự bảo vệ file mãi không?","answer":"Không. Nó cấp khả năng truy cập theo scope/thời hạn; ai có URL có thể dùng theo hợp đồng.","explanation":"Cần giới hạn quyền, thời gian và tránh log/leak.","followUp":"Bạn thu hồi truy cập trước expiry bằng cách nào theo nền tảng?","note":"uploads","level":"Vận dụng"},{"id":"dedup","question":"Deduplicate file theo hash cần chú ý gì?","answer":"Checksum, collision threat model, quyền riêng tư và vòng đời reference tới object.","explanation":"Không để người khác đoán file tồn tại hoặc đọc file chỉ vì biết hash.","followUp":"Xóa một reference có được xóa object dùng chung không?","note":"storage","level":"Vận dụng"},{"id":"inverted","question":"Inverted index là gì?","answer":"Cấu trúc ánh xạ term tới tài liệu/vị trí phục vụ truy vấn tìm kiếm.","explanation":"Analyzer quyết định term; không chỉ tạo index B-tree trên toàn bộ text.","followUp":"Stop words và tiếng Việt ảnh hưởng gì?","note":"search","level":"Cơ bản"},{"id":"lag","question":"Database đã cập nhật nhưng search chưa đổi thì sao?","answer":"Đó có thể là độ trễ của projection/index; cần SLA freshness và cách đồng bộ.","explanation":"Version event và replay giúp không áp sự kiện cũ đè mới.","followUp":"Xóa dữ liệu nhạy cảm cần xử lý index thế nào?","note":"search","level":"Vận dụng"},{"id":"batch","question":"Batch và stream khác nhau ở đâu?","answer":"Khác mô hình xử lý theo tập/đợt và chuỗi liên tục, kèm trade-off latency và vận hành.","explanation":"Stream vẫn cần xử lý event trễ và khôi phục; không mặc định dễ hơn.","followUp":"Khi nào batch hằng giờ đủ cho nghiệp vụ?","note":"pipeline","level":"Vận dụng"},{"id":"time","question":"Event time khác processing time thế nào?","answer":"Một cái là thời điểm sự kiện xảy ra, một cái là lúc hệ thống xử lý nó.","explanation":"Dữ liệu đến muộn làm cửa sổ/tổng hợp cần policy cập nhật.","followUp":"Báo cáo DAU theo múi giờ nào?","note":"pipeline","level":"Vận dụng"},{"id":"cold","question":"Cold start trong recommendation là gì?","answer":"Thiếu lịch sử cho user/item mới khiến mô hình dựa tương tác khó gợi ý.","explanation":"Có thể dùng nội dung, popularity hoặc hỏi sở thích ban đầu; cần đo tác động.","followUp":"Click tăng nhưng người dùng không hài lòng thì đánh giá sao?","note":"pipeline","level":"Cơ bản"}],"order":25},{"id":"system-design","title":"System Design · Case Studies","group":"05 · Hệ thống phân tán","description":"Luyện từ yêu cầu, ước lượng tới sơ đồ, dữ liệu và tình huống lỗi.","sources":[{"title":"Google SRE books","url":"https://sre.google/books/"},{"title":"AWS Builders Library","url":"https://aws.amazon.com/builders-library/"}],"imageRefs":["A13","D02–D03","D05","D19–D20","F18"],"prerequisites":["api","database","cache","messaging","distributed"],"notes":[{"id":"method","title":"Khung giải bài System Design","body":["Làm rõ người dùng/use case và điều không cần làm; chọn non-functional requirements có số đo; ước lượng RPS/storage/bandwidth; định nghĩa API/data; vẽ kiến trúc đơn giản; đào sâu bottleneck và failure mode. Kết thúc bằng trade-off và kế hoạch tiến hóa.","Ví dụ 1 triệu DAU, mỗi người 20 request/ngày: trung bình khoảng 231 RPS, không phải peak. Nếu giả định peak gấp 10 thì khoảng 2.310 RPS. Kích thước payload, cache hit, read/write ratio và retention quyết định phần tiếp theo."],"example":"","pitfall":"Không chọn Kafka/microservices/sharding trước khi có yêu cầu và bottleneck.","exercise":"Ước lượng lưu 5 triệu event/ngày, 1 KB/event trong 30 ngày; thêm replication và index theo giả định."},{"id":"shortener","title":"URL shortener & Pastebin","body":["URL shortener cần mapping code→URL, expiry, rate limit và kiểm tra abuse. Unique key bảo vệ collision; ID tuần tự+encoding khác random code về khả năng đoán và phân bố. Redirect thường read-heavy nên cache hữu ích; loại redirect/cache policy phụ thuộc nhu cầu analytics và chỉnh URL.","Pastebin thêm nội dung text, size limit, visibility, retention và kiểm soát truy cập. Đừng cho private paste thành public chỉ vì URL khó đoán. Analytics có thể đi async để không chặn redirect."],"example":"","pitfall":"","exercise":"Đổi URL đích của một short code: cache/redirect cũ còn tác dụng thế nào?","diagram":{"type":"flow","title":"URL shortener","nodes":["Client → redirect API","Cache mapping","Miss → DB unique code","302/307 theo hợp đồng","Event analytics → queue"],"caption":"Thêm expiry, abuse policy và authorization theo loại link; code không thay quyền."}},{"id":"chat","title":"Chat, notification & news feed","body":["Chat cần connection registry, message ID/order theo conversation, durable storage và delivery/read status riêng. WebSocket chỉ là transport; offline user cần lưu và sync lại. Dedup message khi reconnect/retry theo client-generated ID hoặc key phù hợp.","Notification thêm preferences, đa kênh, retry và provider limits. Feed có fan-out-on-write, fan-out-on-read hoặc hybrid: user nhiều follower làm write fan-out đắt; timeline cache cần freshness và privacy sau khi xóa/chặn."],"example":"","pitfall":"","exercise":"User gửi message rồi mất kết nối trước ACK: thiết kế retry không tạo hai tin."},{"id":"commerce","title":"Commerce, payment, wallet & booking","body":["Commerce tách catalog/search, cart, order, inventory và payment theo trách nhiệm trước khi quyết định service. Inventory cần phép giữ/trừ nguyên tử, reservation expiry và trạng thái order. Payment dùng idempotency, state machine, webhook và reconciliation.","Wallet nên có ledger có thể audit, invariant tiền và đối soát; không chỉ một cột balance được cập nhật tùy ý. Booking ghế/phòng cần định nghĩa độc quyền theo tài nguyên và khoảng thời gian, DB constraint/lock cùng chiến lược khi thanh toán chậm."],"example":"","pitfall":"","exercise":"Thanh toán tới sau khi reservation hết hạn: chọn policy hoàn tiền hoặc xử lý ngoại lệ.","diagram":{"type":"flow","title":"Checkout có trạng thái","nodes":["Giữ hàng có thời hạn","Tạo order pending","Payment idempotent","Xác nhận hoặc hủy/giải phóng","Outbox thông báo + đối soát"],"caption":"Mọi chuyển trạng thái phải chịu retry, webhook trùng và crash; sơ đồ không là một transaction DB toàn cục."}},{"id":"media","title":"Drive, photo sharing & video streaming","body":["File sharing cần object store, metadata DB, quyền truy cập, multipart và CDN. Photo sharing thêm các bản resize, job xử lý, moderation theo yêu cầu và feed. Video thêm ingest, transcode thành nhiều bitrate, manifest và segments để adaptive playback.","Live streaming có pipeline và mục tiêu latency khác video on-demand. Băng thông egress, dung lượng nhiều phiên bản, quyền private và lifecycle thường quan trọng hơn việc thêm service tùy ý."],"example":"","pitfall":"","exercise":"Một video gốc 1 GB có 5 rendition: ước lượng storage bằng bitrate/độ dài thay vì nhân máy móc 5 lần."},{"id":"specialized","title":"Search, ride-hailing, cộng tác và trading","body":["Search/autocomplete cần index, ranking và đồng bộ nguồn dữ liệu. Ride-hailing cần location updates, spatial index, matching và trip state; không chỉ bảng users. Collaborative editor cần mô hình thao tác và conflict resolution như OT/CRDT cùng quyền và persistence.","Game realtime cần authority/state synchronization và latency budget; stock trading cần thứ tự lệnh, matching, ledger, audit và failure recovery theo yêu cầu. Đây là bài khác nhau, không dùng chung một sơ đồ chỉ đổi tên."],"example":"","pitfall":"","exercise":"Chọn một case, ghi invariant không được vi phạm và ba kiểu lỗi phải xử lý."}],"questions":[{"id":"start","question":"Bắt đầu một bài System Design thế nào?","answer":"Làm rõ yêu cầu và quy mô, sau đó đưa mô hình đơn giản đáp ứng use case.","explanation":"Không lao vào công nghệ; hỏi consistency, latency, availability và phạm vi.","followUp":"Bạn ưu tiên ba câu hỏi làm rõ nào?","note":"method","level":"Vận dụng"},{"id":"rps","question":"DAU có bằng RPS không?","answer":"Không. Cần số request/user và phân bố thời gian để ước lượng RPS trung bình/peak.","explanation":"Ghi giả định và units; đọc/ghi và payload ảnh hưởng thành phần khác nhau.","followUp":"Tại sao peak không chỉ là số DAU chia 86400?","note":"method","level":"Vận dụng"},{"id":"scale","question":"Vertical và horizontal scaling chọn thế nào?","answer":"Vertical tăng tài nguyên node; horizontal thêm node, cần phân chia tải/state.","explanation":"Cả hai có giới hạn và chi phí; database và shared dependency có thể vẫn nghẽn.","followUp":"Sticky session ảnh hưởng failover ra sao?","note":"method","level":"Vận dụng"},{"id":"url","question":"URL shortener tạo code không trùng thế nào?","answer":"Dùng cơ chế ID/encoding hoặc random với uniqueness check/constraint và retry collision.","explanation":"Cần xét khả năng đoán, phân bố, expiry và abuse.","followUp":"Code càng ngắn ảnh hưởng không gian khóa thế nào?","note":"shortener","level":"Cơ bản"},{"id":"chat","question":"WebSocket có đủ xây chat tin cậy không?","answer":"Không. Cần storage, ACK nghiệp vụ, ordering/dedup và đồng bộ sau reconnect.","explanation":"TCP connection không thay message state hoặc offline delivery.","followUp":"Sent, delivered và read khác nhau thế nào?","note":"chat","level":"Cơ bản"},{"id":"feed","question":"Fan-out-on-write khác fan-out-on-read thế nào?","answer":"Một cách chuẩn bị feed khi đăng, cách kia tổng hợp khi đọc.","explanation":"Celebrity workload, freshness và chi phí quyết định hybrid.","followUp":"Xóa bài/private account xử lý bản feed đã cache thế nào?","note":"chat","level":"Cơ bản"},{"id":"payment","question":"Ngăn charge trùng bằng gì?","answer":"Idempotency theo ý định, state machine và provider contract, kèm reconciliation.","explanation":"Client timeout không xác nhận charge chưa xảy ra; webhook có thể đến trước/sau.","followUp":"Bạn phục hồi trạng thái pending lâu thế nào?","note":"commerce","level":"Vận dụng"},{"id":"booking","question":"Ngăn bán một ghế hai lần thế nào?","answer":"Biểu diễn invariant trong DB với constraint/transaction/lock phù hợp, không chỉ kiểm tra UI.","explanation":"Reservation và thanh toán có vòng đời riêng; cần policy hết hạn và bù.","followUp":"Hai replica cùng thấy ghế trống thì sao?","note":"commerce","level":"Vận dụng"},{"id":"wallet","question":"Vì sao wallet cần ledger?","answer":"Để truy vết nguồn biến động, đối soát và kiểm chứng invariant thay vì chỉ tin số dư cuối.","explanation":"Cần cân đối entries, idempotency và audit theo nghiệp vụ.","followUp":"Một giao dịch sửa sai được xóa hay tạo entry điều chỉnh?","note":"commerce","level":"Vận dụng"},{"id":"video","question":"Thiết kế video streaming gồm bước nào?","answer":"Ingest/upload, lưu nguồn, transcode, manifest/segments, CDN và playback.","explanation":"Live/VOD khác latency, backpressure và failure recovery.","followUp":"Client chọn bitrate theo điều kiện nào?","note":"media","level":"Vận dụng"},{"id":"collab","question":"Collaborative editor khác chat ở điểm nào?","answer":"Nó cần hội tụ trạng thái tài liệu khi thao tác cạnh tranh, không chỉ giao tin nhắn.","explanation":"OT/CRDT có giả định và chi phí; còn cần undo, permissions và persistence.","followUp":"Hai người xóa/chèn cùng vị trí thì sao?","note":"specialized","level":"Đào sâu"},{"id":"tradeoff","question":"Kết thúc bài thiết kế nên trình bày gì?","answer":"Bottleneck, failure modes, security, chi phí và lựa chọn thay thế có điều kiện.","explanation":"Nêu giới hạn hiện tại và tín hiệu cần tiến hóa, không tuyên bố scale vô hạn.","followUp":"Yêu cầu nào thay đổi sẽ khiến bạn chọn thiết kế khác?","note":"method","level":"Đào sâu"}],"order":26},{"id":"testing","title":"Testing & Debugging","group":"06 · Chất lượng & Vận hành","description":"Chọn kiểm tra theo rủi ro và điều tra lỗi bằng giả thuyết có bằng chứng.","sources":[{"title":"Playwright assertions","url":"https://playwright.dev/docs/test-assertions"},{"title":"Google testing blog","url":"https://testing.googleblog.com/"}],"imageRefs":["A18–A19","F20"],"prerequisites":["backend","react"],"notes":[{"id":"boundaries","title":"Unit, integration, E2E và contract","body":["Unit kiểm tra phần nhỏ với dependency được kiểm soát; integration kiểm tra các thành phần làm việc cùng nhau; E2E đi qua một luồng người dùng/hệ thống rộng hơn. Contract test kiểm tra kỳ vọng giao tiếp producer–consumer. Ranh giới cụ thể cần được nhóm thống nhất.","Chọn theo rủi ro: tính phí có nhiều unit case; transaction/SQL cần integration DB; checkout cần vài E2E quan trọng. Không dùng một tỷ lệ test pyramid cứng để thay phân tích lỗi đáng ngại."],"example":"","pitfall":"","exercise":"Phân bổ test cho tính giảm giá, đặt vé đồng thời và email provider lỗi.","diagram":{"type":"graph","title":"Phạm vi test và ranh giới dependency","nodes":[[320,50,"Hành vi nghiệp vụ"],[110,175,"Unit"],[320,175,"Integration"],[530,175,"End-to-end"]],"edges":[[0,1],[0,2],[0,3]],"caption":"Unit kiểm tra phần nhỏ; integration kiểm tra ranh giới thật; E2E kiểm tra hành trình rộng. Hình không quy định tỷ lệ hoặc số lượng test bắt buộc."}},{"id":"fixtures","title":"Mock, fake, fixture và tính cô lập","body":["Mock kiểm tra tương tác theo kỳ vọng; stub trả dữ liệu định trước; fake là implementation đơn giản có hành vi. Fixtures chuẩn bị dữ liệu/tài nguyên có lifecycle và cleanup. Mock quá nhiều có thể làm test pass dù contract thật sai.","Dùng database thật tương đương môi trường mục tiêu cho semantics SQL quan trọng. Không dùng SQLite để kết luận isolation/index của PostgreSQL đúng. Test độc lập cần tránh phụ thuộc thứ tự, clock thật và dữ liệu dùng chung."],"example":"// Kiểm tra hành vi quan trọng\nexpect(result.total).toBe(90000);\n// Đừng chỉ kiểm tra helper nội bộ được gọi đúng số lần.","pitfall":"Test bám cấu trúc implementation quá sát sẽ cản refactor mà không bảo vệ hành vi.","exercise":"Tạo fixture với NULL, dữ liệu trùng, timezone và hai request cạnh tranh."},{"id":"quality","title":"Coverage, flaky test và load test","body":["Coverage chỉ cho biết code được thực thi theo một thước đo, không chứng minh assertion tốt hay case đủ. Flaky test có thể do timing, dữ liệu chia sẻ, không chờ đúng điều kiện hoặc bug race thật. Retry test không thay sửa nguyên nhân.","Load test mô phỏng tải dự kiến; stress tìm giới hạn; soak tìm vấn đề theo thời gian. Ghi workload, phân bố, test data và mục tiêu. Đo p95/p99, errors, saturation và dependency thay vì chỉ RPS."],"example":"","pitfall":"","exercise":"Thiết kế load test login và checkout với tỷ lệ đọc/ghi thật, không dùng cache nóng cho mọi request."},{"id":"debug","title":"Debug có phương pháp","body":["Xác định triệu chứng và phạm vi, dựng timeline, tái hiện hoặc thu bằng chứng, đặt giả thuyết, thực hiện phép kiểm tra nhỏ rồi đánh giá. Bắt đầu từ thay đổi gần đây nhưng không mặc định đó là nguyên nhân. Request ID và trace nối dữ liệu giữa service.","Sau fix, thêm kiểm tra hành vi tái hiện lỗi quan trọng, xác nhận rollout và theo dõi. Incident review tập trung điều kiện hệ thống và cải tiến, không chỉ “ai viết dòng này”."],"example":"","pitfall":"","exercise":"API p99 tăng sau deploy: chọn ba phép kiểm tra trước khi rollback hay tối ưu.","diagram":{"type":"flow","title":"Vòng điều tra lỗi","nodes":["Triệu chứng + phạm vi","Bằng chứng / timeline","Giả thuyết có thể bác bỏ","Thử nghiệm nhỏ","Fix → kiểm chứng → theo dõi"],"caption":"Đổi nhiều thứ cùng lúc làm khó biết điều gì thực sự sửa lỗi."}}],"questions":[{"id":"types","question":"Unit và integration test khác nhau thế nào?","answer":"Khác phạm vi dependency thực và hành vi tích hợp được kiểm chứng.","explanation":"Tên gọi cần convention; quan trọng là test phát hiện loại lỗi nào.","followUp":"Một test query DB thật bảo vệ gì mà mock không bảo vệ?","note":"boundaries","level":"Cơ bản"},{"id":"mock","question":"Khi nào mock là không đủ?","answer":"Khi lỗi nằm ở SQL, protocol, transaction hoặc hợp đồng thật đã thay đổi.","explanation":"Kết hợp test phạm vi phù hợp với dependency thật và dữ liệu đại diện.","followUp":"Test gateway thanh toán sandbox có thay unit test không?","note":"fixtures","level":"Vận dụng"},{"id":"contract","question":"Contract test có thay E2E không?","answer":"Không. Nó bảo vệ hợp đồng giao tiếp, chưa chứng minh toàn luồng nghiệp vụ hoạt động.","explanation":"Cần phối hợp test ranh giới và một số luồng quan trọng.","followUp":"Schema đúng nhưng auth/config sai thì sao?","note":"boundaries","level":"Cơ bản"},{"id":"coverage","question":"100% coverage có nghĩa không còn bug không?","answer":"Không. Có thể chạy mọi dòng nhưng thiếu assertion và tổ hợp dữ liệu.","explanation":"Branch coverage cũng không chứng minh hết trạng thái/race.","followUp":"Bạn chọn edge case theo invariant thế nào?","note":"quality","level":"Cơ bản"},{"id":"flaky","question":"Test flaky nên xử lý ra sao?","answer":"Thu dữ liệu, tìm điều kiện không xác định và phân biệt lỗi test với race thật.","explanation":"Dùng chờ theo điều kiện thay sleep cố định; cô lập data/clock khi phù hợp.","followUp":"Retry liên tục có che mất vấn đề gì?","note":"quality","level":"Vận dụng"},{"id":"db","question":"Vì sao DB integration test cần đúng DBMS?","answer":"Semantics kiểu dữ liệu, SQL, lock và isolation có khác biệt.","explanation":"Fake hoặc DB khác không chứng minh behavior của DB mục tiêu.","followUp":"Bạn dựng dữ liệu và rollback/cleanup thế nào?","note":"fixtures","level":"Cơ bản"},{"id":"load","question":"Load, stress và soak khác nhau thế nào?","answer":"Khác mục tiêu: tải dự kiến, vượt giới hạn và chạy dài để tìm vấn đề tích lũy.","explanation":"Workload thực và metric quyết định ý nghĩa kết quả.","followUp":"Memory leak thường dễ lộ ở loại nào?","note":"quality","level":"Vận dụng"},{"id":"debug","question":"Bước đầu khi debug production là gì?","answer":"Xác định ảnh hưởng, timeline, rủi ro và dữ liệu quan sát trước khi thay đổi.","explanation":"Nếu cần giảm thiệt hại có thể rollback/mitigate trước rồi điều tra nguyên nhân.","followUp":"Bạn kiểm chứng giả thuyết DB pool nghẽn thế nào?","note":"debug","level":"Vận dụng"},{"id":"reproduce","question":"Không tái hiện local được thì làm gì?","answer":"So sánh cấu hình, dữ liệu, tải, timing và dependency; thu trace/log phù hợp quyền.","explanation":"Tạo môi trường/case gần điều kiện lỗi, tránh in secret để tìm nhanh.","followUp":"Bạn thêm instrumentation tối thiểu nào?","note":"debug","level":"Vận dụng"},{"id":"regression","question":"Regression test tốt cho bug đã sửa là gì?","answer":"Test thất bại trên hành vi cũ và bảo vệ invariant đúng sau fix.","explanation":"Không chỉ assert helper mới tồn tại; kiểm tra kết quả quan sát được.","followUp":"Test đó nên ở tầng nào để ổn định?","note":"fixtures","level":"Vận dụng"}],"order":27},{"id":"docker-cicd","title":"Docker, CI/CD & Cloud","group":"06 · Chất lượng & Vận hành","description":"Đóng gói một lần, triển khai có kiểm soát và phục hồi được.","sources":[{"title":"Docker overview","url":"https://docs.docker.com/get-started/docker-overview/"},{"title":"GitHub Actions","url":"https://docs.github.com/en/actions"}],"imageRefs":["A17","F19"],"prerequisites":["linux","testing"],"notes":[{"id":"containers","title":"Image, container, volume và network","body":["Image là template gồm các layer và metadata; container là instance chạy với cấu hình/ràng buộc. Container trên Linux chia sẻ kernel host, không phải VM đầy đủ. Docker Desktop thường dùng môi trường VM để chạy Linux container trên hệ khác.","Writable layer có thể mất khi container bị loại; dữ liệu cần tồn tại dùng volume hoặc dịch vụ bên ngoài. EXPOSE mô tả cổng, không tự publish ra host. Trong container, localhost chỉ namespace mạng tương ứng."],"example":"","pitfall":"","exercise":"Ứng dụng bind 127.0.0.1 trong container: vì sao port publish vẫn có thể không gọi được?","diagram":{"type":"flow","title":"Từ source đến chạy","nodes":["Source + lockfile","Build image nhiều stage","Registry · image digest","Container + runtime config","Volume / database ngoài"],"caption":"Artifact và runtime config có vòng đời khác nhau; không bake secret vào image."}},{"id":"build","title":"Dockerfile và build có thể tái tạo","body":["Multi-stage tách build tools khỏi runtime artifact. Copy lockfile và cài dependency theo chế độ phù hợp giúp cache và reproducibility. Chạy non-root khi có thể, giảm context bằng .dockerignore, pin phiên bản/digest theo policy và scan/update dependency.","Secret trong build ARG/layer có thể bị lộ; dùng cơ chế build secret của công cụ. Image nhỏ không tự là an toàn, vẫn cần provenance, quyền và runtime policy."],"example":"# Ví dụ Node có package-lock.json, không có bước compile\nFROM node:24-bookworm-slim\nWORKDIR /app\nCOPY package*.json ./\nRUN npm ci --omit=dev\nCOPY --chown=node:node . .\nUSER node\nCMD [\"node\", \"server.js\"]","pitfall":"Đây là ví dụ môi trường; kiểm tra Node/package compatibility và policy pin trước dùng production.","exercise":"Viết .dockerignore loại .git, node_modules, .env và ảnh nguồn không cần thiết."},{"id":"pipeline","title":"CI, continuous delivery và deployment","body":["CI tích hợp thay đổi thường xuyên với build/check tự động. Continuous delivery giữ phiên bản sẵn sàng triển khai; continuous deployment tự động đưa thay đổi đạt điều kiện lên môi trường mục tiêu. Thuật ngữ CD cần nói rõ.","Pipeline hợp lý: checkout → dependency theo lockfile → kiểm tra → build artifact → scan theo policy → publish → deploy → smoke/health check. Build một artifact rồi promote giúp môi trường chạy cùng phiên bản. Secrets cấp theo môi trường và quyền tối thiểu."],"example":"","pitfall":"","exercise":"Xác định artifact ID và bằng chứng smoke test của một release."},{"id":"release","title":"Rolling, blue-green, canary và cloud","body":["Rolling thay instance dần; blue-green chuyển traffic giữa hai nhóm; canary đưa ít traffic trước rồi tăng theo số đo. Mọi chiến lược đều cần health, metric và tương thích dữ liệu. Rollback code không tự rollback DB hoặc side effect.","Cloud gồm compute, network, IAM, storage và managed services. EC2 quản lý VM; ECS/EKS có mô hình orchestration khác nhau. Chọn theo đội ngũ, kiểm soát, chi phí và reliability, không mặc định Kubernetes cho mọi app."],"example":"","pitfall":"Một backup hoặc health check 200 không đủ chứng minh release an toàn về nghiệp vụ.","exercise":"Thiết kế canary 5% với điều kiện dừng theo error rate, latency và lỗi đặt đơn."}],"questions":[{"id":"vm","question":"Container khác VM thế nào?","answer":"Container thường chia sẻ kernel và cô lập bằng cơ chế OS; VM có guest OS/kernel qua hypervisor.","explanation":"Ranh giới và overhead khác; container không tự an toàn như mọi cấu hình VM.","followUp":"Linux container trên macOS chạy qua đâu?","note":"containers","level":"Cơ bản"},{"id":"image","question":"Image và container khác nhau thế nào?","answer":"Image là template; container là instance có trạng thái runtime và writable layer.","explanation":"Cùng image có thể chạy nhiều container với config khác.","followUp":"Xóa container có xóa volume không?","note":"containers","level":"Cơ bản"},{"id":"port","question":"EXPOSE có publish port không?","answer":"Không. Cần cấu hình publish/network phù hợp.","explanation":"Ứng dụng còn phải listen đúng interface và port.","followUp":"127.0.0.1 trong container có phải host không?","note":"containers","level":"Cơ bản"},{"id":"stage","question":"Multi-stage build giúp gì?","answer":"Tách công cụ build khỏi runtime image và chỉ mang artifact cần thiết.","explanation":"Cần kiểm tra native libraries/runtime dependencies vẫn có đủ.","followUp":"Build ở một kiến trúc rồi chạy kiến trúc khác cần gì?","note":"build","level":"Cơ bản"},{"id":"secret","question":"Vì sao không COPY .env vào image?","answer":"Secret có thể nằm trong layer/registry và bị truy cập qua nhiều bản sao.","explanation":"Inject bằng cơ chế phù hợp lúc chạy/build, kiểm soát quyền và rotation.","followUp":"Xóa .env ở layer sau có xóa khỏi layer trước không?","note":"build","level":"Vận dụng"},{"id":"ci","question":"CI khác continuous deployment thế nào?","answer":"CI tập trung tích hợp/kiểm tra; continuous deployment tự đưa phiên bản đạt điều kiện lên môi trường.","explanation":"Continuous delivery có thể giữ bước quyết định triển khai.","followUp":"Một pipeline build pass đã chứng minh deploy thành công chưa?","note":"pipeline","level":"Cơ bản"},{"id":"artifact","question":"Vì sao build một lần rồi promote?","answer":"Để các môi trường chạy cùng artifact, giảm khác biệt do build/dependency.","explanation":"Config vẫn cần theo môi trường; ghi digest và release metadata.","followUp":"Bạn xác định bản đang chạy bằng cách nào?","note":"pipeline","level":"Vận dụng"},{"id":"canary","question":"Canary cần những gì ngoài chia 5% traffic?","answer":"Metric đáng tin, nhóm so sánh, thời gian quan sát và điều kiện rollback.","explanation":"Phải xét sticky session, dữ liệu và traffic đủ đại diện.","followUp":"Error chỉ xảy ra ở một tenant lớn thì sao?","note":"release","level":"Vận dụng"},{"id":"rollback","question":"Rollback app có khôi phục DB tự động không?","answer":"Không. Schema/data và side effect có vòng đời riêng.","explanation":"Expand–contract và migration compatibility giảm rủi ro.","followUp":"Canary mới ghi format mà bản cũ không đọc được thì sao?","note":"release","level":"Đào sâu"},{"id":"cloud","question":"Khi nào chưa cần Kubernetes?","answer":"Khi nền tảng đơn giản/managed service đáp ứng yêu cầu với chi phí vận hành thấp hơn.","explanation":"Quyết định theo workload, đội ngũ, reliability và khả năng quản trị.","followUp":"Một web tĩnh cần container cluster để làm gì?","note":"release","level":"Vận dụng"}],"order":28},{"id":"kubernetes","title":"Kubernetes · triển khai & vận hành","group":"06 · Chất lượng & Vận hành","description":"Tách rõ workload, networking, cấu hình, storage và tình huống lỗi.","sources":[{"title":"Kubernetes concepts","url":"https://kubernetes.io/docs/concepts/"},{"title":"Probes","url":"https://kubernetes.io/docs/concepts/workloads/pods/probes/"},{"title":"Resource management","url":"https://kubernetes.io/docs/concepts/configuration/manage-resources-containers/"}],"imageRefs":["A17","F19"],"prerequisites":["docker-cicd","network"],"notes":[{"id":"objects","title":"Cluster, node, Pod và controller","body":["Control plane giữ trạng thái mong muốn và phối hợp hệ thống; node chạy workload. Pod là đơn vị triển khai với một hoặc nhiều container chia sẻ một số tài nguyên như network namespace. Deployment quản lý replica thông qua controller/ReplicaSet.","Pod có vòng đời và có thể được thay bằng Pod mới với identity/IP khác. Service cung cấp abstraction truy cập ổn định theo selector/endpoints. Không lưu identity ứng dụng bằng IP một Pod tạm thời."],"example":"","pitfall":"","exercise":"Xóa một Pod do Deployment quản lý rồi quan sát controller tạo Pod thay thế.","diagram":{"type":"flow","title":"Traffic tới workload","nodes":["Client → entry Gateway/Ingress","Service → endpoints phù hợp","Pod A / Pod B trên node","Container ứng dụng","Database / storage theo thiết kế"],"caption":"Ingress cần controller; Gateway API cũng cần implementation. Không phải tạo resource là tự có load balancer ngoài."}},{"id":"health","title":"Readiness, liveness và startup probe","body":["Readiness quyết định Pod có sẵn sàng nhận traffic qua cơ chế endpoint phù hợp. Liveness kiểm tra có cần restart container không. Startup probe cho ứng dụng khởi động chậm; khi cấu hình, nó ảnh hưởng thời điểm các probe khác được thực hiện theo semantics K8s.","Không dùng dependency ngoài lỗi làm liveness restart cả fleet vô ích. Shutdown cần nhận SIGTERM, ngừng nhận việc, drain trong grace period và đóng tài nguyên. Readiness không tự hoàn tất mọi kết nối đang chạy."],"example":"","pitfall":"DB tạm chậm mà restart toàn bộ app có thể làm outage nặng hơn.","exercise":"Thiết kế readiness/liveness cho API và worker queue; xác định deadline shutdown."},{"id":"resources","title":"Requests, limits, ConfigMap và Secret","body":["Scheduler dùng requests và các ràng buộc để đặt Pod. CPU limit có thể gây throttling; memory limit có thể dẫn OOM kill theo cơ chế hệ thống. Requests không đơn giản là lượng dùng cố định. QoS và eviction cũng cần xét khi node thiếu tài nguyên.","ConfigMap chứa cấu hình không bí mật; Secret là resource cho dữ liệu nhạy cảm nhưng base64 không phải mã hóa. Cần RBAC, encryption at rest theo cấu hình và quản lý rotation. Không commit secret thật vào manifest."],"example":"resources:\n  requests:\n    cpu: \"100m\"\n    memory: \"128Mi\"\n  limits:\n    cpu: \"500m\"\n    memory: \"256Mi\"","pitfall":"Con số minh họa không phải cấu hình tối ưu cho mọi app. Cần load test/metrics.","exercise":"Pod Pending: kiểm tra requests, node capacity, affinity, taint/toleration và volume."},{"id":"operations","title":"Storage, scaling, rollout và debug","body":["PVC là yêu cầu storage theo model; PV/StorageClass/driver cung cấp tài nguyên theo môi trường. StatefulSet cung cấp identity/order phù hợp workload stateful, không tự biến database thành HA đúng. HPA scale theo metric và cấu hình; tăng Pod không sửa DB nghẽn.","Điều tra theo trạng thái: Pending xem scheduling events; CrashLoopBackOff xem logs và previous logs; không có traffic xem Service selector/endpoints/readiness; OOMKilled xem memory. Helm đóng gói template; GitOps quản lý desired state; Terraform thường quản lý hạ tầng theo phạm vi."],"example":"kubectl get pods,svc,deploy\nkubectl describe pod \u003cpod>\nkubectl logs \u003cpod> --previous\nkubectl rollout status deployment/\u003cname>\nkubectl get endpointslices","pitfall":"Không sửa tay production rồi quên reconcile desired state trong GitOps.","exercise":"Tạo runbook cho “Pod Running nhưng API không truy cập được”."},{"id":"networking","title":"Service, DNS, Gateway/Ingress và NetworkPolicy","body":["ClusterIP phục vụ truy cập trong cluster theo cấu hình; NodePort mở port trên node; LoadBalancer yêu cầu integration của môi trường. Service DNS giúp client tìm Service; selector/endpoints/readiness nối abstraction tới workload thực. Ingress là resource cần controller; Gateway API là họ API riêng cần implementation.","NetworkPolicy mô tả policy mạng và cần CNI hỗ trợ/enforce. Namespace không tự tạo ranh giới bảo mật đầy đủ. TLS, service identity và application authorization vẫn cần xét độc lập."],"example":"","pitfall":"","exercise":"Service có endpoint nhưng 502 ở ingress: liệt kê target port, protocol, TLS và health cần kiểm tra.","diagram":{"type":"graph","title":"Service selector nối đến các Pod sẵn sàng","nodes":[[110,150,"Client"],[320,150,"Service"],[535,60,"Pod A ready"],[535,150,"Pod B ready"],[535,250,"Pod C not ready"]],"edges":[[0,1],[1,2],[1,3]],"caption":"Sơ đồ entry ổn định tới endpoint phù hợp; Pod C không nhận traffic qua readiness thông thường. Traffic đang tồn tại và policy cụ thể cần được phân tích riêng."}},{"id":"rollout","title":"Deployment rollout, disruption và autoscaling","body":["Rolling update điều chỉnh maxSurge/maxUnavailable để cân bằng capacity và tài nguyên dư. PodDisruptionBudget giới hạn một số voluntary disruption theo cơ chế, không bảo đảm chống mọi node failure. Topology spread/anti-affinity giúp phân tán workload nhưng có thể làm scheduling Pending khi constraint quá chặt.","HPA thay replica; cluster autoscaler thêm/bớt node theo nền tảng. Hai vòng có độ trễ. Startup, readiness, capacity downstream và min/max replica cần được phối hợp. Helm chart và GitOps phải giữ secret/ownership rõ."],"example":"","pitfall":"","exercise":"Thiết kế rollout cho API 3 replica có một node mất; xác định remaining capacity và rủi ro nếu DB chỉ chịu 4 pool."}],"questions":[{"id":"pod","question":"Pod khác container thế nào?","answer":"Pod là đơn vị K8s chứa container cùng vòng đời và một số tài nguyên chia sẻ.","explanation":"Không nên gộp mọi service vào một Pod chỉ để gọi localhost.","followUp":"Khi nào sidecar hợp lý?","note":"objects","level":"Cơ bản"},{"id":"deploy","question":"Deployment khác Service thế nào?","answer":"Deployment duy trì workload/replica; Service cung cấp abstraction mạng tới endpoint phù hợp.","explanation":"Selector sai có thể khiến Service không trỏ tới Pod nào dù Deployment khỏe.","followUp":"Pod đổi IP thì client dựa vào gì?","note":"objects","level":"Cơ bản"},{"id":"probe","question":"Readiness khác liveness thế nào?","answer":"Readiness ảnh hưởng khả năng nhận traffic; liveness có thể dẫn restart container khi fail.","explanation":"Startup probe bảo vệ giai đoạn khởi động dài theo cấu hình.","followUp":"DB downtime có nên làm liveness fail không?","note":"health","level":"Cơ bản"},{"id":"pending","question":"Pod Pending thì kiểm tra gì?","answer":"Scheduling events, requests/capacity, constraints, taints và volume binding.","explanation":"Không chỉ xem application log vì container có thể chưa chạy.","followUp":"Tăng replica có giúp nếu cluster không đủ RAM không?","note":"operations","level":"Vận dụng"},{"id":"crash","question":"CrashLoopBackOff có nghĩa gì?","answer":"Container liên tục kết thúc/lỗi và được restart với backoff.","explanation":"Xem last termination reason, exit code, current/previous logs, config và probe.","followUp":"Lỗi config khác OOMKilled ra sao?","note":"operations","level":"Vận dụng"},{"id":"limits","question":"CPU limit và memory limit có tác động giống nhau không?","answer":"Không. CPU thường bị throttling; vượt memory có thể bị OOM kill theo cơ chế.","explanation":"Cần đo và xét QoS/node pressure, không chỉ đặt số ngẫu nhiên.","followUp":"p99 tăng do throttling nhận biết thế nào?","note":"resources","level":"Vận dụng"},{"id":"secret","question":"Secret base64 đã được mã hóa an toàn chưa?","answer":"Không. Base64 là encoding; bảo vệ cần RBAC, encryption và policy phù hợp.","explanation":"Người đọc được Secret có thể decode; tránh commit credential thật.","followUp":"Rotation có tự cập nhật environment của process đang chạy không?","note":"resources","level":"Vận dụng"},{"id":"hpa","question":"HPA có tự sửa mọi overload không?","answer":"Không. Cần metric đúng, tài nguyên/cluster và dependency đủ công suất.","explanation":"Lag scale, warmup và bottleneck DB có thể làm tăng Pod không hiệu quả.","followUp":"Worker queue nên dùng metric nào?","note":"operations","level":"Đào sâu"},{"id":"stateful","question":"StatefulSet có tự làm database HA không?","answer":"Không. Nó hỗ trợ identity/order/storage association theo mô hình; replication/failover do DB/operator và thiết kế.","explanation":"Backup/restore, consistency và quorum vẫn cần vận hành.","followUp":"Mất zone chứa volume thì recovery ra sao?","note":"operations","level":"Đào sâu"},{"id":"tools","question":"Helm, GitOps và Terraform khác nhau thế nào?","answer":"Helm đóng gói/render chart; GitOps reconcile desired state; Terraform quản lý resource theo provider/state.","explanation":"Chúng có thể phối hợp nhưng cần ownership rõ để không tranh quản lý một resource.","followUp":"Ai là nguồn sự thật khi sửa manifest?","note":"operations","level":"Vận dụng"},{"id":"namespace","question":"Namespace có tự cô lập network không?","answer":"Không. Cần NetworkPolicy/CNI và các policy khác theo yêu cầu.","explanation":"Namespace giúp scope resource, không tự là biên giới bảo mật hoàn chỉnh.","followUp":"RBAC và NetworkPolicy bảo vệ hai việc gì?","note":"networking","level":"Đào sâu"},{"id":"ingress","question":"Tạo Ingress resource có tự nhận traffic Internet không?","answer":"Không. Cần controller/implementation và hạ tầng/network/DNS tương ứng.","explanation":"Resource khai báo desired config; phần thực thi nằm ở hệ đang chạy.","followUp":"Gateway API có cần implementation không?","note":"networking","level":"Đào sâu"},{"id":"pvc","question":"PVC khác PV thế nào?","answer":"PVC là claim storage; PV là resource cung cấp dung lượng theo mô hình K8s.","explanation":"StorageClass/CSI và access mode/topology ảnh hưởng binding.","followUp":"Pod Pending vì volume ở zone khác thì sao?","note":"operations","level":"Đào sâu"},{"id":"pdb","question":"PDB có chống mọi gián đoạn không?","answer":"Không. Nó tác động một số voluntary disruption, không ngăn mọi hardware/node failure.","explanation":"Cần replica, topology và capacity cùng thiết kế.","followUp":"PDB quá chặt có thể cản node drain thế nào?","note":"rollout","level":"Đào sâu"},{"id":"surge","question":"maxSurge và maxUnavailable dùng làm gì?","answer":"Giới hạn Pod tăng thêm và số unavailable trong rolling update theo cấu hình.","explanation":"Cluster cần đủ tài nguyên cho surge; readiness sai có thể chuyển traffic quá sớm.","followUp":"App khởi động 90 giây cần probe gì?","note":"rollout","level":"Đào sâu"},{"id":"autoscaler","question":"HPA khác cluster autoscaler thế nào?","answer":"HPA thay replica workload; cluster autoscaler thay công suất node theo nền tảng/cơ chế.","explanation":"Có độ trễ và giới hạn; thêm Pod có thể Pending trước khi node sẵn sàng.","followUp":"Metric CPU phù hợp mọi worker queue không?","note":"rollout","level":"Đào sâu"},{"id":"rbac","question":"Kubernetes RBAC có thay quyền nghiệp vụ trong API không?","answer":"Không. RBAC K8s quản lý quyền với Kubernetes API; ứng dụng vẫn cần authorization cho user/resource.","explanation":"ServiceAccount nên tối thiểu quyền và tránh dùng cluster-admin tùy tiện.","followUp":"Pod có cần quyền đọc mọi Secret trong cluster không?","note":"resources","level":"Đào sâu"},{"id":"ephemeral","question":"Container filesystem có thay PVC được không?","answer":"Không khi dữ liệu phải sống qua việc loại/recreate container/Pod theo mô hình lưu trữ.","explanation":"emptyDir có lifecycle theo Pod; persistence còn phụ thuộc volume/driver và policy.","followUp":"Xóa PVC có luôn giữ dữ liệu thật không?","note":"operations","level":"Đào sâu"}],"order":29},{"id":"observability","title":"Observability & Performance","group":"06 · Chất lượng & Vận hành","description":"Nối logs, metrics và traces để hiểu trải nghiệm thực tế.","sources":[{"title":"Google SRE monitoring","url":"https://sre.google/sre-book/monitoring-distributed-systems/"},{"title":"OpenTelemetry concepts","url":"https://opentelemetry.io/docs/concepts/"}],"imageRefs":["A13","D16–D17","F09","F20"],"prerequisites":["backend","testing","distributed"],"notes":[{"id":"signals","title":"Logs, metrics, traces và context","body":["Logs mô tả sự kiện; metrics gom số đo theo thời gian/labels; traces nối span của một tác vụ qua dependency. Correlation ID giúp tìm log cùng request; trace context có semantics truyền riêng. Không log secret/PII tùy ý; sampling và retention cần theo yêu cầu.","Cardinality cao như user ID trong metric label có thể làm hệ giám sát quá tải. Đưa thông tin chi tiết vào log/trace có kiểm soát khi phù hợp, dùng label giới hạn cho metrics."],"example":"","pitfall":"","exercise":"Chọn label cho metric http_requests_total mà không dùng raw URL chứa ID.","diagram":{"type":"sequence","title":"Trace request checkout","actors":["Frontend/API","Order service","Database","Payment"],"steps":[[0,1,"trace context"],[1,2,"span DB"],[2,1,"query result"],[1,3,"span payment"],[3,1,"provider response"],[1,0,"kết quả + request ID"]],"caption":"Trace cho thời gian từng dependency; log/metric bổ sung lỗi, tải và saturation."}},{"id":"slo","title":"SLI, SLO, SLA và alert","body":["SLI là số đo trải nghiệm/độ tin cậy; SLO là mục tiêu trên một window; SLA là cam kết có hệ quả theo hợp đồng. Error budget diễn đạt mức không đạt cho phép theo SLO và cách đo. Không dùng uptime process thay thành công nghiệp vụ khi hai điều khác nhau.","Alert nên hướng tới triệu chứng cần hành động, có runbook và owner. CPU cao có thể là tín hiệu điều tra; không phải lúc nào cũng cần gọi người lúc đêm nếu người dùng không bị ảnh hưởng."],"example":"","pitfall":"","exercise":"Định nghĩa SLI cho checkout: request nào là good, bad và bị loại khỏi mẫu?"},{"id":"latency","title":"Latency, percentiles và bottleneck","body":["Throughput là tốc độ hoàn thành việc; latency là thời gian một việc theo ranh giới đo. p95 nghĩa 95% quan sát không vượt giá trị đó trong tập đo; không phải latency trung bình của 95% user. Không lấy trung bình các p99 rồi coi là p99 toàn hệ.","Xem queueing, pool wait và dependency trước tối ưu CPU. Khi utilization gần giới hạn, queue delay có thể tăng mạnh. Profiling, EXPLAIN và trace cần được kết hợp theo tầng, đo trước/sau trên workload đại diện."],"example":"","pitfall":"Cache hit ratio hay CPU thấp riêng lẻ không đủ kết luận hệ khỏe.","exercise":"API p99 2 giây, DB query 20ms nhưng pool wait 1,8 giây: bạn sửa gì?"},{"id":"incident","title":"RED, USE và điều tra incident","body":["RED nhìn Rate, Errors, Duration cho service; USE nhìn Utilization, Saturation, Errors cho resource. Chúng là khung quan sát bổ trợ, không phải dashboard bắt buộc giống nhau. So timeline với deploy/config/data changes.","Incident response ưu tiên giảm ảnh hưởng, phân vai, ghi timeline và liên lạc theo quy trình. Sau đó kiểm chứng nguyên nhân và hành động cụ thể. Runbook tốt có điều kiện nhận diện, lệnh kiểm tra, giới hạn và cách xác nhận phục hồi."],"example":"","pitfall":"","exercise":"Viết runbook cho DB connection pool exhaustion; tránh tăng pool mù quáng."}],"questions":[{"id":"signals","question":"Logs, metrics và traces khác nhau thế nào?","answer":"Chúng cung cấp sự kiện chi tiết, số đo tổng hợp và hành trình tác vụ qua các bước.","explanation":"Kết hợp theo request/time/context để tránh suy từ một tín hiệu.","followUp":"Bạn tìm slow dependency bằng gì?","note":"signals","level":"Cơ bản"},{"id":"cardinality","question":"High-cardinality label gây vấn đề gì?","answer":"Tạo số series lớn, tăng bộ nhớ, chi phí và độ khó truy vấn.","explanation":"User ID hoặc raw path thường không phù hợp metric label.","followUp":"Thay /users/123 bằng route template giúp gì?","note":"signals","level":"Vận dụng"},{"id":"slo","question":"SLI, SLO và SLA khác nhau thế nào?","answer":"Số đo, mục tiêu và cam kết có hệ quả theo hợp đồng.","explanation":"Cần định nghĩa window, mẫu đo và good event rõ.","followUp":"99,9% theo request khác theo thời gian ra sao?","note":"slo","level":"Cơ bản"},{"id":"budget","question":"Error budget dùng để làm gì?","answer":"Định lượng phần không đạt mục tiêu cho phép theo SLO và hướng quyết định vận hành/release.","explanation":"Không phải quyền bỏ qua lỗi nghiêm trọng hoặc vấn đề bảo mật.","followUp":"Burn rate nhanh nên kích hoạt hành động gì?","note":"slo","level":"Vận dụng"},{"id":"p99","question":"Có thể trung bình p99 của các server để ra p99 chung không?","answer":"Không nói chung. Percentile không cộng/trung bình theo cách đó.","explanation":"Cần phân phối/histogram và cách aggregate đúng.","followUp":"Hai server có lượng request rất khác nhau ảnh hưởng gì?","note":"latency","level":"Vận dụng"},{"id":"throughput","question":"Throughput cao có bảo đảm latency thấp không?","answer":"Không. Queue có thể dài trong khi hệ vẫn hoàn thành nhiều việc.","explanation":"Cần xét tải vào, saturation, concurrency và mục tiêu latency.","followUp":"Bạn đo waiting time ở đâu?","note":"latency","level":"Vận dụng"},{"id":"nplus","question":"N+1 query là gì?","answer":"Một query lấy danh sách rồi N query lấy dữ liệu liên quan từng item.","explanation":"Có thể dùng join/batch/eager loading phù hợp, vẫn cần kiểm tra cardinality và dung lượng.","followUp":"Lấy mọi cột bằng một join khổng lồ có luôn tốt hơn không?","note":"latency","level":"Vận dụng"},{"id":"cpu","question":"API chậm nhưng CPU thấp thì điều tra gì?","answer":"Pool wait, network/DB/dependency, locks và queue trước khi tối ưu compute.","explanation":"Dùng trace chia thời gian; CPU trung bình có thể che một thread bị bão hòa.","followUp":"Event loop lag cao nhưng CPU máy chưa đầy thì sao?","note":"incident","level":"Vận dụng"},{"id":"alert","question":"Alert tốt khác dashboard metric thế nào?","answer":"Alert cần báo tình huống có thể hành động với mức khẩn phù hợp.","explanation":"Dashboard giúp khám phá; quá nhiều alert không actionable gây mệt mỏi.","followUp":"Runbook và owner có giúp giảm MTTR thế nào?","note":"slo","level":"Vận dụng"},{"id":"profile","question":"Tối ưu hiệu năng nên theo trình tự nào?","answer":"Đặt mục tiêu, đo baseline, tìm bottleneck, đổi nhỏ rồi đo và kiểm tra correctness.","explanation":"Không chọn kỹ thuật chỉ vì nghe nhanh; đo cả chi phí và failure behavior.","followUp":"Bạn làm sao tránh benchmark chỉ chạy cache nóng?","note":"latency","level":"Vận dụng"}],"order":30},{"id":"interview-skills","title":"Dự án, giao tiếp & phỏng vấn hành vi","group":"07 · Luyện tổng hợp","description":"Trình bày kinh nghiệm trung thực, có quyết định và bằng chứng.","sources":[{"title":"MDN soft skills","url":"https://developer.mozilla.org/en-US/curriculum/getting-started/soft-skills/"}],"imageRefs":[],"prerequisites":["system-design"],"notes":[{"id":"project","title":"Kể dự án bằng vấn đề và quyết định","body":["Bắt đầu với ai dùng, vấn đề gì và giới hạn. Nêu vai trò thật của bạn, kiến trúc vừa đủ để hiểu, một quyết định có lựa chọn thay thế và kết quả có bằng chứng. Nếu chưa có metric, nói rõ cách quan sát thay vì bịa phần trăm.","Dự án nhỏ vẫn có chiều sâu: validation, data integrity, accessibility, deployment và cách debug. Phân biệt việc tự làm, việc nhóm làm và điều bạn đang đề xuất nếu có thời gian thêm."],"example":"","pitfall":"","exercise":"Chuẩn bị bản giới thiệu 90 giây và bản đào sâu 5 phút cho cùng một dự án."},{"id":"star","title":"STAR cho tình huống hành vi","body":["Situation nêu bối cảnh; Task nêu trách nhiệm; Action mô tả hành động cụ thể của bạn; Result nêu kết quả và bài học. Không cần thuộc một bài văn; chuẩn bị các sự kiện thật có thể hỏi sâu.","Khi kể lỗi cá nhân, nhận phần trách nhiệm và giải thích thay đổi hệ thống để giảm lặp. Khi kể bất đồng, cho thấy bạn lắng nghe tiêu chí và dữ liệu, không chỉ “thuyết phục mọi người theo mình”."],"example":"","pitfall":"","exercise":"Viết một tình huống lỗi production: làm gì ngay, bằng chứng nào, sửa gì sau đó?"},{"id":"reasoning","title":"Trả lời kỹ thuật và nói khi chưa biết","body":["Dùng cấu trúc: định nghĩa ngắn → cơ chế → ví dụ → đánh đổi → điều kiện áp dụng. Làm rõ phiên bản hoặc giả định khi câu hỏi có nhiều đáp án. Nếu chưa biết, nói phần chắc chắn, đặt giả thuyết và mô tả cách kiểm chứng.","Trong coding/design, nói về invariant và cách kiểm tra, không đọc từng ký tự code. Khi nhận gợi ý, cập nhật lập luận rõ ràng thay vì cố bảo vệ giải pháp ban đầu."],"example":"","pitfall":"","exercise":"Trả lời “Redis có bảo đảm lock đúng không?” trong 60 giây, không dùng một chữ có/không đơn giản."},{"id":"practice","title":"Luyện theo vòng và tự đánh giá","body":["Vòng tổng hợp lấy lại câu hỏi từ topic, không tạo một kho đáp án tách rời. Trước khi mở đáp án, nói hoặc viết lời giải; tự đánh dấu chưa chắc, cần ôn hoặc đã giải thích được. Trở lại Note liên quan khi thiếu cơ chế.","Một buổi có thể gồm nền tảng, câu hỏi tình huống và một case đào sâu. Sau buổi, ghi câu sai cùng lý do, không chỉ đếm số câu đã mở. Tự chấm chỉ là phản tư, không phải chứng nhận sẵn sàng phỏng vấn."],"example":"","pitfall":"","exercise":"Chọn 10 câu Backend, ghi âm câu trả lời rồi kiểm tra thuật ngữ, ví dụ và giả định."}],"questions":[{"id":"intro","question":"Bạn giới thiệu dự án gần nhất thế nào?","answer":"Nêu vấn đề, người dùng, vai trò của mình, giải pháp chính và một kết quả có bằng chứng.","explanation":"Câu trả lời nên trung thực và mở ra điểm có thể đào sâu, không liệt kê công nghệ đơn thuần.","followUp":"Quyết định nào do chính bạn đưa ra?","note":"project","level":"Vận dụng"},{"id":"tradeoff","question":"Kể một quyết định kỹ thuật có đánh đổi.","answer":"Mô tả bối cảnh, lựa chọn thay thế, tiêu chí, quyết định và hệ quả đã quan sát.","explanation":"Không cần quyết định hoàn hảo; cần lập luận và nhận biết giới hạn.","followUp":"Điều kiện nào đổi thì bạn chọn phương án khác?","note":"project","level":"Đào sâu"},{"id":"mistake","question":"Kể về một lỗi bạn gây ra.","answer":"Chọn sự kiện thật, nói ảnh hưởng, hành động giảm thiệt hại và cách ngăn lặp.","explanation":"Nhận trách nhiệm phù hợp, không đổ hết cho người khác hoặc biến câu trả lời thành khoe khéo.","followUp":"Bạn thêm kiểm tra hay thay quy trình gì?","note":"star","level":"Vận dụng"},{"id":"conflict","question":"Bạn xử lý bất đồng với đồng đội thế nào?","answer":"Làm rõ mục tiêu/tiêu chí, nghe lý do, dùng dữ liệu hoặc thử nghiệm nhỏ và thống nhất quyết định.","explanation":"Nêu ví dụ cụ thể về hành động và kết quả; không coi mọi bất đồng là đấu thắng thua.","followUp":"Nếu quyết định cuối cùng khác ý bạn thì sao?","note":"star","level":"Vận dụng"},{"id":"unknown","question":"Không biết một câu hỏi kỹ thuật thì làm gì?","answer":"Nói giới hạn hiểu biết, trình bày phần chắc và cách suy luận/kiểm chứng.","explanation":"Không bịa guarantee hoặc số liệu; đặt câu hỏi làm rõ khi thiếu bối cảnh.","followUp":"Nguồn nào bạn sẽ tra trước?","note":"reasoning","level":"Cơ bản"},{"id":"deadline","question":"Deadline gấp mà scope lớn thì xử lý thế nào?","answer":"Làm rõ ưu tiên, chia phần có giá trị, nêu rủi ro và thương lượng scope với bằng chứng.","explanation":"Không hứa mọi thứ rồi âm thầm bỏ kiểm tra quan trọng.","followUp":"Bạn giữ những invariant nào dù giảm scope?","note":"star","level":"Vận dụng"},{"id":"review","question":"Nhận code review khó nghe thì phản hồi sao?","answer":"Tách nội dung kỹ thuật khỏi cảm xúc, hỏi tiêu chí và kiểm chứng đề xuất.","explanation":"Chấp nhận sửa khi có lý do, giải thích trade-off bằng dữ liệu khi không đồng ý.","followUp":"Bạn ghi lại quyết định thế nào?","note":"star","level":"Vận dụng"},{"id":"impact","question":"Không có metric đẹp thì kể kết quả thế nào?","answer":"Dùng bằng chứng thật như lỗi được ngăn, quy trình rõ hơn hoặc thời gian thao tác quan sát được.","explanation":"Nói rõ giới hạn đo; không bịa phần trăm tăng trưởng.","followUp":"Bạn sẽ đo tốt hơn lần sau bằng cách nào?","note":"project","level":"Vận dụng"},{"id":"learn","question":"Bạn học một công nghệ mới như thế nào?","answer":"Bắt đầu từ mục tiêu, tài liệu chính thức, ví dụ nhỏ và kiểm tra failure mode.","explanation":"Liên hệ concept đã biết nhưng kiểm chứng khác biệt; ghi note bằng lời mình.","followUp":"Bạn biết mình đã hiểu bằng cách nào?","note":"reasoning","level":"Vận dụng"},{"id":"readiness","question":"Đọc hết đáp án có nghĩa sẵn sàng phỏng vấn chưa?","answer":"Chưa. Cần tự giải thích, làm bài không nhìn đáp án và ứng phó biến thể.","explanation":"Buổi tổng hợp giúp lộ lỗ hổng; quay về Note để sửa cơ chế hiểu sai.","followUp":"Bạn tự chấm một câu trả lời tốt bằng tiêu chí gì?","note":"practice","level":"Vận dụng"}],"order":31}]};
